function notionTextFragmentsFromString(value, chunkSize = 1800) {
  const text = String(value || "").replace(/\r\n/g, "\n").trim();
  if (!text) return [];

  const out = [];
  for (let i = 0; i < text.length; i += chunkSize) {
    out.push({ text: { content: text.slice(i, i + chunkSize) } });
  }
  return out;
}

function buildWritableTextPropValue(propName, propType, value) {
  if (!propName) return null;
  const type = String(propType || "").trim();
  const fragments = notionTextFragmentsFromString(value);

  if (type === "title") return { [propName]: { title: fragments } };
  if (type === "rich_text") return { [propName]: { rich_text: fragments } };
  if (type === "select") {
    const clean = String(value || "").trim();
    return { [propName]: { select: clean ? { name: clean } : null } };
  }
  if (type === "status") {
    const clean = String(value || "").trim();
    return { [propName]: { status: clean ? { name: clean } : null } };
  }
  return null;
}

function notionPropPlainText(prop) {
  try {
    if (!prop) return "";
    if (prop.type === "rich_text") {
      return (prop.rich_text || []).map((x) => x?.plain_text || "").join("").trim();
    }
    if (prop.type === "title") {
      return (prop.title || []).map((x) => x?.plain_text || "").join("").trim();
    }
    if (prop.type === "select") return String(prop.select?.name || "").trim();
    if (prop.type === "status") return String(prop.status?.name || "").trim();
    if (prop.type === "number" && (prop.number === 0 || typeof prop.number === "number")) {
      return String(prop.number);
    }
    if (prop.type === "multi_select") {
      return (prop.multi_select || [])
        .map((x) => String(x?.name || "").trim())
        .filter(Boolean)
        .join(", ");
    }
  } catch {}
  return "";
}

function notionPropRelationIds(prop) {
  try {
    if (!prop || prop.type !== "relation") return [];
    return (prop.relation || []).map((x) => x?.id).filter(Boolean);
  } catch {
    return [];
  }
}

function notionSelectOrStatusOptions(propMeta) {
  try {
    if (!propMeta) return [];
    if (propMeta.type === "status") return Array.isArray(propMeta.status?.options) ? propMeta.status.options : [];
    if (propMeta.type === "select") return Array.isArray(propMeta.select?.options) ? propMeta.select.options : [];
    return [];
  } catch {
    return [];
  }
}

function notionExactOptionName(propMeta, desired, fallback = "") {
  const wanted = String(desired || "").trim();
  if (!wanted) return String(fallback || "").trim();
  const options = notionSelectOrStatusOptions(propMeta);
  if (!options.length) return wanted;

  const normalized = normKey(wanted);
  const exact = options.find((opt) => normKey(opt?.name) === normalized);
  if (exact?.name) return exact.name;

  const partial = options.find((opt) => normKey(opt?.name).includes(normalized));
  if (partial?.name) return partial.name;

  return String(fallback || wanted).trim();
}

function isSparePartsTagName(value) {
  const key = normKey(value);
  return key === normKey("Spare Parts") || key === normKey("Spare Part") || key === "spareparts";
}

function isMaintenanceSparePartPlaceholderName(value) {
  const key = normKey(value);
  return !key || key === "selectcomponent" || key === "selectsparepart" || key === "nosparepartselected";
}


async function listMaintenanceReplacementProducts() {
  if (_sbProductsEnabled()) {
    const list = await _sbProductsList();
    const out = (Array.isArray(list) ? list : [])
      .map((product) => ({
        id: String(product?.id || "").trim(),
        name: String(product?.name || "").trim(),
        displayId: String(product?.displayId || product?.idCode || "").trim(),
        unitPrice: Number.isFinite(Number(product?.unitPrice)) ? Number(product.unitPrice) : 0,
        url: product?.url || null,
        tags: Array.isArray(product?.tags) ? product.tags : _sbSplitValues(product?.tags),
      }))
      .filter((product) => product.id && product.name);
    out.sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), undefined, {
      sensitivity: "base",
      numeric: true,
    }));
    return out;
  }
  return listSparePartsComponents();
}

function _normalizeMaintenanceSparePartEntries(value, lookups = {}) {
  const entries = [];
  const seen = new Set();
  const byId = lookups?.byId || new Map();
  const byName = lookups?.byName || new Map();

  const add = (entry = {}) => {
    const id = String(entry?.id ?? entry?.productId ?? entry?.sparePartId ?? entry?.value ?? "").trim();
    let rawName = String(entry?.name ?? entry?.label ?? entry?.component ?? entry?.sparePartName ?? "").trim();
    let qty = Number(entry?.qty ?? entry?.quantity ?? entry?.count ?? 1);
    if (!Number.isFinite(qty) || qty <= 0) qty = 1;
    qty = Math.max(1, Math.round(qty));

    const fromId = id ? byId.get(id) : null;
    if (!rawName && fromId?.name) rawName = fromId.name;

    const qtyMatch = rawName.match(/(?:\s*[x×]\s*|\s*\(\s*qty\s*:?\s*)(\d+(?:\.\d+)?)\s*\)?\s*$/i);
    if (qtyMatch) {
      const parsedQty = Number(qtyMatch[1]);
      if (Number.isFinite(parsedQty) && parsedQty > 0) qty = Math.max(1, Math.round(parsedQty));
      rawName = rawName.slice(0, qtyMatch.index).trim();
    }

    if (!id && isMaintenanceSparePartPlaceholderName(rawName)) return;

    const fromName = rawName ? byName.get(normKey(rawName)) : null;
    const product = fromId || fromName || null;
    const name = String(product?.name || rawName || "").trim();
    if (!name || (!id && isMaintenanceSparePartPlaceholderName(name))) return;
    const finalId = String(product?.id || id || "").trim();
    const key = `${finalId || normKey(name)}|${qty}`;
    if (seen.has(key)) return;
    seen.add(key);
    entries.push({
      id: finalId,
      name,
      qty,
      displayId: String(product?.displayId || product?.idCode || "").trim(),
      unitPrice: Number.isFinite(Number(product?.unitPrice)) ? Number(product.unitPrice) : 0,
      url: product?.url || null,
    });
  };

  if (Array.isArray(value)) {
    value.forEach(add);
    return entries;
  }

  if (value && typeof value === "object") {
    if (Array.isArray(value.items)) value.items.forEach(add);
    else add(value);
    return entries;
  }

  const raw = String(value || "").trim();
  if (!raw) return entries;
  try {
    const parsed = JSON.parse(raw);
    return _normalizeMaintenanceSparePartEntries(parsed, lookups);
  } catch {}

  raw.split(/[,\n]+/).map((part) => part.trim()).filter(Boolean).forEach((name) => add({ name }));
  return entries;
}

function _maintenanceSparePartEntriesToText(entries = []) {
  return (Array.isArray(entries) ? entries : [])
    .map((entry) => {
      const name = String(entry?.name || "").trim();
      if (!name) return "";
      const qty = Number.isFinite(Number(entry?.qty)) ? Math.max(1, Math.round(Number(entry.qty))) : 1;
      return qty > 1 ? `${name} x${qty}` : name;
    })
    .filter(Boolean)
    .join(", ");
}

async function listSparePartsComponents() {
  // Supabase-first: products are now the canonical source after migration.
  // We keep the Notion branch below for legacy deployments only.
  if (_sbProductsEnabled()) {
    try {
      const list = await _sbProductsList();
      const out = (Array.isArray(list) ? list : [])
        .map((product) => ({
          id: String(product?.id || "").trim(),
          name: String(product?.name || "").trim(),
          tags: Array.isArray(product?.tags) ? product.tags : _sbSplitValues(product?.tags),
        }))
        .filter((product) => product.id && product.name && product.tags.some(isSparePartsTagName));
      out.sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), undefined, {
        sensitivity: "base",
        numeric: true,
      }));
      return out;
    } catch (error) {
      console.warn("[supabase] spare-parts list failed, falling back to Notion:", error?.message || error);
    }
  }

  if (!componentsDatabaseId) return [];

  const out = [];
  let hasMore = true;
  let startCursor = undefined;

  const getPropInsensitive = (props, name) => {
    if (!props) return null;
    if (props[name]) return props[name];
    const target = normKey(name);
    for (const [k, v] of Object.entries(props || {})) {
      if (normKey(k) === target) return v;
    }
    return null;
  };

  while (hasMore) {
    const response = await notion.databases.query({
      database_id: componentsDatabaseId,
      start_cursor: startCursor,
      page_size: 100,
      sorts: [{ timestamp: "created_time", direction: "descending" }],
    });

    for (const page of response.results || []) {
      const props = page.properties || {};
      const tagsProp =
        getPropInsensitive(props, "Tags") ||
        getPropInsensitive(props, "Tag");

      const tags = [];
      try {
        if (tagsProp?.type === "multi_select") {
          for (const item of tagsProp.multi_select || []) {
            const name = String(item?.name || "").trim();
            if (name) tags.push(name);
          }
        } else if (tagsProp?.type === "select") {
          const name = String(tagsProp.select?.name || "").trim();
          if (name) tags.push(name);
        }
      } catch {}

      if (!tags.some(isSparePartsTagName)) continue;

      const titlePropName = firstTitlePropName(props);
      const name = titlePropName
        ? (props[titlePropName]?.title || []).map((x) => x?.plain_text || "").join("").trim()
        : "";

      if (!name) continue;

      out.push({
        id: page.id,
        name,
        tags,
      });
    }

    hasMore = !!response.has_more;
    startCursor = response.next_cursor || undefined;
  }

  out.sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), undefined, {
    sensitivity: "base",
    numeric: true,
  }));
  return out;
}

