// App download/install links for the profile menu
app.get("/api/app-download-links", requireAuth, (req, res) => {
  res.set("Cache-Control", "no-store");

  function cleanDownloadUrl(value) {
    const raw = String(value || "").trim();
    if (!raw) return "";

    // Ignore documentation placeholders that may have been copied into Vercel env vars.
    const lower = raw.toLowerCase();
    const placeholderFragments = [
      "your-android-download-link",
      "your-windows-download-link",
      "your-download-link",
      "your-app-link",
      "yourdomain.com",
      "example.com",
      "https://your-",
      "http://your-",
    ];
    if (placeholderFragments.some((part) => lower.includes(part))) return "";

    // Absolute URLs are safe to open directly. Relative URLs are also allowed for
    // files hosted under the same Vercel deployment, for example /downloads/app.apk.
    if (/^https?:\/\//i.test(raw) || raw.startsWith("/")) return raw;
    return "";
  }

  const forwardedProto = String(req.get("x-forwarded-proto") || "").split(",")[0].trim();
  const proto = forwardedProto || req.protocol || "https";
  const host = req.get("host") || "";
  const origin = host ? `${proto}://${host}` : "";

  const androidUrl = cleanDownloadUrl(
    process.env.ANDROID_APP_DOWNLOAD_URL ||
    process.env.APP_ANDROID_URL ||
    process.env.APK_DOWNLOAD_URL ||
    ""
  );

  const windowsUrl = cleanDownloadUrl(
    process.env.WINDOWS_APP_DOWNLOAD_URL ||
    process.env.APP_WINDOWS_URL ||
    process.env.WINDOWS_SETUP_URL ||
    ""
  );

  const nextFrontendEnabled = ["1", "true", "yes", "on"].includes(
    String(process.env.ENABLE_NEXT_FRONTEND || "").trim().toLowerCase(),
  );
  const pwaStartPath = nextFrontendEnabled ? "/next/pwa-start" : "/pwa-start";
  const installPagePath = nextFrontendEnabled ? "/next/app-install" : "/pwa-start";

  res.json({
    androidUrl,
    windowsUrl,
    pwaUrl: origin ? `${origin}${pwaStartPath}` : pwaStartPath,
    manifestUrl: origin ? `${origin}/manifest.webmanifest` : "/manifest.webmanifest",
    pwaStartUrl: origin ? `${origin}${pwaStartPath}` : pwaStartPath,
    installPageUrl: origin ? `${origin}${installPagePath}` : installPagePath,
    installMode: "pwa",
  });
});

// Account info (returns fresh allowedPages)
app.get("/api/account", requireAuth, async (req, res) => {
  const hasSupabaseSession = !!req.session?.userSupabaseId && _sbTeamMembersEnabled();
  if (!teamMembersDatabaseId && !hasSupabaseSession && !_sbTeamMembersEnabled()) {
    return res.status(500).json({ error: "Team_Members database ID or Supabase Team Members table is not configured." });
  }

  res.set("Cache-Control", "no-store");
  const ACCOUNT_CACHE_TTL_MS = 2 * 60 * 1000;
  const withLmsAccess = async (payload) => {
    try {
      const cachedAccess = req.session?.lmsAccessCache;
      const cachedAt = Number(req.session?.lmsAccessCacheTs || 0);
      if (cachedAccess && cachedAt && Date.now() - cachedAt < 30_000) {
        return { ...(payload || {}), lmsAccess: cachedAccess };
      }
      const lmsAccess = await _sbLmsSessionAccessPayload(req);
      try {
        req.session.lmsAccessCache = lmsAccess;
        req.session.lmsAccessCacheTs = Date.now();
      } catch {}
      return { ...(payload || {}), lmsAccess };
    } catch (error) {
      console.warn("Account LMS access summary unavailable:", error?.details || error?.message || error);
      return payload;
    }
  };
  try {
    const cached = req.session?.accountCache;
    const ts = Number(req.session?.accountCacheTs || 0);
    // Page permissions are operational controls. For Supabase users, always
    // refresh them so a permission granted in Users Center appears immediately
    // instead of waiting for the previous two-minute account-cache window.
    if (!(_sbTeamMembersEnabled() && req.session?.userSupabaseId) && cached && ts && Date.now() - ts < ACCOUNT_CACHE_TTL_MS && Array.isArray(cached.filesMedia) && cached.pageAccess) {
      return res.json(await withLmsAccess(cached));
    }
  } catch {}

  if (_sbTeamMembersEnabled() && req.session?.userSupabaseId) {
    try {
      const accessBundle = await _sbCachedAccountPayloadWithAccessForMember(
        req.session.userSupabaseId,
        req.session.username || "",
      );
      if (accessBundle?.accountPayload) {
        const { accountPayload: data, allowedNormalized, pageAccessRows } = accessBundle;
        try {
          req.session.username = data.username || req.session.username || "";
          req.session.allowedPages = allowedNormalized;
          req.session.pageAccess = pageAccessRows;
          req.session.accountCache = data;
          req.session.accountCacheTs = Date.now();
        } catch {}
        return res.json(await withLmsAccess(data));
      }
    } catch (error) {
      console.error("Error fetching account from Supabase:", error?.details || error);
    }
  }

  try {
    const userId = await getSessionUserNotionId(req);
    if (!userId) return res.status(404).json({ error: "User not found." });

    const accountCacheKey = `cache:api:account:${normalizeNotionId(userId)}:v4`;
    const data = await cacheGetOrSet(accountCacheKey, 5 * 60, async () => {
      const userPage = await notion.pages.retrieve({ page_id: userId });
      const p = userPage.properties || {};

      const freshAllowed = extractAllowedPages(p);
      const allowedUI = expandAllowedForUI(freshAllowed);

      return {
        name: p?.Name?.title?.[0]?.plain_text || "",
        username: req.session.username || "",
        department: p?.Department?.select?.name || "",
        position: p?.Position?.select?.name || "",
        photoUrl: extractProfilePhotoUrlFromProps(p) || "",
        coverPhotoUrl: "",
        phone: p?.Phone?.phone_number || "",
        email: p?.Email?.email || "",
        employeeCode: p?.["Employee Code"]?.number ?? null,
        filesMedia: extractFilesMediaFromProps(p),
        passwordSet: (_extractPropText(p?.Password) ?? null) !== null,
        allowedPages: allowedUI,
        pageAccess: { pages: _legacyPageAccessRowsFromAllowed(freshAllowed) },
      };
    });

    try {
      req.session.allowedPages = Array.isArray(data?.allowedPages) ? data.allowedPages : [];
      req.session.pageAccess = Array.isArray(data?.pageAccess?.pages) ? data.pageAccess.pages : _legacyPageAccessRowsFromAllowed(req.session.allowedPages);
      req.session.accountCache = data;
      req.session.accountCacheTs = Date.now();
    } catch {}

    return res.json(await withLmsAccess(data));
  } catch (error) {
    console.error("Error fetching account:", error.body || error);
    res.status(500).json({ error: "Failed to fetch account info." });
  }
});




function _sbPublicProfileFilesFromValue(value) {
  const entries = _sbParseScreenshotEntries(value)
    .map((entry, index) => ({
      name: String(entry?.name || `File ${index + 1}`).trim() || `File ${index + 1}`,
      url: String(entry?.url || '').trim(),
    }))
    .filter((entry) => entry.name || entry.url);
  return entries;
}

function _sbSerializeTeamMemberPublicProfile(row = {}) {
  const base = _sbSerializeTeamMemberRow(row);
  const publicProfileDisplayOrder = [
    'Name',
    'Department',
    'Position',
    'Phone',
    'Email',
    'Employee Code',
  ];

  const fields = publicProfileDisplayOrder
    .map((label) => ({
      label,
      value: _sbString(_sbValueForLabel(row, label)),
      type: label === 'Email' ? 'email' : (label === 'Phone' ? 'phone_number' : 'text'),
      files: [],
    }))
    .filter((field) => String(field.value || '').trim());

  const filesMedia = _sbPublicProfileFilesFromValue(_sbValueForLabel(row, 'Files & media'));

  return {
    id: base.id,
    name: base.name,
    username: base.name,
    department: base.department,
    position: base.position,
    phone: base.phone,
    email: base.email,
    employeeCode: base.employeeCode,
    photoUrl: base.photoUrl,
    coverPhotoUrl: base.coverPhotoUrl || "",
    filesMedia,
    fields,
    source: 'supabase',
  };
}

async function _sbFindTeamMemberForPublicProfile(rawId = '') {
  const raw = String(rawId || '').trim();
  if (!raw || !_sbTeamMembersEnabled()) return null;

  const byId = await _sbFindTeamMemberById(raw).catch(() => null);
  if (byId) return byId;

  const target = norm(raw);
  if (!target) return null;
  const rows = await _sbSelectTeamMembersRows();
  return (rows || []).find((row) => {
    const id = norm(_sbGet(row, ['id', 'ID']));
    const name = norm(_sbValueForLabel(row, 'Name'));
    const code = norm(_sbValueForLabel(row, 'Employee Code'));
    const email = norm(_sbValueForLabel(row, 'Email'));
    return (id && id === target) ||
      (name && (name === target || name.includes(target) || target.includes(name))) ||
      (code && code === target) ||
      (email && email === target);
  }) || null;
}





app.get("/api/team-members/:id/public", requireAuth, async (req, res) => {
  try {
    const rawId = String(req.params?.id || "").trim();
    if (!rawId) return res.status(400).json({ error: "Team member ID is required." });

    res.set("Cache-Control", "no-store");

    if (_sbTeamMembersEnabled()) {
      const cacheKey = `cache:api:team-member-public:supabase:${cacheKeySafe(rawId)}:v1`;
      const profile = await cacheGetOrSet(cacheKey, 2 * 60, async () => {
        const row = await _sbFindTeamMemberForPublicProfile(rawId);
        if (!row) {
          const err = new Error("Team member not found.");
          err.statusCode = 404;
          throw err;
        }
        return _sbSerializeTeamMemberPublicProfile(row);
      });
      return res.json(profile);
    }

    if (!teamMembersDatabaseId) {
      return res.status(500).json({ error: "Team_Members database ID is not configured." });
    }

    const cacheKey = `cache:api:team-member-public:${normalizeNotionId(rawId)}:v2`;
    const profile = await cacheGetOrSet(cacheKey, 5 * 60, async () => {
      const page = await notion.pages.retrieve({ page_id: rawId });

      const parentDb = page?.parent?.database_id || "";
      if (
        parentDb &&
        teamMembersDatabaseId &&
        normalizeNotionId(parentDb) !== normalizeNotionId(teamMembersDatabaseId)
      ) {
        const err = new Error("Team member not found.");
        err.statusCode = 404;
        throw err;
      }

      return await serializeTeamMemberPublicProfile(page);
    });

    return res.json(profile);
  } catch (error) {
    const status = Number(error?.statusCode) || Number(error?.status) || 500;
    if (status === 404) return res.status(404).json({ error: "Team member not found." });
    console.error("GET /api/team-members/:id/public error:", error?.body || error);
    return res.status(500).json({ error: "Failed to load team member profile." });
  }
});


function withTimeoutResult(promise, ms, fallbackValue) {
  return Promise.race([
    Promise.resolve(promise),
    new Promise((resolve) => setTimeout(() => resolve(fallbackValue), Math.max(1000, Number(ms) || 1000))),
  ]);
}

