// User Access & Data — Upload profile/media files to Supabase Storage and return public URLs
app.post(
  "/api/user-access/upload-file",
  requireAuth,
  async (req, res) => {
    res.set("Cache-Control", "no-store");
    try {
      if (!_uaAdminVerified(req)) {
        return res.status(403).json({ ok: false, error: "Admin verification expired. Please enter the Admin password first." });
      }
      const { dataUrl, filename, kind } = req.body || {};
      if (!dataUrl) return res.status(400).json({ ok: false, error: "File data is required." });
      const { mime, buf } = parseDataUrlToBuffer(dataUrl);
      const uploadKind = String(kind || "file").toLowerCase();
      if (uploadKind.includes("profile") && !/^image\//i.test(String(mime || ""))) {
        return res.status(400).json({ ok: false, error: "Profile picture must be an image." });
      }
      if (buf.length > 12 * 1024 * 1024) {
        return res.status(413).json({ ok: false, error: "File is too large. Maximum size is 12MB." });
      }
      const safeOriginalName = String(filename || "upload.bin").trim() || "upload.bin";
      const cleanName = safeOriginalName.replace(/[^a-z0-9._-]/gi, "_");
      const blobName = `team-members/${uploadKind || "file"}/${Date.now()}-${Math.random().toString(16).slice(2)}-${cleanName}`;
      const publicUrl = await uploadToBlobFromBase64(dataUrl, blobName);
      return res.json({ ok: true, url: publicUrl, name: safeOriginalName, mime });
    } catch (error) {
      console.error("POST /api/user-access/upload-file error:", error?.details || error?.body || error);
      const message = String(error?.message || "") === "SUPABASE_STORAGE_OR_BLOB_TOKEN_MISSING"
        ? "Supabase Storage is not configured. Add SUPABASE_STORAGE_BUCKET in Vercel, or add BLOB_READ_WRITE_TOKEN as fallback."
        : (error?.message || "Failed to upload file.");
      return res.status(error?.status || 500).json({ ok: false, error: message });
    }
  },
);


// LMS User Center — separate page catalog and access matrix for LMS workspace pages.
function _sbSerializeLmsPage(row = {}) {
  const id = _sbGet(row, ["id", "page_id", "ID"]);
  return {
    id: String(id ?? ""),
    pageId: String(id ?? ""),
    pageKey: _sbString(_sbGet(row, ["page_key", "pageKey"])) || "",
    pageName: _sbString(_sbGet(row, ["page_name", "pageName", "name"])) || "",
    routePath: _sbString(_sbGet(row, ["route_path", "routePath"])) || "",
    routePattern: _sbString(_sbGet(row, ["route_pattern", "routePattern"])) || "",
    moduleName: _sbString(_sbGet(row, ["module_name", "moduleName"])) || "LMS",
    parentPageKey: _sbString(_sbGet(row, ["parent_page_key", "parentPageKey"])) || "",
    sortOrder: Number(_sbGet(row, ["sort_order", "sortOrder"]) || 100),
    isActive: _sbBool(_sbGet(row, ["is_active", "isActive"]), true),
    isAssignable: _sbBool(_sbGet(row, ["is_assignable", "isAssignable"]), true),
    visibleInSidebar: _sbBool(_sbGet(row, ["visible_in_sidebar", "visibleInSidebar"]), true),
  };
}

async function _sbSelectLmsPages({ assignableOnly = true, activeOnly = true } = {}) {
  const cacheKey = SUPABASE_CACHE_KEYS.lmsPages(assignableOnly, activeOnly);
  return await cacheGetOrSet(cacheKey, SUPABASE_CACHE_TTL.LMS_PAGES, async () => {
    const params = ["select=*", "order=sort_order.asc", "limit=1000"];
    if (activeOnly) params.push("is_active=eq.true");
    if (assignableOnly) params.push("is_assignable=eq.true");
    const rows = await supabaseDb.request(`/lms_pages?${params.join("&")}`);
    return (Array.isArray(rows) ? rows : []).map(_sbSerializeLmsPage).filter((page) => page.id && page.pageKey && page.pageName);
  }, { memoryTtlSeconds: 60 });
}

async function _sbSelectRawLmsPageAccessForMember(teamMemberId) {
  const id = String(teamMemberId || "").trim();
  if (!id) return [];
  return await cacheGetOrSet(SUPABASE_CACHE_KEYS.lmsPageAccessMember(id), SUPABASE_CACHE_TTL.LMS_MEMBER_PAGE_ACCESS, async () => {
    const rows = await supabaseDb.request(`/team_member_lms_page_access?select=*&team_member_id=eq.${_sbRestFilterValue(id)}&limit=1000`);
    return Array.isArray(rows) ? rows : [];
  }, { memoryTtlSeconds: 5 });
}

function requireLmsPageAccess(pageKey) {
  return async (req, res, next) => {
    try {
      if (_sessionIsBuiltInAdmin(req)) return next();
      const memberId = String(req.session?.userSupabaseId || "").trim();
      if (!memberId) return res.status(403).send("Access denied.");

      // The old guard made two Supabase requests on every LMS page opening.
      // Reuse the cached page catalog and the member's short-lived permission
      // matrix instead; permission saves explicitly invalidate both caches.
      const [pages, accessRows] = await Promise.all([
        _sbSelectLmsPages({ assignableOnly: false, activeOnly: true }),
        _sbSelectRawLmsPageAccessForMember(memberId),
      ]);
      const wantedKey = String(pageKey || "").trim().toLowerCase();
      const page = (pages || []).find((item) => String(item?.pageKey || "").trim().toLowerCase() === wantedKey);
      const pageId = String(page?.pageId || page?.id || "").trim();
      if (!pageId) return res.status(403).send("LMS page is not available.");

      const allowed = (accessRows || []).some((row) =>
        String(_sbGet(row, ["page_id", "pageId"]) ?? "").trim() === pageId &&
        _sbBool(_sbGet(row, ["is_enabled", "isEnabled"]), false)
      );
      if (!allowed) return res.status(403).send("Access denied.");
      return next();
    } catch (error) {
      console.error("LMS page access check failed:", error?.details || error?.body || error);
      return res.status(error?.status || 500).send("Unable to verify LMS access.");
    }
  };
}

function _sbLmsPageAccessSummary(rows = []) {
  const enabled = (rows || []).filter((row) => _sbBool(_sbGet(row, ["is_enabled", "isEnabled"]), false));
  return {
    allowedPages: enabled.map((row) => String(_sbGet(row, ["page_name", "pageName"]) || "").trim()).filter(Boolean),
    accessCount: enabled.length,
    adminCount: enabled.filter((row) => _sbNormalizePageAccessLevel(_sbGet(row, ["access_level", "accessLevel"])) === PAGE_ACCESS_LEVELS.ADMIN).length,
  };
}

async function _sbLmsPageAccessPayloadForMember(teamMemberId) {
  const [pages, accessRows] = await Promise.all([
    _sbSelectLmsPages({ assignableOnly: true }),
    _sbSelectRawLmsPageAccessForMember(teamMemberId).catch(() => []),
  ]);
  const byPageId = new Map((accessRows || []).map((row) => [String(_sbGet(row, ["page_id", "pageId"]) ?? ""), row]));
  const items = pages.map((page) => {
    const access = byPageId.get(String(page.pageId || page.id));
    return {
      ...page,
      accessId: String(_sbGet(access || {}, ["id", "access_id", "accessId"]) ?? ""),
      accessLevel: _sbNormalizePageAccessLevel(_sbGet(access || {}, ["access_level", "accessLevel"]) || "edit"),
      isEnabled: access ? _sbBool(_sbGet(access, ["is_enabled", "isEnabled"]), false) : false,
    };
  });
  return {
    pages: items,
    summary: _sbLmsPageAccessSummary(items.map((item) => ({ ...item, page_name: item.pageName, is_enabled: item.isEnabled, access_level: item.accessLevel }))),
  };
}

async function _sbSaveLmsPageAccessForMember(teamMemberId, entries = [], { teamMemberName = "", grantedBy = "" } = {}) {
  const memberId = String(teamMemberId || "").trim();
  if (!memberId) {
    const error = new Error("Missing team member ID.");
    error.status = 400;
    throw error;
  }
  const pages = await _sbSelectLmsPages({ assignableOnly: true });
  const pagesById = new Map(pages.map((page) => [String(page.pageId || page.id), page]));
  const pagesByKey = new Map(pages.map((page) => [String(page.pageKey), page]));
  const cleanEntries = _sbNormalizePageAccessEntries(entries);
  const writeRows = [];
  for (const entry of cleanEntries) {
    if (!entry.isEnabled) continue;
    const page = (entry.pageId && pagesById.get(entry.pageId)) || (entry.pageKey && pagesByKey.get(entry.pageKey));
    if (!page) continue;
    writeRows.push({
      team_member_id: Number(memberId),
      team_member_name: teamMemberName || null,
      page_id: Number(page.pageId || page.id),
      access_level: _sbNormalizePageAccessLevel(entry.accessLevel),
      is_enabled: true,
      granted_by: grantedBy || null,
    });
  }
  if (cleanEntries.length && !writeRows.length && cleanEntries.some((entry) => entry.isEnabled)) {
    const error = new Error("No valid LMS pages were received. Reload the page and try again.");
    error.status = 400;
    throw error;
  }
  await supabaseDb.request(`/team_member_lms_page_access?team_member_id=eq.${_sbRestFilterValue(memberId)}`, {
    method: "DELETE",
    headers: { Prefer: "return=minimal" },
  });
  if (!writeRows.length) {
    await clearSupabaseMemberAccessCaches(memberId, { includeLms: true, includeDirectory: false });
    return [];
  }
  const created = await supabaseDb.request('/team_member_lms_page_access', {
    method: "POST",
    headers: { Prefer: "return=representation" },
    body: writeRows,
  });
  await clearSupabaseMemberAccessCaches(memberId, { includeLms: true, includeDirectory: false });
  return Array.isArray(created) ? created : [];
}


// LMS Home overview — aggregate LMS-only data for the LMS dashboard.
async function _sbLmsHomeOverviewPayload({ force = false } = {}) {
  const load = async () => {
    const readRows = async (table, query = "select=id&limit=10000") => {
      try {
        const rows = await supabaseDb.request(`/${table}?${query}`);
        return Array.isArray(rows) ? rows : [];
      } catch (error) {
        console.warn(`LMS Home: unable to read ${table}:`, error?.details || error?.body || error?.message || error);
        return [];
      }
    };

    const roleTables = {
      supervisors: "lms_supervisors",
      team_leaders: "lms_team_leaders",
      instructors: "lms_instructors",
      co_instructors: "lms_co_instructors",
      school_coordinators: "lms_school_coordinators",
      students: "lms_students",
      parents: "lms_parents",
    };
    const [schools, structures, curriculumGroups, recentCurricula, themes, resources, ...roleRows] = await Promise.all([
      readRows("b2b_schools"),
      readRows("lms_structures"),
      readRows("lms_curriculum_groups"),
      readRows("lms_curricula", "select=*&order=created_at.desc&limit=5"),
      readRows("lms_curricula"),
      readRows("lms_curriculum_resources", "select=id,resource_type&limit=10000"),
      ...Object.values(roleTables).map((table) => readRows(table)),
    ]);
    const roles = {};
    Object.keys(roleTables).forEach((key, index) => { roles[key] = roleRows[index]?.length || 0; });
    const resourceTypes = { book: 0, teacher_guide: 0, lesson_plan: 0, presentation: 0, materials: 0, exam: 0 };
    resources.forEach((row) => {
      const key = String(row?.resource_type || "").trim().toLowerCase();
      if (Object.prototype.hasOwnProperty.call(resourceTypes, key)) resourceTypes[key] += 1;
    });
    return {
      ok: true,
      counts: {
        schools: schools.length,
        people: Object.values(roles).reduce((sum, value) => sum + Number(value || 0), 0),
        structures: structures.length,
        curricula: curriculumGroups.length,
        themes: themes.length,
        resources: resources.length,
      },
      roles,
      resourceTypes,
      recentCurricula,
    };
  };

  if (force) return load();
  return cacheGetOrSet("cache:api:lms-home:overview:v2", 60, load, { memoryTtlSeconds: 15 });
}

async function _sbLmsSessionAccessPayload(req) {
  const pages = await _sbSelectLmsPages({ assignableOnly: false, activeOnly: true });
  const isBuiltInAdmin = _sessionIsBuiltInAdmin(req);
  const memberId = String(req.session?.userSupabaseId || "").trim();
  let accessRows = [];
  if (!isBuiltInAdmin && memberId) {
    accessRows = await _sbSelectRawLmsPageAccessForMember(memberId).catch(() => []);
  }
  const byPageId = new Map((accessRows || []).map((row) => [String(_sbGet(row, ["page_id", "pageId"]) ?? ""), row]));
  const visiblePages = (pages || []).map((page) => {
    const access = byPageId.get(String(page.pageId || page.id));
    const isEnabled = isBuiltInAdmin || (access && _sbBool(_sbGet(access, ["is_enabled", "isEnabled"]), false));
    return {
      ...page,
      isEnabled: !!isEnabled,
      accessLevel: isBuiltInAdmin
        ? PAGE_ACCESS_LEVELS.ADMIN
        : _sbNormalizePageAccessLevel(_sbGet(access || {}, ["access_level", "accessLevel"]) || PAGE_ACCESS_LEVELS.VIEW),
    };
  }).filter((page) => page.isEnabled);

  return {
    ok: true,
    source: "supabase",
    isBuiltInAdmin,
    pages: visiblePages,
    summary: {
      accessCount: visiblePages.length,
      adminCount: visiblePages.filter((page) => page.accessLevel === PAGE_ACCESS_LEVELS.ADMIN).length,
    },
  };
}

