const LMS_CURRICULUM_MAX_FILE_BYTES = 500 * 1024 * 1024;
const LMS_CURRICULUM_STORAGE_BUCKET = String(process.env.SUPABASE_LMS_CURRICULUM_BUCKET || "lms-curriculum").trim() || "lms-curriculum";
const LMS_CURRICULUM_DIRECT_PDF_URL_SECONDS = 30 * 60;
const LMS_CURRICULUM_DIRECT_PREVIEW_URL_SECONDS = 10 * 60;
const LMS_CURRICULUM_SIGNED_URL_CACHE_LIMIT = 4000;
const lmsCurriculumSignedUrlCache = new Map();

function _lmsCurriculumSignedUrlCacheKey(bucketName, objectPath) {
  return `${String(bucketName || "").trim()}::${String(objectPath || "").trim()}`;
}

function _lmsCurriculumTrimSignedUrlCache() {
  const now = Date.now();
  for (const [key, entry] of lmsCurriculumSignedUrlCache.entries()) {
    if (!entry?.signedUrl || Number(entry.expiresAt || 0) <= now + 30_000) {
      lmsCurriculumSignedUrlCache.delete(key);
    }
  }
  while (lmsCurriculumSignedUrlCache.size > LMS_CURRICULUM_SIGNED_URL_CACHE_LIMIT) {
    lmsCurriculumSignedUrlCache.delete(lmsCurriculumSignedUrlCache.keys().next().value);
  }
}

async function _lmsCurriculumCreateCachedSignedDownloadUrl(objectPath, {
  bucketName = LMS_CURRICULUM_STORAGE_BUCKET,
  expiresIn = LMS_CURRICULUM_DIRECT_PREVIEW_URL_SECONDS,
} = {}) {
  const cleanBucket = String(bucketName || LMS_CURRICULUM_STORAGE_BUCKET).trim() || LMS_CURRICULUM_STORAGE_BUCKET;
  const cleanPath = String(objectPath || "").trim().replace(/^\/+/, "");
  if (!cleanPath) throw new Error("Curriculum storage path is required.");
  const key = _lmsCurriculumSignedUrlCacheKey(cleanBucket, cleanPath);
  const now = Date.now();
  const cached = lmsCurriculumSignedUrlCache.get(key);
  if (cached?.signedUrl && Number(cached.expiresAt || 0) > now + 90_000) {
    lmsCurriculumSignedUrlCache.delete(key);
    lmsCurriculumSignedUrlCache.set(key, cached);
    return cached;
  }
  const signed = await supabaseDb.createSignedDownloadUrl(cleanPath, {
    bucketName: cleanBucket,
    expiresIn,
  });
  const lifetimeSeconds = Math.max(30, Number(signed?.expiresIn || expiresIn) || expiresIn);
  const entry = {
    ...signed,
    expiresAt: now + (lifetimeSeconds * 1000),
  };
  lmsCurriculumSignedUrlCache.set(key, entry);
  if (lmsCurriculumSignedUrlCache.size > LMS_CURRICULUM_SIGNED_URL_CACHE_LIMIT) {
    _lmsCurriculumTrimSignedUrlCache();
  }
  return entry;
}

function _lmsCurriculumSafeFileName(value = "file") {
  const raw = String(value || "file").trim().slice(0, 240) || "file";
  const dot = raw.lastIndexOf(".");
  const stem = (dot > 0 ? raw.slice(0, dot) : raw).replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "file";
  const ext = dot > 0 ? raw.slice(dot).replace(/[^a-zA-Z0-9.]+/g, "").slice(0, 20) : "";
  return `${stem.slice(0, 180)}${ext}`;
}

function _lmsCurriculumPreviewKind(mimeType = "", fileName = "") {
  const mime = String(mimeType || "").trim().toLowerCase();
  const extension = String(fileName || "").trim().toLowerCase().match(/\.([a-z0-9]{1,10})$/)?.[1] || "";
  if (mime === "application/pdf" || extension === "pdf") return "pdf";
  if (mime.startsWith("image/") || ["jpg", "jpeg", "png", "gif", "webp", "bmp", "svg", "avif"].includes(extension)) return "image";
  if (mime.startsWith("video/") || ["mp4", "webm", "ogv", "mov", "m4v"].includes(extension)) return "video";
  if (mime.startsWith("audio/") || ["mp3", "wav", "ogg", "m4a", "aac", "flac"].includes(extension)) return "audio";
  if (
    mime.startsWith("text/") ||
    ["txt", "md", "csv", "json", "xml", "log", "js", "css", "html", "htm"].includes(extension) ||
    ["application/json", "application/xml", "application/javascript"].includes(mime)
  ) return "text";
  return "unsupported";
}

app.post("/api/lms/curriculum/:id/grades/:gradeId/upload-ticket", async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const curriculumId = String(req.params?.id || "").trim();
    const gradeId = String(req.params?.gradeId || "").trim();
    if (!/^\d+$/.test(curriculumId) || !/^\d+$/.test(gradeId)) return res.status(400).json({ ok: false, error: "Invalid grade ID." });
    const fileName = String(req.body?.fileName || req.body?.name || "").trim().slice(0, 240);
    const fileSize = Number(req.body?.fileSize || req.body?.size || 0);
    const mimeType = String(req.body?.mimeType || req.body?.type || "application/octet-stream").trim().slice(0, 240) || "application/octet-stream";
    const resourceType = String(req.body?.resourceType || "").trim().toLowerCase();
    if (!Object.prototype.hasOwnProperty.call(LMS_CURRICULUM_RESOURCE_TYPES, resourceType)) return res.status(400).json({ ok: false, error: "Choose a valid curriculum file type." });
    if (!fileName) return res.status(400).json({ ok: false, error: "Choose a file first." });
    if (!Number.isFinite(fileSize) || fileSize <= 0) return res.status(400).json({ ok: false, error: "The selected file is empty." });
    if (fileSize > LMS_CURRICULUM_MAX_FILE_BYTES) return res.status(413).json({ ok: false, error: "The file must be 500 MB or less." });
    const gradeExists = await supabaseDb.request(`/lms_curriculum_grades?select=id&id=eq.${_sbRestFilterValue(gradeId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&limit=1`);
    if (!Array.isArray(gradeExists) || !gradeExists.length) return res.status(404).json({ ok: false, error: "Grade was not found." });
    const cleanName = _lmsCurriculumSafeFileName(fileName);
    const objectPath = `curriculum/${curriculumId}/grades/${gradeId}/${resourceType}/${Date.now()}-${Math.random().toString(16).slice(2)}-${cleanName}`;
    const ticket = await supabaseDb.createSignedUploadUrl(objectPath, { bucketName: LMS_CURRICULUM_STORAGE_BUCKET, upsert: false });
    let previewUploads = [];
    if (_lmsCurriculumPreviewKind(mimeType, fileName) === "pdf") {
      const previewResults = await Promise.allSettled([1, 2].map(async (pageNumber) => {
        const previewPath = _lmsCurriculumPdfPreviewObjectPath(objectPath, pageNumber);
        const previewTicket = await supabaseDb.createSignedUploadUrl(previewPath, {
          bucketName: LMS_CURRICULUM_STORAGE_BUCKET,
          upsert: false,
        });
        return {
          pageNumber,
          signedUrl: previewTicket.signedUrl,
          path: previewTicket.path,
          bucket: previewTicket.bucket,
          mimeType: "image/jpeg",
        };
      }));
      previewUploads = previewResults
        .filter((result) => result.status === "fulfilled")
        .map((result) => result.value);
    }
    const storageBaseUrl = String(supabaseDb.getConfig()?.url || "").trim().replace(/\/+$/, "");
    const resumableApiKey = String(
      process.env.SUPABASE_ANON_KEY ||
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ||
      ""
    ).trim();
    const resumableUrl = storageBaseUrl ? `${storageBaseUrl}/storage/v1/upload/resumable/sign` : "";
    const resumableEnabled = Boolean(ticket.token && resumableUrl && resumableApiKey);
    return res.status(201).json({
      ok: true,
      upload: {
        mode: resumableEnabled ? "resumable" : "standard",
        signedUrl: ticket.signedUrl,
        token: ticket.token,
        resumableUrl: resumableEnabled ? resumableUrl : null,
        resumableApiKey: resumableEnabled ? resumableApiKey : null,
        path: ticket.path,
        bucket: ticket.bucket,
        publicUrl: ticket.publicUrl,
        fileName,
        fileSize,
        mimeType,
        previewUploads,
      },
    });
  } catch (error) {
    console.error("POST curriculum upload ticket error:", error?.details || error?.body || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to prepare the file upload." });
  }
});

app.post("/api/lms/curriculum/:id/grades/:gradeId/resources", async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const curriculumId = String(req.params?.id || "").trim();
    const gradeId = String(req.params?.gradeId || "").trim();
    if (!/^\d+$/.test(curriculumId) || !/^\d+$/.test(gradeId)) return res.status(400).json({ ok: false, error: "Invalid grade ID." });
    const resourceType = String(req.body?.resourceType || "").trim().toLowerCase();
    if (!Object.prototype.hasOwnProperty.call(LMS_CURRICULUM_RESOURCE_TYPES, resourceType)) return res.status(400).json({ ok: false, error: "Choose a valid curriculum file type." });
    const name = String(req.body?.name || req.body?.fileName || "").trim().slice(0, 240);
    const storagePath = String(req.body?.storagePath || "").trim().slice(0, 2000) || null;
    const storageBucket = String(req.body?.storageBucket || LMS_CURRICULUM_STORAGE_BUCKET).trim().slice(0, 200) || LMS_CURRICULUM_STORAGE_BUCKET;
    const fileName = String(req.body?.fileName || name || "").trim().slice(0, 500) || name;
    const fileSize = Math.max(0, Math.min(LMS_CURRICULUM_MAX_FILE_BYTES, Number(req.body?.fileSize || 0) || 0));
    const mimeType = String(req.body?.mimeType || "application/octet-stream").trim().slice(0, 240) || "application/octet-stream";
    const notes = String(req.body?.notes || "").trim().slice(0, 4000) || null;
    if (!name) return res.status(400).json({ ok: false, error: "File name is required." });
    if (!storagePath) return res.status(400).json({ ok: false, error: "Upload the file before saving it." });
    const gradeExists = await supabaseDb.request(`/lms_curriculum_grades?select=id&id=eq.${_sbRestFilterValue(gradeId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&limit=1`);
    if (!Array.isArray(gradeExists) || !gradeExists.length) return res.status(404).json({ ok: false, error: "Grade was not found." });
    const createdByRaw = String(req.session?.userSupabaseId || "").trim();
    const createdBy = /^\d+$/.test(createdByRaw) ? Number(createdByRaw) : null;
    const rows = await supabaseDb.request('/lms_curriculum_resources', {
      method: 'POST', headers: { Prefer: 'return=representation' },
      body: { curriculum_id: Number(curriculumId), grade_id: Number(gradeId), resource_type: resourceType, name, resource_url: null, storage_path: storagePath, storage_bucket: storageBucket, file_name: fileName, file_size: fileSize, mime_type: mimeType, notes, created_by: createdBy, metadata: {} },
    });
    return res.status(201).json({ ok: true, resource: Array.isArray(rows) ? rows[0] : rows });
  } catch (error) {
    console.error("POST grade curriculum resource error:", error?.details || error?.body || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to add curriculum file." });
  }
});

app.patch("/api/lms/curriculum/:id/grades/:gradeId/resources/:resourceId", async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const curriculumId = String(req.params?.id || "").trim();
    const gradeId = String(req.params?.gradeId || "").trim();
    const resourceId = String(req.params?.resourceId || "").trim();
    if (!/^\d+$/.test(curriculumId) || !/^\d+$/.test(gradeId) || !/^\d+$/.test(resourceId)) {
      return res.status(400).json({ ok: false, error: "Invalid file ID." });
    }
    const name = String(req.body?.name || "").trim().slice(0, 240);
    const notes = String(req.body?.notes || "").trim().slice(0, 4000) || null;
    if (!name) return res.status(400).json({ ok: false, error: "File name is required." });

    const existingRows = await supabaseDb.request(`/lms_curriculum_resources?select=*&id=eq.${_sbRestFilterValue(resourceId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&grade_id=eq.${_sbRestFilterValue(gradeId)}&limit=1`);
    const existing = Array.isArray(existingRows) ? existingRows[0] : null;
    if (!existing) return res.status(404).json({ ok: false, error: "Curriculum file was not found." });

    const replacementPath = String(req.body?.storagePath || "").trim().slice(0, 2000);
    const hasReplacement = Boolean(replacementPath);
    const payload = { name, notes, updated_at: new Date().toISOString() };
    let replacementBucket = "";
    if (hasReplacement) {
      const fileName = String(req.body?.fileName || "").trim().slice(0, 500);
      const fileSize = Number(req.body?.fileSize || 0);
      const mimeType = String(req.body?.mimeType || "application/octet-stream").trim().slice(0, 240) || "application/octet-stream";
      replacementBucket = String(req.body?.storageBucket || LMS_CURRICULUM_STORAGE_BUCKET).trim().slice(0, 200) || LMS_CURRICULUM_STORAGE_BUCKET;
      if (!fileName) return res.status(400).json({ ok: false, error: "Replacement file name is required." });
      if (!Number.isFinite(fileSize) || fileSize <= 0) return res.status(400).json({ ok: false, error: "The replacement file is empty." });
      if (fileSize > LMS_CURRICULUM_MAX_FILE_BYTES) return res.status(413).json({ ok: false, error: "The file must be 500 MB or less." });
      Object.assign(payload, {
        resource_url: null,
        storage_path: replacementPath,
        storage_bucket: replacementBucket,
        file_name: fileName,
        file_size: fileSize,
        mime_type: mimeType,
      });
    }

    let rows;
    try {
      rows = await supabaseDb.request(`/lms_curriculum_resources?id=eq.${_sbRestFilterValue(resourceId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&grade_id=eq.${_sbRestFilterValue(gradeId)}`, {
        method: "PATCH",
        headers: { Prefer: "return=representation" },
        body: payload,
      });
    } catch (error) {
      if (hasReplacement) {
        try {
          await supabaseDb.deleteStorageObjects(_lmsCurriculumStoredObjectPaths({ storage_path: replacementPath }), {
            bucketName: replacementBucket,
          });
        }
        catch (cleanupError) { console.warn("Curriculum replacement rollback failed:", cleanupError?.message || cleanupError); }
      }
      throw error;
    }
    const resource = Array.isArray(rows) ? rows[0] : rows;
    if (!resource?.id) return res.status(404).json({ ok: false, error: "Curriculum file was not found." });

    if (hasReplacement && existing.storage_path && existing.storage_path !== replacementPath) {
      try {
        await supabaseDb.deleteStorageObjects(_lmsCurriculumStoredObjectPaths(existing), {
          bucketName: existing.storage_bucket || LMS_CURRICULUM_STORAGE_BUCKET,
        });
      } catch (storageError) {
        console.warn("Old curriculum file cleanup failed after replacement:", storageError?.message || storageError);
      }
    }
    return res.json({ ok: true, resource: _lmsCurriculumClientResource(resource) });
  } catch (error) {
    console.error("PATCH grade curriculum resource error:", error?.details || error?.body || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to update curriculum file." });
  }
});

app.get("/api/lms/curriculum/:id/grades/:gradeId/resources/:resourceId/view-ticket", async (req, res) => {
  res.set({
    "Cache-Control": "no-store, no-cache, must-revalidate, private",
    Pragma: "no-cache",
    "Referrer-Policy": "no-referrer",
  });
  try {
    const curriculumId = String(req.params?.id || "").trim();
    const gradeId = String(req.params?.gradeId || "").trim();
    const resourceId = String(req.params?.resourceId || "").trim();
    if (!/^\d+$/.test(curriculumId) || !/^\d+$/.test(gradeId) || !/^\d+$/.test(resourceId)) {
      return res.status(400).json({ ok: false, error: "Invalid file ID." });
    }
    const rows = await supabaseDb.request(`/lms_curriculum_resources?select=id,name,file_name,file_size,mime_type,resource_type,storage_path,storage_bucket&id=eq.${_sbRestFilterValue(resourceId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&grade_id=eq.${_sbRestFilterValue(gradeId)}&limit=1`);
    const resource = Array.isArray(rows) ? rows[0] : null;
    if (!resource) return res.status(404).json({ ok: false, error: "Curriculum file was not found." });
    const storagePath = String(resource.storage_path || "").trim();
    if (!storagePath) {
      return res.status(409).json({ ok: false, error: "This legacy file must be re-uploaded once before it can use protected in-system preview." });
    }
    const fileName = String(resource.file_name || resource.name || "Curriculum file").trim();
    const mimeType = String(resource.mime_type || "application/octet-stream").trim() || "application/octet-stream";
    const previewKind = _lmsCurriculumPreviewKind(mimeType, fileName);
    const commonPreview = {
      id: resource.id,
      name: String(resource.name || fileName).trim(),
      fileName,
      fileSize: Number(resource.file_size || 0) || 0,
      mimeType,
      resourceType: String(resource.resource_type || "").trim(),
      previewKind,
      viewerName: String(req.session?.username || "Authorized user").trim().slice(0, 120) || "Authorized user",
    };
    if (previewKind === "unsupported") {
      return res.json({
        ok: true,
        preview: {
          ...commonPreview,
          streamUrl: null,
          message: "This format has no safe native browser preview. Convert it to PDF, image, video, audio, or text to keep it view-only inside the system.",
        },
      });
    }
    const protectedStreamUrl = `/api/lms/curriculum/${encodeURIComponent(curriculumId)}/grades/${encodeURIComponent(gradeId)}/resources/${encodeURIComponent(resourceId)}/stream`;
    const protectedPreviewUrls = previewKind === "pdf"
      ? [1, 2].map((pageNumber) => `/api/lms/curriculum/${encodeURIComponent(curriculumId)}/grades/${encodeURIComponent(gradeId)}/resources/${encodeURIComponent(resourceId)}/fast-preview/${pageNumber}`)
      : [];

    // Give the browser short-lived direct Storage URLs. This removes the most
    // expensive part of opening large PDFs: every PDF.js range request no
    // longer needs another database lookup, signed-URL request, and Node proxy
    // stream. The authenticated in-app routes remain as automatic fallbacks.
    const bucketName = resource.storage_bucket || LMS_CURRICULUM_STORAGE_BUCKET;
    let streamUrl = protectedStreamUrl;
    let streamUrlExpiresAt = null;
    let previewUrls = protectedPreviewUrls;
    if (previewKind === "pdf") {
      const directResults = await Promise.allSettled([
        _lmsCurriculumCreateCachedSignedDownloadUrl(storagePath, {
          bucketName,
          expiresIn: LMS_CURRICULUM_DIRECT_PDF_URL_SECONDS,
        }),
        ...[1, 2].map((pageNumber) => _lmsCurriculumCreateCachedSignedDownloadUrl(
          _lmsCurriculumPdfPreviewObjectPath(storagePath, pageNumber),
          { bucketName, expiresIn: LMS_CURRICULUM_DIRECT_PREVIEW_URL_SECONDS }
        )),
      ]);
      const directPdf = directResults[0]?.status === "fulfilled" ? directResults[0].value : null;
      if (directPdf?.signedUrl) {
        streamUrl = directPdf.signedUrl;
        streamUrlExpiresAt = new Date(Number(directPdf.expiresAt || 0)).toISOString();
      }
      previewUrls = [1, 2].map((pageNumber, index) => {
        const result = directResults[index + 1];
        return result?.status === "fulfilled" && result.value?.signedUrl
          ? result.value.signedUrl
          : protectedPreviewUrls[pageNumber - 1];
      });
    }
    return res.json({
      ok: true,
      preview: {
        ...commonPreview,
        streamUrl,
        previewUrls,
        fallbackStreamUrl: protectedStreamUrl,
        fallbackPreviewUrls: protectedPreviewUrls,
        streamUrlExpiresAt,
        directStorage: streamUrl !== protectedStreamUrl,
      },
    });
  } catch (error) {
    console.error("GET curriculum protected preview ticket error:", error?.details || error?.body || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to prepare protected preview." });
  }
});

app.post("/api/lms/curriculum/:id/grades/:gradeId/resources/:resourceId/fast-preview-upload-ticket", async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const curriculumId = String(req.params?.id || "").trim();
    const gradeId = String(req.params?.gradeId || "").trim();
    const resourceId = String(req.params?.resourceId || "").trim();
    if (!/^\d+$/.test(curriculumId) || !/^\d+$/.test(gradeId) || !/^\d+$/.test(resourceId)) {
      return res.status(400).json({ ok: false, error: "Invalid file ID." });
    }
    const rows = await supabaseDb.request(`/lms_curriculum_resources?select=id,file_name,mime_type,storage_path,storage_bucket&id=eq.${_sbRestFilterValue(resourceId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&grade_id=eq.${_sbRestFilterValue(gradeId)}&limit=1`);
    const resource = Array.isArray(rows) ? rows[0] : null;
    if (!resource) return res.status(404).json({ ok: false, error: "Curriculum file was not found." });
    const storagePath = String(resource.storage_path || "").trim();
    if (!storagePath || _lmsCurriculumPreviewKind(resource.mime_type, resource.file_name) !== "pdf") {
      return res.status(409).json({ ok: false, error: "Fast page previews are only available for stored PDF files." });
    }
    const bucketName = resource.storage_bucket || LMS_CURRICULUM_STORAGE_BUCKET;
    const results = await Promise.all([1, 2].map(async (pageNumber) => {
      const previewPath = _lmsCurriculumPdfPreviewObjectPath(storagePath, pageNumber);
      const previewTicket = await supabaseDb.createSignedUploadUrl(previewPath, {
        bucketName,
        upsert: true,
      });
      return {
        pageNumber,
        signedUrl: previewTicket.signedUrl,
        path: previewTicket.path,
        bucket: previewTicket.bucket,
        mimeType: "image/jpeg",
        upsert: true,
      };
    }));
    return res.status(201).json({ ok: true, uploads: results });
  } catch (error) {
    console.error("POST curriculum fast preview upload ticket error:", error?.details || error?.body || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to prepare the fast page preview upload." });
  }
});

app.get("/api/lms/curriculum/:id/grades/:gradeId/resources/:resourceId/fast-preview/:pageNumber", async (req, res) => {
  res.set({
    "Cache-Control": "private, max-age=120, stale-while-revalidate=300",
    "Referrer-Policy": "no-referrer",
    "X-Content-Type-Options": "nosniff",
    "Cross-Origin-Resource-Policy": "same-origin",
  });
  try {
    const curriculumId = String(req.params?.id || "").trim();
    const gradeId = String(req.params?.gradeId || "").trim();
    const resourceId = String(req.params?.resourceId || "").trim();
    const pageNumber = Number(req.params?.pageNumber || 0);
    if (
      !/^\d+$/.test(curriculumId) ||
      !/^\d+$/.test(gradeId) ||
      !/^\d+$/.test(resourceId) ||
      ![1, 2].includes(pageNumber)
    ) {
      return res.status(400).end();
    }
    const rows = await supabaseDb.request(`/lms_curriculum_resources?select=id,file_name,mime_type,storage_path,storage_bucket&id=eq.${_sbRestFilterValue(resourceId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&grade_id=eq.${_sbRestFilterValue(gradeId)}&limit=1`);
    const resource = Array.isArray(rows) ? rows[0] : null;
    if (!resource) return res.status(404).end();
    const storagePath = String(resource.storage_path || "").trim();
    if (!storagePath || _lmsCurriculumPreviewKind(resource.mime_type, resource.file_name) !== "pdf") {
      return res.status(404).end();
    }
    const previewPath = _lmsCurriculumPdfPreviewObjectPath(storagePath, pageNumber);
    const signed = await _lmsCurriculumCreateCachedSignedDownloadUrl(previewPath, {
      bucketName: resource.storage_bucket || LMS_CURRICULUM_STORAGE_BUCKET,
      expiresIn: LMS_CURRICULUM_DIRECT_PREVIEW_URL_SECONDS,
    });
    const abortController = new AbortController();
    const abortUpstream = () => abortController.abort();
    if (typeof req.once === "function") req.once("aborted", abortUpstream);
    if (typeof res.once === "function") res.once("close", abortUpstream);
    const upstream = await fetch(signed.signedUrl, {
      method: req.method === "HEAD" ? "HEAD" : "GET",
      headers: { Accept: "image/jpeg", "Accept-Encoding": "identity" },
      redirect: "follow",
      signal: abortController.signal,
    });
    if (upstream.status === 404) {
      try { await upstream.body?.cancel(); } catch {}
      return res.status(404).end();
    }
    if (!upstream.ok || (req.method !== "HEAD" && !upstream.body)) {
      try { await upstream.body?.cancel(); } catch {}
      const error = new Error("Fast PDF preview storage did not return the requested page.");
      error.status = upstream.status || 502;
      throw error;
    }
    res.status(200);
    res.setHeader("Content-Type", "image/jpeg");
    res.setHeader("Content-Disposition", `inline; filename="page-${pageNumber}.jpg"`);
    const contentLength = upstream.headers.get("content-length");
    if (contentLength) res.setHeader("Content-Length", contentLength);
    if (req.method === "HEAD") return res.end();
    const stream = Readable.fromWeb(upstream.body);
    stream.on("error", (streamError) => {
      if (streamError?.name !== "AbortError") console.error("Curriculum fast preview stream error:", streamError?.message || streamError);
      if (!res.headersSent) res.status(502).end();
      else res.destroy(streamError);
    });
    stream.pipe(res);
  } catch (error) {
    if (error?.status === 404) return res.status(404).end();
    console.error("GET curriculum fast preview error:", error?.details || error?.body || error);
    if (res.headersSent) return res.destroy(error);
    return res.status(error?.status || 500).end();
  }
});

app.get("/api/lms/curriculum/:id/grades/:gradeId/resources/:resourceId/stream", async (req, res) => {
  res.set({
    "Cache-Control": "no-store, no-cache, must-revalidate, private",
    Pragma: "no-cache",
    "Referrer-Policy": "no-referrer",
    "X-Content-Type-Options": "nosniff",
    "Content-Security-Policy": "default-src 'none'; sandbox",
  });
  try {
    const curriculumId = String(req.params?.id || "").trim();
    const gradeId = String(req.params?.gradeId || "").trim();
    const resourceId = String(req.params?.resourceId || "").trim();
    if (!/^\d+$/.test(curriculumId) || !/^\d+$/.test(gradeId) || !/^\d+$/.test(resourceId)) {
      return res.status(400).json({ ok: false, error: "Invalid file ID." });
    }
    const rows = await supabaseDb.request(`/lms_curriculum_resources?select=id,name,file_name,mime_type,storage_path,storage_bucket&id=eq.${_sbRestFilterValue(resourceId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&grade_id=eq.${_sbRestFilterValue(gradeId)}&limit=1`);
    const resource = Array.isArray(rows) ? rows[0] : null;
    if (!resource) return res.status(404).json({ ok: false, error: "Curriculum file was not found." });
    const storagePath = String(resource.storage_path || "").trim();
    if (!storagePath) return res.status(409).json({ ok: false, error: "This legacy file must be re-uploaded before it can be previewed." });

    const fileName = String(resource.file_name || resource.name || "Curriculum file").trim();
    const mimeType = String(resource.mime_type || "application/octet-stream").trim().replace(/[\r\n]/g, "") || "application/octet-stream";
    const previewKind = _lmsCurriculumPreviewKind(mimeType, fileName);
    if (previewKind === "unsupported") {
      return res.status(415).json({ ok: false, error: "This file format is not available in the protected viewer." });
    }

    const signed = await _lmsCurriculumCreateCachedSignedDownloadUrl(storagePath, {
      bucketName: resource.storage_bucket || LMS_CURRICULUM_STORAGE_BUCKET,
      expiresIn: LMS_CURRICULUM_DIRECT_PDF_URL_SECONDS,
    });
    const upstreamHeaders = { Accept: "*/*", "Accept-Encoding": "identity" };
    const requestedRange = String(req.headers.range || "").trim();
    if (/^bytes=\d*-\d*$/.test(requestedRange)) upstreamHeaders.Range = requestedRange;
    const abortController = new AbortController();
    const abortUpstream = () => abortController.abort();
    if (typeof req.once === "function") req.once("aborted", abortUpstream);
    if (typeof res.once === "function") res.once("close", abortUpstream);
    const upstream = await fetch(signed.signedUrl, {
      method: req.method === "HEAD" ? "HEAD" : "GET",
      headers: upstreamHeaders,
      redirect: "follow",
      signal: abortController.signal,
    });
    if (!upstream.ok || (req.method !== "HEAD" && !upstream.body)) {
      try { await upstream.body?.cancel(); } catch {}
      const error = new Error("Protected file storage did not return the requested content.");
      error.status = upstream.status || 502;
      throw error;
    }

    const safeName = _lmsCurriculumSafeFileName(fileName).replace(/"/g, "") || "preview";
    const safeContentType = previewKind === "pdf"
      ? "application/pdf"
      : previewKind === "text"
        ? "text/plain; charset=utf-8"
        : mimeType;
    res.status(upstream.status === 206 ? 206 : 200);
    res.setHeader("Content-Type", safeContentType);
    res.setHeader("Content-Disposition", `inline; filename="${safeName}"`);
    ["content-length", "content-range", "accept-ranges"].forEach((header) => {
      const value = upstream.headers.get(header);
      if (value) res.setHeader(header, value);
    });
    if (req.method === "HEAD") return res.end();

    const stream = Readable.fromWeb(upstream.body);
    stream.on("error", (streamError) => {
      if (streamError?.name !== "AbortError") console.error("Curriculum protected stream error:", streamError?.message || streamError);
      if (!res.headersSent) res.status(502).end();
      else res.destroy(streamError);
    });
    stream.pipe(res);
  } catch (error) {
    console.error("GET curriculum protected stream error:", error?.details || error?.body || error);
    if (res.headersSent) return res.destroy(error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to stream the protected preview." });
  }
});

app.delete("/api/lms/curriculum/:id/grades/:gradeId/resources/:resourceId", async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const curriculumId = String(req.params?.id || "").trim();
    const gradeId = String(req.params?.gradeId || "").trim();
    const resourceId = String(req.params?.resourceId || "").trim();
    if (!/^\d+$/.test(curriculumId) || !/^\d+$/.test(gradeId) || !/^\d+$/.test(resourceId)) return res.status(400).json({ ok: false, error: "Invalid file ID." });
    const rows = await supabaseDb.request(`/lms_curriculum_resources?select=id,storage_path,storage_bucket&id=eq.${_sbRestFilterValue(resourceId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&grade_id=eq.${_sbRestFilterValue(gradeId)}&limit=1`);
    const resource = Array.isArray(rows) ? rows[0] : null;
    if (!resource) return res.status(404).json({ ok: false, error: "Curriculum file was not found." });
    await supabaseDb.request(`/lms_curriculum_resources?id=eq.${_sbRestFilterValue(resourceId)}&curriculum_id=eq.${_sbRestFilterValue(curriculumId)}&grade_id=eq.${_sbRestFilterValue(gradeId)}`, { method: 'DELETE', headers: { Prefer: 'return=minimal' } });
    if (resource.storage_path) {
      try {
        await supabaseDb.deleteStorageObjects(_lmsCurriculumStoredObjectPaths(resource), {
          bucketName: resource.storage_bucket || LMS_CURRICULUM_STORAGE_BUCKET,
        });
      }
      catch (storageError) { console.warn("Curriculum storage cleanup failed:", storageError?.message || storageError); }
    }
    return res.json({ ok: true });
  } catch (error) {
    console.error("DELETE grade curriculum resource error:", error?.details || error?.body || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to delete curriculum file." });
  }
});

app.post("/api/lms/curriculum/:id/resources", async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const curriculumId = String(req.params?.id || "").trim();
    if (!/^\d+$/.test(curriculumId)) return res.status(400).json({ ok: false, error: "Invalid curriculum ID." });
    const resourceType = String(req.body?.resourceType || "").trim().toLowerCase();
    if (!Object.prototype.hasOwnProperty.call(LMS_CURRICULUM_RESOURCE_TYPES, resourceType)) {
      return res.status(400).json({ ok: false, error: "Choose a valid curriculum file type." });
    }
    const name = String(req.body?.name || "").trim().slice(0, 240);
    const resourceUrl = String(req.body?.resourceUrl || "").trim().slice(0, 2000) || null;
    const notes = String(req.body?.notes || "").trim().slice(0, 4000) || null;
    if (!name) return res.status(400).json({ ok: false, error: "File name is required." });
    const exists = await supabaseDb.request(`/lms_curricula?select=id&id=eq.${_sbRestFilterValue(curriculumId)}&limit=1`);
    if (!Array.isArray(exists) || !exists.length) return res.status(404).json({ ok: false, error: "Curriculum was not found." });
    const createdByRaw = String(req.session?.userSupabaseId || "").trim();
    const createdBy = /^\d+$/.test(createdByRaw) ? Number(createdByRaw) : null;
    const rows = await supabaseDb.request('/lms_curriculum_resources', {
      method: 'POST', headers: { Prefer: 'return=representation' },
      body: { curriculum_id: Number(curriculumId), resource_type: resourceType, name, resource_url: resourceUrl, notes, created_by: createdBy, metadata: {} },
    });
    return res.status(201).json({ ok: true, resource: Array.isArray(rows) ? rows[0] : rows });
  } catch (error) {
    console.error("POST /api/lms/curriculum/:id/resources error:", error?.details || error?.body || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to add curriculum file." });
  }
});

