// Update "Quantity Received by operations" for a single order item (Operations edit Qty)
// Body: { value: number }
app.post(
  "/api/orders/requested/:id/received-quantity",
  requireAuth,
  requirePage("Requested Orders"),
  async (req, res) => {
    try {
      const rawId = String(req.params.id || "").trim();
      const id = looksLikeNotionId(rawId) ? toHyphenatedUUID(rawId) : rawId;
      const { value } = req.body || {};

      const vNumRaw = Number(value);
      if (!Number.isFinite(vNumRaw)) {
        return res.status(400).json({ error: "value must be a number" });
      }

      // Support fractional quantities (e.g. 0.5). Keep values stable by rounding.
      const roundQty = (n) => {
        const v = Number(n);
        if (!Number.isFinite(v)) return 0;
        return Math.round(v * 1e6) / 1e6;
      };

      const vNumRounded = roundQty(vNumRaw);

      if (_sbOrdersEnabled() && /^\d+$/.test(String(id))) {
        const row = await supabaseDb.selectById(_sbOrdersTable(), id);
        if (!row) return res.status(404).json({ error: "Order row not found" });
        const base = _sbSerializeOrderRow(row).quantity || 0;
        const vNum = clampOrderQtyToBase(base, vNumRounded);
        const remaining = roundQty((Number(base) || 0) - vNum);
        await supabaseDb.updateById(_sbOrdersTable(), id, {
          quantity_received_by_operations: vNum,
          quantity_remaining: remaining,
        });
        await _sbInvalidateOrdersCaches();
        return res.json({
          success: true,
          value: vNum,
          remaining,
          quantityRemaining: remaining,
          source: "supabase",
        });
      }

      // Detect received quantity property name (Number)
      const receivedProp = (await (async () => {
        const props = await getOrdersDBProps();
        if (props[REC_PROP_HARDBIND] && props[REC_PROP_HARDBIND].type === "number") return REC_PROP_HARDBIND;
        return await detectReceivedQtyPropName();
      })());

      if (!receivedProp) {
        return res.status(500).json({ error: 'Received-quantity column not found (expected: "Quantity Received by operations")' });
      }

      // Remaining quantity column (optional but expected by the UI)
      const remainingProp = await detectRemainingQtyPropName();

      // Read base qty to compute remaining = base - received
      let baseQtyNum = 0;
      let pageProps = null;
      try {
        const page = await notion.pages.retrieve({ page_id: id });
        pageProps = page?.properties || {};
      } catch (err) {
        console.error("received-quantity retrieve error:", err?.body || err);
        pageProps = null;
      }

      const normKeyLocal = (s) => String(s || "").trim().toLowerCase().replace(/[^a-z0-9]/g, "");
      const getPropInsensitive = (props, name) => {
        const want = normKeyLocal(name);
        for (const k of Object.keys(props || {})) {
          if (normKeyLocal(k) === want) return props[k];
        }
        return null;
      };

      const parseNumberProp = (prop) => {
        if (!prop) return null;
        try {
          if (prop.type === "number") return prop.number ?? null;
          if (prop.type === "formula") {
            if (prop.formula?.type === "number") return prop.formula.number ?? null;
            if (prop.formula?.type === "string") {
              const n = parseFloat(String(prop.formula.string || "").replace(/[^0-9.-]/g, ""));
              return Number.isFinite(n) ? n : null;
            }
          }
          if (prop.type === "rollup") {
            if (prop.rollup?.type === "number") return prop.rollup.number ?? null;
            if (prop.rollup?.type === "array") {
              const arr = prop.rollup.array || [];
              for (const x of arr) {
                if (x.type === "number" && typeof x.number === "number") return x.number;
                if (x.type === "formula" && x.formula?.type === "number") return x.formula.number;
                if (x.type === "formula" && x.formula?.type === "string") {
                  const n = parseFloat(String(x.formula.string || "").replace(/[^0-9.-]/g, ""));
                  if (Number.isFinite(n)) return n;
                }
              }
            }
          }
        } catch {}
        return null;
      };

      if (pageProps) {
        const qtyProgressRaw =
          parseNumberProp(getPropInsensitive(pageProps, "Quantity Progress")) ??
          parseNumberProp(getPropInsensitive(pageProps, "Quantity progress"));

        const qtyRequestedRaw =
          parseNumberProp(getPropInsensitive(pageProps, "Quantity Requested")) ??
          parseNumberProp(getPropInsensitive(pageProps, "Quantity requested"));

        baseQtyNum =
          qtyProgressRaw !== null && qtyProgressRaw !== undefined && Number.isFinite(Number(qtyProgressRaw))
            ? Number(qtyProgressRaw)
            : qtyRequestedRaw !== null && qtyRequestedRaw !== undefined && Number.isFinite(Number(qtyRequestedRaw))
              ? Number(qtyRequestedRaw)
              : 0;
      }
      const safeBaseQty = roundQty(baseQtyNum || 0);
      const vNum = clampOrderQtyToBase(safeBaseQty, vNumRounded);
      const remainingVal = roundQty(safeBaseQty - vNum);

      const updateProps = {
        [receivedProp]: { number: vNum },
      };
      if (remainingProp) {
        updateProps[remainingProp] = { number: remainingVal };
      }

      await notion.pages.update({
        page_id: id,
        properties: updateProps,
      });

      // Invalidate caches so quantities update immediately.
      await cacheDel("cache:api:orders:requested:v7");
      try {
        const page = await notion.pages.retrieve({ page_id: id });
        const rel = page?.properties?.["Teams Members"]?.relation || [];
        const memberIds = (Array.isArray(rel) ? rel : [])
          .map((r) => r?.id)
          .filter(Boolean);
        await Promise.all(
          memberIds.map((mid) => cacheDel(`cache:api:orders:list:${mid}:v7`)),
        );
      } catch {}

      return res.json({ success: true, value: vNum, remaining: remainingVal });
    } catch (e) {
      console.error("received-quantity update error:", e.body || e);
      return res.status(500).json({ error: "Failed to update received quantity" });
    }
  },
);


// Export requested order to PDF (Delivery receipt)
// Body: { orderIds: [notionPageId, ...] }
app.post(
  "/api/orders/requested/export/pdf",
  requireAuth,
  requirePage(["Requested Orders", "Operations Orders", "Maintenance Orders"]),
  async (req, res) => {
    try {
      const { orderIds, tab, columns } = req.body || {};
      if (!Array.isArray(orderIds) || orderIds.length === 0) {
        return res.status(400).json({ error: "orderIds required" });
      }

      // Requested change:
      // When exporting from the "Received" or "Delivered" tabs, hide cost columns (Unit / Total)
      // in the generated PDF.
      const tabKey = String(tab || "").trim().toLowerCase();
      const selectedExportColumns = _normalizeOrderExportColumns(columns, { tab: tabKey });
      const hideCosts = !selectedExportColumns.includes("unit") && !selectedExportColumns.includes("total");

      const ids = orderIds
        .map((x) => String(x || "").trim())
        .filter(Boolean)
        .map((x) => (looksLikeNotionId(x) ? toHyphenatedUUID(x) : x));

      if (!ids.length) return res.status(400).json({ error: "orderIds required" });

      if (_sbOrdersEnabled() && ids.every((id) => /^\d+$/.test(String(id)))) {
        return await _sbPipeOrderDeliveryPdf(req, res, ids, { tab, columns });
      }

      const parseNumberProp = (prop) => {
        if (!prop) return null;
        try {
          if (prop.type === "number") return prop.number ?? null;
          if (prop.type === "formula") {
            if (prop.formula?.type === "number") return prop.formula.number ?? null;
            if (prop.formula?.type === "string") {
              const n = parseFloat(String(prop.formula.string || "").replace(/[^0-9.-]/g, ""));
              return Number.isFinite(n) ? n : null;
            }
          }
          if (prop.type === "rollup") {
            if (prop.rollup?.type === "number") return prop.rollup.number ?? null;
            if (prop.rollup?.type === "array") {
              const arr = prop.rollup.array || [];
              for (const x of arr) {
                if (x.type === "number" && typeof x.number === "number") return x.number;
                if (x.type === "formula" && x.formula?.type === "number") return x.formula.number;
                if (x.type === "formula" && x.formula?.type === "string") {
                  const n = parseFloat(String(x.formula.string || "").replace(/[^0-9.-]/g, ""));
                  if (Number.isFinite(n)) return n;
                }
              }
            }
          }
          if (prop.type === "rich_text") {
            const t = (prop.rich_text || []).map((r) => r.plain_text).join("").trim();
            const n = parseFloat(t.replace(/[^0-9.-]/g, ""));
            return Number.isFinite(n) ? n : null;
          }
        } catch {}
        return null;
      };

      const getPropInsensitive = (props, name) => {
        if (!props || !name) return null;
        const target = String(name).trim().toLowerCase();
        for (const [k, v] of Object.entries(props)) {
          if (String(k).trim().toLowerCase() === target) return v;
        }
        return null;
      };

      const extractUniqueIdDetails = (prop) => {
        try {
          if (!prop) return { text: null, prefix: null, number: null };
          if (prop.type === "unique_id") {
            const u = prop.unique_id;
            if (!u || typeof u.number !== "number") return { text: null, prefix: null, number: null };
            const prefix = u.prefix ? String(u.prefix).trim() : "";
            const number = u.number;
            const text = prefix ? `${prefix}-${number}` : String(number);
            return { text, prefix: prefix || null, number };
          }
        } catch {}
        return { text: null, prefix: null, number: null };
      };

      const getOrderUniqueIdDetails = (props) => {
        // Prefer the new numeric group id column: "Order - ID" (Number)
        const orderNumProp =
          getPropInsensitive(props, "Order - ID") ||
          getPropInsensitive(props, "Order ID") ||
          getPropInsensitive(props, "Order-ID") ||
          getPropInsensitive(props, "Order Id") ||
          null;
        const orderNum = _extractPropNumber(orderNumProp);
        if (Number.isFinite(Number(orderNum))) {
          const n = Number(orderNum);
          return { text: `ORD-${n}`, prefix: "ORD", number: n };
        }

        // Fallback to old unique_id column (legacy)
        const direct = getPropInsensitive(props, "ID");
        const d = extractUniqueIdDetails(direct);
        if (d.text) return d;
        for (const v of Object.values(props || {})) {
          if (v?.type === "unique_id") {
            const x = extractUniqueIdDetails(v);
            if (x.text) return x;
          }
        }
        return { text: null, prefix: null, number: null };
      };

      const computeOrderIdRange = (uids) => {
        const nums = uids.filter((u) => typeof u.number === "number");
        if (nums.length) {
          const prefix = nums[0].prefix || "";
          const samePrefix = nums.every((x) => (x.prefix || "") === prefix);
          const min = Math.min(...nums.map((x) => x.number));
          const max = Math.max(...nums.map((x) => x.number));
          if (min === max) return prefix ? `${prefix}-${min}` : String(min);
          if (samePrefix && prefix) return `${prefix}-${min} : ${prefix}-${max}`;
        }
        const texts = uids.map((u) => u.text).filter(Boolean);
        if (!texts.length) return "Order";
        if (texts.length === 1) return texts[0];
        return `${texts[0]} : ${texts[texts.length - 1]}`;
      };

      const money = (n) => {
        const num = Number(n) || 0;
        return `£${num.toFixed(2)}`;
      };

      // Detect received quantity property name (Number)
      const receivedProp = (await (async () => {
        const props = await getOrdersDBProps();
        if (props[REC_PROP_HARDBIND] && props[REC_PROP_HARDBIND].type === "number") return REC_PROP_HARDBIND;
        return await detectReceivedQtyPropName();
      })());

      // Load pages
      const pages = (await Promise.all(
        ids.map(async (id) => {
          try {
            return await notion.pages.retrieve({ page_id: id });
          } catch {
            return null;
          }
        }),
      )).filter(Boolean);

      if (!pages.length) return res.status(404).json({ error: "Orders not found" });

      // Member name cache
      const nameCache = new Map();
      async function memberName(id) {
        if (!id) return "";
        if (nameCache.has(id)) return nameCache.get(id);
        try {
          const nm = await getTeamMemberNameCached(id);
          nameCache.set(id, nm || "");
          return nm || "";
        } catch {
          return "";
        }
      }

      // Product cache
      const productCache = new Map();
      async function productInfo(productPageId) {
        if (!productPageId) return { name: "Unknown", idCode: null, unitPrice: null, url: null };
        if (productCache.has(productPageId)) return productCache.get(productPageId);
        const info = await getProductInfoCached(productPageId);
        const out = {
          name: info?.name || "Unknown",
          idCode: info?.idCode || null,
          unitPrice: typeof info?.unitPrice === "number" ? info.unitPrice : null,
          url: info?.url || null,
        };
        productCache.set(productPageId, out);
        return out;
      }

      // Header info
      const createdTimes = pages.map((p) => new Date(p.created_time));
      const createdAt = new Date(Math.min(...createdTimes.map((d) => d.getTime())));

      // Team member (from first page relation)
      let teamMember = "";
      const firstProps = pages[0].properties || {};
      const teamRel = firstProps["Teams Members"]?.relation;
      if (Array.isArray(teamRel) && teamRel.length) {
        teamMember = await memberName(teamRel[0].id);
      }

      const uids = pages.map((p) => getOrderUniqueIdDetails(p.properties || {}));
      const orderIdRange = computeOrderIdRange(uids);
      const receiptView = _receiptPresentationForOrderType(_extractOrderTypeInfo(firstProps).orderType);

      // Build rows
      const rows = [];
      let grandTotal = 0;
      let grandQty = 0;

      for (const p of pages) {
        const props = p.properties || {};
        const reason = props.Reason?.title?.[0]?.plain_text || "";

        // Base qty: "Quantity Progress" (fallback to "Quantity Requested")
        const qtyProgressProp = props["Quantity Progress"] || props["Quantity progress"];
        const qtyProgress =
          qtyProgressProp?.number ??
          qtyProgressProp?.formula?.number ??
          qtyProgressProp?.rollup?.number ??
          null;

        const qtyRequested = props["Quantity Requested"]?.number || 0;
        const baseQty =
          qtyProgress !== null && qtyProgress !== undefined ? qtyProgress : qtyRequested;

        // Received qty (Operations override)
        const recQtyRaw = receivedProp ? parseNumberProp(props[receivedProp]) : null;
        const qty =
          recQtyRaw === null || recQtyRaw === undefined
            ? Number(baseQty) || 0
            : Number.isFinite(Number(recQtyRaw))
              ? Number(recQtyRaw)
              : Number(baseQty) || 0;

        const productRel = props.Product?.relation;
        const productPageId =
          Array.isArray(productRel) && productRel.length ? productRel[0].id : null;

        const prod = await productInfo(productPageId);
        const unitProp =
          _propInsensitive(props, "Unit price") ||
          _propInsensitive(props, "Unit Price") ||
          _propInsensitive(props, "Unity Price") ||
          _propInsensitive(props, "Price") ||
          null;
        const unitFromOrder = _extractPropNumber(unitProp);
        const unit = Number.isFinite(Number(unitFromOrder))
          ? Number(unitFromOrder)
          : (Number(prod.unitPrice) || 0);
        const total = (Number(qty) || 0) * unit;

        grandTotal += total;
        grandQty += Number(qty) || 0;

        rows.push({
          idCode: prod.idCode || "",
          component: prod.name,
          qty,
          reason,
          link: prod.url,
          unit,
          total,
        });
      }

      // Primary Reason for this order group (current orders are grouped by Reason)
      const reasonCounts = new Map();
      for (const r of rows) {
        const key = String(r?.reason || "").trim() || "No Reason";
        reasonCounts.set(key, (reasonCounts.get(key) || 0) + 1);
      }
      const groupReason =
        Array.from(reasonCounts.entries()).sort((a, b) => b[1] - a[1])[0]?.[0] || "No Reason";

      const safeName = String(orderIdRange || "order")
        .replace(/[\\/:*?"<>|]/g, "-")
        .replace(/\s+/g, "_")
        .slice(0, 60);

      const fileName = `${receiptView.filePrefix}_${safeName}.pdf`;

      await _sendBackgroundExport(res, {
        type: "delivery-pdf",
        fileName,
        payload: {
          orderId: orderIdRange,
          createdAt,
          teamMember,
          preparedBy: groupReason,
          rows,
          grandQty,
          grandTotal,
          metaLayout: "teamReasonFirst",
          showReasonTagBar: false,
          groupByReason: false,
          headerColorKey: groupReason,
          showCosts: !hideCosts,
          exportColumns: selectedExportColumns,
          documentTitle: receiptView.documentTitle,
          recipientLabelLeft: receiptView.recipientLabelLeft,
          thirdSignatureLabel: receiptView.thirdSignatureLabel,
          signatureLabels: receiptView.signatureLabels,
        },
      });
    } catch (e) {
      console.error("export requested pdf error:", e.body || e);
      try {
        if (!res.headersSent) res.status(_exportErrorStatus(e)).json({ error: e?.message || "Failed to export PDF" });
      } catch {}
    }
  },
);

// Export maintenance order to PDF (Maintenance receipt)
// Body: { orderIds: [notionPageId, ...] }
app.post(
  "/api/orders/requested/export/maintenance-pdf",
  requireAuth,
  requirePage(["Requested Orders", "Operations Orders", "Maintenance Orders"]),
  async (req, res) => {
    try {
      const { orderIds } = req.body || {};
      if (!Array.isArray(orderIds) || orderIds.length === 0) {
        return res.status(400).json({ error: "orderIds required" });
      }

      const ids = orderIds
        .map((x) => String(x || "").trim())
        .filter(Boolean)
        .map((x) => (looksLikeNotionId(x) ? toHyphenatedUUID(x) : x));

      if (!ids.length) return res.status(400).json({ error: "orderIds required" });

      if (_sbOrdersEnabled() && ids.every((id) => /^\d+$/.test(String(id)))) {
        return await _sbPipeOrderMaintenancePdf(req, res, ids);
      }

      const pages = (await Promise.all(
        ids.map(async (id) => {
          try {
            return await notion.pages.retrieve({ page_id: id });
          } catch {
            return null;
          }
        }),
      )).filter(Boolean);

      if (!pages.length) return res.status(404).json({ error: "Orders not found" });

      const firstProps = pages[0].properties || {};
      const firstOrderType = _extractOrderTypeInfo(firstProps).orderType;
      if (_normKeyOrderType(firstOrderType) !== _normKeyOrderType("Request Maintenance")) {
        return res.status(400).json({ error: "This export is only available for maintenance orders." });
      }

      const issueDescPropName = await detectIssueDescriptionPropName();
      const actualIssueDescPropName = await detectActualIssueDescriptionPropName();
      const repairActionPropName = await detectRepairActionPropName();
      const resolutionMethodPropName = await detectResolutionMethodPropName();
      const sparePartsReplacedPropName = await detectSparePartsReplacedPropName();
      const maintenanceReceiptPropName = await detectMaintenanceReceiptPropName();
      const receivedPropName = await detectReceivedQtyPropName();

      const titleFromPage = (page) => {
        const props = page?.properties || {};
        const n = _extractPropNumber(
          _propInsensitive(props, "Order - ID") ||
          _propInsensitive(props, "Order ID") ||
          _propInsensitive(props, "Order-ID") ||
          _propInsensitive(props, "Order Id"),
        );
        if (Number.isFinite(Number(n))) return `ORD-${Number(n)}`;
        return (
          _extractPropText(_propInsensitive(props, "ID")) ||
          _extractPropText(_propInsensitive(props, "Order")) ||
          "Order"
        );
      };

      const uniqueOrderIds = Array.from(new Set(pages.map((page) => titleFromPage(page)).filter(Boolean)));
      const orderIdRange =
        uniqueOrderIds.length <= 1
          ? uniqueOrderIds[0] || "Order"
          : `${uniqueOrderIds[0]} : ${uniqueOrderIds[uniqueOrderIds.length - 1]}`;

      const createdAt = new Date(Math.min(...pages.map((page) => new Date(page.created_time).getTime())));

      const nameCache = new Map();
      async function memberName(id) {
        if (!id) return "";
        if (nameCache.has(id)) return nameCache.get(id);
        try {
          const value = String(await getTeamMemberNameCached(id) || "").trim();
          nameCache.set(id, value);
          return value;
        } catch {
          nameCache.set(id, "");
          return "";
        }
      }

      const productCache = new Map();
      async function productInfo(productPageId) {
        if (!productPageId) return { name: "Unknown", idCode: null, unitPrice: null, url: null };
        if (productCache.has(productPageId)) return productCache.get(productPageId);
        const info = await getProductInfoCached(productPageId);
        const out = {
          name: info?.name || "Unknown",
          idCode: info?.idCode || null,
          unitPrice: typeof info?.unitPrice === "number" ? info.unitPrice : null,
          url: info?.url || null,
        };
        productCache.set(productPageId, out);
        return out;
      }

      let requestedBy = "";
      const teamRel = firstProps["Teams Members"]?.relation;
      if (Array.isArray(teamRel) && teamRel.length) {
        requestedBy = await memberName(teamRel[0].id);
      }

      const extractOperationsName = async (props = {}) => {
        const opsProp =
          _propInsensitive(props, "Person Received by Operations") ||
          _propInsensitive(props, "Received by operations") ||
          _propInsensitive(props, "Operations");

        if (opsProp?.type === "relation") {
          const rel = Array.isArray(opsProp.relation) ? opsProp.relation : [];
          if (rel.length) return await memberName(rel[0].id);
        }
        if (opsProp?.type === "people") {
          const person = (opsProp.people || []).find((item) => item?.name || item?.id);
          return String(person?.name || "").trim();
        }
        if (opsProp?.type === "rich_text") {
          return (opsProp.rich_text || []).map((item) => item?.plain_text || "").join("").trim();
        }
        return "";
      };

      const pickFirstText = (propName) => {
        if (!propName) return "";
        for (const page of pages) {
          const text = String(_extractPropText(page?.properties?.[propName]) || "").trim();
          if (text) return text;
        }
        return "";
      };

      let operationsBy = "";
      for (const page of pages) {
        operationsBy = String(await extractOperationsName(page.properties || {})).trim();
        if (operationsBy) break;
      }

      const issueDescription = pickFirstText(issueDescPropName) || pages[0]?.properties?.Reason?.title?.[0]?.plain_text || "";
      const actualIssueDescription = pickFirstText(actualIssueDescPropName);
      const repairAction = pickFirstText(repairActionPropName);
      const resolutionMethod = pickFirstText(resolutionMethodPropName);

      let sparePartsReplacedList = [];
      if (sparePartsReplacedPropName) {
        for (const page of pages) {
          const prop = page?.properties?.[sparePartsReplacedPropName];
          const relationIds = notionPropRelationIds(prop);
          if (relationIds.length) {
            const relationNames = await Promise.all(
              relationIds.map(async (relationId) => {
                const info = await productInfo(relationId);
                return String(info?.name || "").trim() || String(await pageTitleById(relationId) || "").trim();
              }),
            );
            sparePartsReplacedList.push(...relationNames);
          }
          if (!sparePartsReplacedList.length && prop?.type === "multi_select") {
            sparePartsReplacedList.push(
              ...(prop.multi_select || []).map((item) => String(item?.name || "").trim()).filter(Boolean),
            );
          }
          if (!sparePartsReplacedList.length) {
            sparePartsReplacedList.push(...toUniqueStringArray(String(_extractPropText(prop) || "").trim(), {
              splitComma: true,
            }));
          }
          if (sparePartsReplacedList.length) break;
        }
      }
      sparePartsReplacedList = toUniqueStringArray(sparePartsReplacedList, { splitComma: true });
      const sparePartsReplaced = sparePartsReplacedList.join(", ");

      let maintenanceReceiptFiles = [];
      if (maintenanceReceiptPropName) {
        for (const page of pages) {
          maintenanceReceiptFiles.push(...notionFileMetas(page?.properties?.[maintenanceReceiptPropName]));
          if (maintenanceReceiptFiles.length) break;
        }
      }
      maintenanceReceiptFiles = maintenanceReceiptFiles.filter((item) => item?.name || item?.url);
      const maintenanceReceiptName = maintenanceReceiptFiles[0]?.name || "";
      const maintenanceReceiptUrl = maintenanceReceiptFiles[0]?.url || "";

      const rows = [];
      for (const page of pages) {
        const props = page.properties || {};
        const productRel = props.Product?.relation;
        const productPageId = Array.isArray(productRel) && productRel.length ? productRel[0].id : null;
        const product = await productInfo(productPageId);

        const qtyProgress =
          _extractPropNumber(_propInsensitive(props, "Quantity Progress")) ??
          _extractPropNumber(_propInsensitive(props, "Quantity progress"));
        const qtyRequested =
          _extractPropNumber(_propInsensitive(props, "Quantity Requested")) ??
          props["Quantity Requested"]?.number ??
          0;
        const qtyReceived = receivedPropName ? _extractPropNumber(props[receivedPropName]) : null;
        const qty =
          qtyReceived === null || qtyReceived === undefined
            ? (qtyProgress !== null && qtyProgress !== undefined ? qtyProgress : qtyRequested)
            : qtyReceived;

        rows.push({
          idCode: product?.idCode || "",
          component: product?.name || "Unknown",
          qty: Number(qty) || 0,
          link: product?.url || null,
        });
      }

      const safeName = String(orderIdRange || "maintenance")
        .replace(/[\\/:*?"<>|]/g, "-")
        .replace(/\s+/g, "_")
        .slice(0, 60);
      const fileName = `maintenance_receipt_${safeName}.pdf`;

      await _sendBackgroundExport(res, {
        type: "maintenance-pdf",
        fileName,
        payload: {
          orderId: orderIdRange,
          createdAt,
          requestedBy,
          operationsBy,
          issueDescription,
          actualIssueDescription,
          repairAction,
          resolutionMethod,
          sparePartsReplaced,
          sparePartsReplacedList,
          rows,
          maintenanceReceiptName,
          maintenanceReceiptUrl,
          maintenanceReceiptFiles,
        },
      });
    } catch (e) {
      console.error("export maintenance pdf error:", e?.body || e);
      try {
        if (!res.headersSent) res.status(_exportErrorStatus(e)).json({ error: e?.message || "Failed to export maintenance PDF" });
      } catch {}
    }
  },
);

// Export requested order to Excel
// Body: { orderIds: [notionPageId, ...] }
app.post(
  "/api/orders/requested/export/excel",
  requireAuth,
  requirePage(["Requested Orders", "Operations Orders", "Maintenance Orders"]),
  async (req, res) => {
    try {
      const ExcelJS = require("exceljs");
      const { orderIds, columns, tab } = req.body || {};
      if (!Array.isArray(orderIds) || orderIds.length === 0) {
        return res.status(400).json({ error: "orderIds required" });
      }

      const ids = orderIds
        .map((x) => String(x || "").trim())
        .filter(Boolean)
        .map((x) => (looksLikeNotionId(x) ? toHyphenatedUUID(x) : x));

      if (!ids.length) return res.status(400).json({ error: "orderIds required" });

      if (_sbOrdersEnabled() && ids.every((id) => /^\d+$/.test(String(id)))) {
        return await _sbPipeOrderExcel(req, res, ids, { columns, tab });
      }

      // Helpers
      const parseNumberProp = (prop) => {
        if (!prop) return null;
        try {
          if (prop.type === "number") return prop.number ?? null;
          if (prop.type === "formula") {
            if (prop.formula?.type === "number") return prop.formula.number ?? null;
            if (prop.formula?.type === "string") {
              const n = parseFloat(
                String(prop.formula.string || "").replace(/[^0-9.-]/g, ""),
              );
              return Number.isFinite(n) ? n : null;
            }
          }
          if (prop.type === "rollup") {
            if (prop.rollup?.type === "number") return prop.rollup.number ?? null;
            if (prop.rollup?.type === "array") {
              const arr = prop.rollup.array || [];
              for (const x of arr) {
                if (x.type === "number" && typeof x.number === "number") return x.number;
                if (x.type === "formula" && x.formula?.type === "number") return x.formula.number;
                if (x.type === "formula" && x.formula?.type === "string") {
                  const n = parseFloat(
                    String(x.formula.string || "").replace(/[^0-9.-]/g, ""),
                  );
                  if (Number.isFinite(n)) return n;
                }
              }
            }
          }
        } catch {}
        return null;
      };

      const getPropInsensitive = (props, name) => {
        if (!props || !name) return null;
        const target = String(name).trim().toLowerCase();
        for (const [k, v] of Object.entries(props)) {
          if (String(k).trim().toLowerCase() === target) return v;
        }
        return null;
      };

      const extractUniqueIdDetails = (prop) => {
        try {
          if (!prop) return { text: null, prefix: null, number: null };
          if (prop.type === "unique_id") {
            const u = prop.unique_id;
            if (!u || typeof u.number !== "number") return { text: null, prefix: null, number: null };
            const prefix = u.prefix ? String(u.prefix).trim() : "";
            const number = u.number;
            const text = prefix ? `${prefix}-${number}` : String(number);
            return { text, prefix: prefix || null, number };
          }
        } catch {}
        return { text: null, prefix: null, number: null };
      };

      const getOrderUniqueIdDetails = (props) => {
        // Prefer the new numeric group id column: "Order - ID" (Number)
        const orderNumProp =
          getPropInsensitive(props, "Order - ID") ||
          getPropInsensitive(props, "Order ID") ||
          getPropInsensitive(props, "Order-ID") ||
          getPropInsensitive(props, "Order Id") ||
          null;
        const orderNum = _extractPropNumber(orderNumProp);
        if (Number.isFinite(Number(orderNum))) {
          const n = Number(orderNum);
          return { text: `ORD-${n}`, prefix: "ORD", number: n };
        }

        // Fallback to old unique_id column (legacy)
        const direct = getPropInsensitive(props, "ID");
        const d = extractUniqueIdDetails(direct);
        if (d.text) return d;
        for (const v of Object.values(props || {})) {
          if (v?.type === "unique_id") {
            const x = extractUniqueIdDetails(v);
            if (x.text) return x;
          }
        }
        return { text: null, prefix: null, number: null };
      };

      const computeOrderIdRange = (uids) => {
        const nums = uids.filter((u) => typeof u.number === "number");
        if (nums.length) {
          const prefix = nums[0].prefix || "";
          const samePrefix = nums.every((x) => (x.prefix || "") === prefix);
          const min = Math.min(...nums.map((x) => x.number));
          const max = Math.max(...nums.map((x) => x.number));
          if (min === max) return prefix ? `${prefix}-${min}` : String(min);
          if (samePrefix && prefix) return `${prefix}-${min} : ${prefix}-${max}`;
        }
        const texts = uids.map((u) => u.text).filter(Boolean);
        if (!texts.length) return "Order";
        if (texts.length === 1) return texts[0];
        return `${texts[0]} : ${texts[texts.length - 1]}`;
      };

      // Received Quantity property (Number) — if filled, use it instead of base quantity
      const receivedProp = (await (async () => {
        const props = await getOrdersDBProps();
        if (props[REC_PROP_HARDBIND] && props[REC_PROP_HARDBIND].type === "number") return REC_PROP_HARDBIND;
        return await detectReceivedQtyPropName();
      })());

      // Load pages
      const pages = (await Promise.all(
        ids.map(async (id) => {
          try {
            return await notion.pages.retrieve({ page_id: id });
          } catch {
            return null;
          }
        }),
      )).filter(Boolean);

      if (!pages.length) return res.status(404).json({ error: "Orders not found" });

      // Member name cache
      const nameCache = new Map();
      async function memberName(id) {
        if (!id) return "";
        if (nameCache.has(id)) return nameCache.get(id);
        try {
          const p = await notion.pages.retrieve({ page_id: id });
          const nm = p.properties?.Name?.title?.[0]?.plain_text || "";
          nameCache.set(id, nm);
          return nm;
        } catch {
          return "";
        }
      }

      // Product cache
      const productCache = new Map();
      async function productInfo(productPageId) {
        if (!productPageId) return { name: "Unknown", unitPrice: null, url: null };
        if (productCache.has(productPageId)) return productCache.get(productPageId);
        try {
          const p = await notion.pages.retrieve({ page_id: productPageId });
          const name = p.properties?.Name?.title?.[0]?.plain_text || "Unknown";
          const idCode = _extractIdCodeFromProps(p.properties || {});
          const unitPrice =
            parseNumberProp(p.properties?.["Unity Price"]) ??
            parseNumberProp(p.properties?.["Unit price"]) ??
            parseNumberProp(p.properties?.["Unit Price"]) ??
            parseNumberProp(p.properties?.["Price"]) ??
            null;
          // Prefer Products DB "URL" property (external website URL), fallback to Notion page URL.
          let url = null;
          try {
            const urlProp =
              getPropInsensitive(p.properties, "URL") ||
              getPropInsensitive(p.properties, "Url") ||
              getPropInsensitive(p.properties, "Link") ||
              getPropInsensitive(p.properties, "Website");

            if (urlProp?.type === "url") url = urlProp.url || null;
            if (!url && urlProp?.type === "rich_text") {
              const t = (urlProp.rich_text || [])
                .map((x) => x?.plain_text || "")
                .join("")
                .trim();
              url = t || null;
            }
          } catch {}
          if (!url) url = p.url || null;
          const info = { name, idCode, unitPrice, url };
          productCache.set(productPageId, info);
          return info;
        } catch {
          const info = { name: "Unknown", idCode: null, unitPrice: null, url: null };
          productCache.set(productPageId, info);
          return info;
        }
      }

      // Derive order header info
      const createdTimes = pages.map((p) => new Date(p.created_time));
      const createdAt = new Date(Math.min(...createdTimes.map((d) => d.getTime())));

      // Team member (from first page relation)
      let teamMember = "";
      const firstProps = pages[0].properties || {};
      const teamRel = firstProps["Teams Members"]?.relation;
      if (Array.isArray(teamRel) && teamRel.length) {
        teamMember = await memberName(teamRel[0].id);
      }

      const uids = pages.map((p) => getOrderUniqueIdDetails(p.properties || {}));
      const orderIdRange = computeOrderIdRange(uids);

      // Build rows
      const rows = [];
      let grandTotal = 0;
      let grandQty = 0;
      for (const p of pages) {
        const props = p.properties || {};
        const reason = props.Reason?.title?.[0]?.plain_text || "";
        // Qty should come from "Quantity Progress" (fallback to "Quantity Requested")
        const qtyProgressProp = props["Quantity Progress"] || props["Quantity progress"];
        const qtyProgress =
          qtyProgressProp?.number ??
          qtyProgressProp?.formula?.number ??
          qtyProgressProp?.rollup?.number ??
          null;
        const qtyRequested = props["Quantity Requested"]?.number || 0;
        const baseQty =
          qtyProgress !== null && qtyProgress !== undefined ? qtyProgress : qtyRequested;

        // Use received quantity if Operations already set it
        const recQtyRaw = receivedProp ? parseNumberProp(props[receivedProp]) : null;
        const qty =
          recQtyRaw === null || recQtyRaw === undefined
            ? Number(baseQty) || 0
            : Number.isFinite(Number(recQtyRaw))
              ? Number(recQtyRaw)
              : Number(baseQty) || 0;
        const productRel = props.Product?.relation;
        const productPageId =
          Array.isArray(productRel) && productRel.length ? productRel[0].id : null;
        const prod = await productInfo(productPageId);
        const unitProp =
          _propInsensitive(props, "Unit price") ||
          _propInsensitive(props, "Unit Price") ||
          _propInsensitive(props, "Unity Price") ||
          _propInsensitive(props, "Price") ||
          null;
        const unitFromOrder = _extractPropNumber(unitProp);
        const unit = Number.isFinite(Number(unitFromOrder))
          ? Number(unitFromOrder)
          : (Number(prod.unitPrice) || 0);
        const total = (Number(qty) || 0) * unit;
        grandTotal += total;
        grandQty += Number(qty) || 0;

        rows.push({
          idCode: prod.idCode || "",
          component: prod.name,
          qty: Number(qty) || 0,
          reason,
          link: prod.url,
          unit,
          total,
        });
      }

      // Primary Reason for this order group (current orders are grouped by Reason)
      const reasonCounts = new Map();
      for (const r of rows) {
        const key = String(r?.reason || "").trim() || "No Reason";
        reasonCounts.set(key, (reasonCounts.get(key) || 0) + 1);
      }
      const groupReason =
        Array.from(reasonCounts.entries()).sort((a, b) => b[1] - a[1])[0]?.[0] || "No Reason";

      // Create workbook
      const wb = new ExcelJS.Workbook();
      wb.creator = "Operations Hub";
      const ws = wb.addWorksheet("Order");

      const formatDateTime = (date) => {
        try {
          const d = date instanceof Date ? date : new Date(date);
          if (Number.isNaN(d.getTime())) return String(date || "-");
          return d.toLocaleString("en-GB", {
            day: "2-digit",
            month: "short",
            year: "numeric",
            hour: "2-digit",
            minute: "2-digit",
          });
        } catch {
          return String(date || "-");
        }
      };

      // User requested: "make all border for tables" (strong borders)
      const borderStrong = {
        top: { style: "thin", color: { argb: "FF000000" } },
        left: { style: "thin", color: { argb: "FF000000" } },
        bottom: { style: "thin", color: { argb: "FF000000" } },
        right: { style: "thin", color: { argb: "FF000000" } },
      };

      // ---- Meta small table (top) ----
      ws.addRow(["Order ID", orderIdRange, "Date", formatDateTime(createdAt)]);
      ws.addRow([
        "Team member",
        String(teamMember || ""),
        "Prepared by (Operations)",
        String(req.session?.username || "—"),
      ]);
      ws.addRow([
        "Total quantity",
        Number(grandQty) || 0,
        "Estimate total",
        Number(grandTotal) || 0,
      ]);

      // Style meta table A1:D3
      for (let r = 1; r <= 3; r++) {
        const row = ws.getRow(r);
        row.height = 20;
        for (let c = 1; c <= 4; c++) {
          const cell = row.getCell(c);
          cell.border = borderThin;
          cell.alignment = {
            vertical: "middle",
            horizontal: "left",
            wrapText: true,
          };
        }
        // label cells
        [1, 3].forEach((c) => {
          const cell = row.getCell(c);
          cell.font = { bold: true };
          cell.fill = {
            type: "pattern",
            pattern: "solid",
            fgColor: { argb: "FFEFEFEF" },
          };
        });
        // value cells
        [2, 4].forEach((c) => {
          const cell = row.getCell(c);
          cell.font = { bold: true };
        });
      }
      ws.getRow(3).getCell(2).numFmt = "0";
      ws.getRow(3).getCell(4).numFmt = '"£"#,##0.00';

      ws.addRow([]);

      // ---- Data table (grouped by Reason, with different colors per group) ----
      const EXCEL_TAG_PALETTE = [
        { bg: "FFFDF2F8", header: "FFFCE7F3", font: "FF9D174D" }, // pink
        { bg: "FFECFDF5", header: "FFD1FAE5", font: "FF065F46" }, // green
        { bg: "FFEFF6FF", header: "FFDBEAFE", font: "FF1E40AF" }, // blue
        { bg: "FFFEFCE8", header: "FFFEF3C7", font: "FF92400E" }, // yellow
        { bg: "FFF5F3FF", header: "FFEDE9FE", font: "FF5B21B6" }, // purple
        { bg: "FFFFF7ED", header: "FFFFEDD5", font: "FF9A3412" }, // orange
        { bg: "FFF0FDFA", header: "FFCCFBF1", font: "FF115E59" }, // teal
      ];
      const hashString = (str) => {
        const s = String(str || "");
        let h = 0;
        for (let i = 0; i < s.length; i++) {
          h = (h << 5) - h + s.charCodeAt(i);
          h |= 0;
        }
        return h;
      };
      const pickExcelColors = (key) => {
        const idx = Math.abs(hashString(key)) % EXCEL_TAG_PALETTE.length;
        return EXCEL_TAG_PALETTE[idx];
      };

      // Group rows by Reason
      const reasonMap = new Map();
      for (const row of rows || []) {
        const reason = String(row.reason || "").trim() || "No Reason";
        if (!reasonMap.has(reason)) reasonMap.set(reason, []);
        reasonMap.get(reason).push(row);
      }

      let reasons = Array.from(reasonMap.keys()).sort((a, b) => String(a).localeCompare(String(b)));
      // Put No Reason at the end
      const noReasonIdx = reasons.findIndex((x) => x === "No Reason");
      if (noReasonIdx !== -1) {
        const [nr] = reasons.splice(noReasonIdx, 1);
        reasons.push(nr);
      }

      const dataHeaderCols = [
        "ID Code",
        "Component",
        "Quantity",
        "Reason",
        "Component link",
        "Unit cost",
        "Total cost",
      ];

      for (let gi = 0; gi < reasons.length; gi++) {
        const reason = reasons[gi];
        const items = (reasonMap.get(reason) || []).slice().sort((a, b) =>
          String(a?.component || "").localeCompare(String(b?.component || "")),
        );
        const colors = pickExcelColors(reason);

        // Group title row (merged across the table)
        const titleRow = ws.addRow([`Reason: ${reason} (${items.length} items)`]);
        const titleRowNum = titleRow.number;
        ws.mergeCells(`A${titleRowNum}:G${titleRowNum}`);
        const titleCell = ws.getCell(`A${titleRowNum}`);
        titleCell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: colors.bg } };
        titleCell.font = { bold: true, color: { argb: colors.font } };
        titleCell.alignment = { vertical: "middle", horizontal: "left" };
        // Add borders on the merged row
        for (let c = 1; c <= 7; c++) {
          const cell = ws.getRow(titleRowNum).getCell(c);
          cell.border = borderThin;
          cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: colors.bg } };
        }

        // Header row for this group
        const header = ws.addRow(dataHeaderCols);
        header.font = { bold: true, color: { argb: colors.font } };
        header.alignment = { vertical: "middle" };
        header.eachCell((cell) => {
          cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: colors.header } };
          cell.border = borderThin;
        });

        for (const row of items) {
          const r = ws.addRow([
            row.idCode || "",
            row.component,
            row.qty,
            row.reason,
            row.link || "",
            row.unit === null || typeof row.unit === "undefined" ? "" : Number(row.unit),
            row.total === null || typeof row.total === "undefined" ? "" : Number(row.total),
          ]);

          // hyperlink (show the actual URL text, pointing to the product website URL)
          if (row.link) {
            r.getCell(5).value = { text: row.link, hyperlink: row.link };
            r.getCell(5).font = { color: { argb: "FF2563EB" }, underline: true };
          }

          // formats
          r.getCell(3).numFmt = "0";
          r.getCell(6).numFmt = '"£"#,##0.00';
          r.getCell(7).numFmt = '"£"#,##0.00';

          // borders / alignment
          r.eachCell((cell) => {
            cell.border = borderLight;
            cell.alignment = { vertical: "middle", wrapText: true };
          });
        }

        // blank row between groups (except after last)
        if (gi !== reasons.length - 1) ws.addRow([]);
      }

      // Column widths
      ws.columns = [
        { width: 14 },
        { width: 32 },
        { width: 10 },
        { width: 24 },
        { width: 48 },
        { width: 12 },
        { width: 12 },
      ];

      // Freeze meta rows + blank row (rows 1-4)
      ws.views = [{ state: "frozen", ySplit: 4 }];

      const safeName = String(orderIdRange || "order")
        .replace(/[\\/:*?"<>|]/g, "-")
        .replace(/\s+/g, "_")
        .slice(0, 60);
      const fileName = `order_${safeName}.xlsx`;

      const buf = await wb.xlsx.writeBuffer();
      res.setHeader(
        "Content-Type",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      );
      res.setHeader(
        "Content-Disposition",
        `attachment; filename="${fileName}"; filename*=UTF-8''${encodeURIComponent(
          fileName,
        )}`,
      );
      res.setHeader("Cache-Control", "no-store");
      res.send(Buffer.from(buf));
    } catch (e) {
      console.error("export requested excel error:", e.body || e);
      res.status(500).json({ error: "Failed to export Excel" });
    }
  },
);

// ===================== Current Orders: Export (PDF / Excel) =====================

// Export current user's order group to PDF
// Body: { orderIds: [notionPageId, ...] }
app.post(
  "/api/orders/export/pdf",
  requireAuth,
  requirePage("Current Orders"),
  async (req, res) => {
    try {
      const { orderIds } = req.body || {};
      if (!Array.isArray(orderIds) || orderIds.length === 0) {
        return res.status(400).json({ error: "orderIds required" });
      }

      const ids = orderIds
        .map((x) => String(x || "").trim())
        .filter(Boolean)
        .map((x) => (looksLikeNotionId(x) ? toHyphenatedUUID(x) : x));

      if (!ids.length) return res.status(400).json({ error: "orderIds required" });

      if (_sbOrdersEnabled() && ids.every((id) => /^\d+$/.test(String(id)))) {
        return await _sbPipeOrderDeliveryPdf(req, res, ids, { tab: "current" });
      }

      const userId = await getSessionUserNotionId(req);
      if (!userId) return res.status(404).json({ error: "User not found." });

      const sameId = (a, b) => String(a || "").replace(/-/g, "") === String(b || "").replace(/-/g, "");

      const parseNumberProp = (prop) => {
        if (!prop) return null;
        try {
          if (prop.type === "number") return prop.number ?? null;
          if (prop.type === "formula") {
            if (prop.formula?.type === "number") return prop.formula.number ?? null;
            if (prop.formula?.type === "string") {
              const n = parseFloat(String(prop.formula.string || "").replace(/[^0-9.-]/g, ""));
              return Number.isFinite(n) ? n : null;
            }
          }
          if (prop.type === "rollup") {
            if (prop.rollup?.type === "number") return prop.rollup.number ?? null;
            if (prop.rollup?.type === "array") {
              const arr = prop.rollup.array || [];
              for (const x of arr) {
                if (x.type === "number" && typeof x.number === "number") return x.number;
                if (x.type === "formula" && x.formula?.type === "number") return x.formula.number;
                if (x.type === "formula" && x.formula?.type === "string") {
                  const n = parseFloat(String(x.formula.string || "").replace(/[^0-9.-]/g, ""));
                  if (Number.isFinite(n)) return n;
                }
              }
            }
          }
          if (prop.type === "rich_text") {
            const t = (prop.rich_text || []).map((r) => r.plain_text).join("").trim();
            const n = parseFloat(t.replace(/[^0-9.-]/g, ""));
            return Number.isFinite(n) ? n : null;
          }
        } catch {}
        return null;
      };

      const getPropInsensitive = (props, name) => {
        if (!props || !name) return null;
        const target = String(name).trim().toLowerCase();
        for (const [k, v] of Object.entries(props)) {
          if (String(k).trim().toLowerCase() === target) return v;
        }
        return null;
      };

      const extractUniqueIdDetails = (prop) => {
        try {
          if (!prop) return { text: null, prefix: null, number: null };
          if (prop.type === "unique_id") {
            const u = prop.unique_id;
            if (!u || typeof u.number !== "number") return { text: null, prefix: null, number: null };
            const prefix = u.prefix ? String(u.prefix).trim() : "";
            const number = u.number;
            const text = prefix ? `${prefix}-${number}` : String(number);
            return { text, prefix: prefix || null, number };
          }
        } catch {}
        return { text: null, prefix: null, number: null };
      };

      const getOrderUniqueIdDetails = (props) => {
        // Prefer the new numeric group id column: "Order - ID" (Number)
        const orderNumProp =
          getPropInsensitive(props, "Order - ID") ||
          getPropInsensitive(props, "Order ID") ||
          getPropInsensitive(props, "Order-ID") ||
          getPropInsensitive(props, "Order Id") ||
          null;
        const orderNum = _extractPropNumber(orderNumProp);
        if (Number.isFinite(Number(orderNum))) {
          const n = Number(orderNum);
          return { text: `ORD-${n}`, prefix: "ORD", number: n };
        }

        // Fallback to old unique_id column (legacy)
        const direct = getPropInsensitive(props, "ID");
        const d = extractUniqueIdDetails(direct);
        if (d.text) return d;
        for (const v of Object.values(props || {})) {
          if (v?.type === "unique_id") {
            const x = extractUniqueIdDetails(v);
            if (x.text) return x;
          }
        }
        return { text: null, prefix: null, number: null };
      };

      const computeOrderIdRange = (uids) => {
        const nums = uids.filter((u) => typeof u.number === "number");
        if (nums.length) {
          const prefix = nums[0].prefix || "";
          const samePrefix = nums.every((x) => (x.prefix || "") === prefix);
          const min = Math.min(...nums.map((x) => x.number));
          const max = Math.max(...nums.map((x) => x.number));
          if (min === max) return prefix ? `${prefix}-${min}` : String(min);
          if (samePrefix && prefix) return `${prefix}-${min} : ${prefix}-${max}`;
        }
        const texts = uids.map((u) => u.text).filter(Boolean);
        if (!texts.length) return "Order";
        if (texts.length === 1) return texts[0];
        return `${texts[0]} : ${texts[texts.length - 1]}`;
      };

      // Detect received quantity property name (Number)
      const receivedProp = (await (async () => {
        const props = await getOrdersDBProps();
        if (props[REC_PROP_HARDBIND] && props[REC_PROP_HARDBIND].type === "number") return REC_PROP_HARDBIND;
        return await detectReceivedQtyPropName();
      })());

      // Load pages
      const pagesMap = await mapWithConcurrency(ids, 3, async (id) => {
        return await notion.pages.retrieve({ page_id: id });
      });
      const pages = ids.map((id) => pagesMap.get(id)).filter(Boolean);
      if (!pages.length) return res.status(404).json({ error: "Orders not found" });

      // Validate ownership
      for (const p of pages) {
        const rel = p?.properties?.["Teams Members"]?.relation || [];
        const belongs = Array.isArray(rel) && rel.some((r) => sameId(r?.id, userId));
        if (!belongs) return res.status(403).json({ error: "Not allowed" });
      }

      // Header info
      const createdTimes = pages.map((p) => new Date(p.created_time));
      const createdAt = new Date(Math.min(...createdTimes.map((d) => d.getTime())));

      // Team member (from first page relation)
      let teamMember = "";
      const firstProps = pages[0].properties || {};
      const teamRel = firstProps["Teams Members"]?.relation;
      if (Array.isArray(teamRel) && teamRel.length) {
        teamMember = await getTeamMemberNameCached(teamRel[0].id);
      }

      const uids = pages.map((p) => getOrderUniqueIdDetails(p.properties || {}));
      const orderIdRange = computeOrderIdRange(uids);
      const receiptView = _receiptPresentationForOrderType(_extractOrderTypeInfo(firstProps).orderType);

      // Product cache
      const productCache = new Map();
      async function productInfo(productPageId) {
        if (!productPageId) return { name: "Unknown", idCode: null, unitPrice: null, url: null };
        if (productCache.has(productPageId)) return productCache.get(productPageId);
        const info = await getProductInfoCached(productPageId);
        const out = {
          name: info?.name || "Unknown",
          idCode: info?.idCode || null,
          unitPrice: typeof info?.unitPrice === "number" ? info.unitPrice : null,
          url: info?.url || null,
        };
        productCache.set(productPageId, out);
        return out;
      }

      // Build rows
      const rows = [];
      let grandTotal = 0;
      let grandQty = 0;

      for (const p of pages) {
        const props = p.properties || {};
        const reason = props.Reason?.title?.[0]?.plain_text || "";

        // Base qty: "Quantity Progress" (fallback to "Quantity Requested")
        const qtyProgressProp = props["Quantity Progress"] || props["Quantity progress"];
        const qtyProgress =
          qtyProgressProp?.number ??
          qtyProgressProp?.formula?.number ??
          qtyProgressProp?.rollup?.number ??
          null;

        const qtyRequested = props["Quantity Requested"]?.number || 0;
        const baseQty = qtyProgress !== null && qtyProgress !== undefined ? qtyProgress : qtyRequested;

        // Received qty (Operations override)
        const recQtyRaw = receivedProp ? parseNumberProp(props[receivedProp]) : null;
        const qty =
          recQtyRaw === null || recQtyRaw === undefined
            ? Number(baseQty) || 0
            : Number.isFinite(Number(recQtyRaw))
              ? Number(recQtyRaw)
              : Number(baseQty) || 0;

        const productRel = props.Product?.relation;
        const productPageId = Array.isArray(productRel) && productRel.length ? productRel[0].id : null;
        const prod = await productInfo(productPageId);
        const unitProp =
          _propInsensitive(props, "Unit price") ||
          _propInsensitive(props, "Unit Price") ||
          _propInsensitive(props, "Unity Price") ||
          _propInsensitive(props, "Price") ||
          null;
        const unitFromOrder = _extractPropNumber(unitProp);
        const unit = Number.isFinite(Number(unitFromOrder))
          ? Number(unitFromOrder)
          : (Number(prod.unitPrice) || 0);
        const total = (Number(qty) || 0) * unit;

        grandTotal += total;
        grandQty += Number(qty) || 0;

        rows.push({
          idCode: prod.idCode || "",
          component: prod.name,
          qty,
          reason,
          link: prod.url,
          unit,
          total,
        });
      }

      const safeName = String(orderIdRange || "order")
        .replace(/[\\/:*?"<>|]/g, "-")
        .replace(/\s+/g, "_")
        .slice(0, 60);
      const fileName = `${receiptView.filePrefix}_${safeName}.pdf`;

      // Primary Reason for this order group (Current Orders are grouped by Reason)
      const reasonCounts = new Map();
      for (const r of rows) {
        const key = String(r?.reason || "").trim() || "No Reason";
        reasonCounts.set(key, (reasonCounts.get(key) || 0) + 1);
      }
      const groupReason =
        Array.from(reasonCounts.entries()).sort((a, b) => b[1] - a[1])[0]?.[0] || "No Reason";

      await _sendBackgroundExport(res, {
        type: "delivery-pdf",
        fileName,
        payload: {
          orderId: orderIdRange,
          createdAt,
          teamMember,
          preparedBy: groupReason,
          rows,
          grandQty,
          grandTotal,
          metaLayout: "teamReasonFirst",
          showReasonTagBar: false,
          groupByReason: false,
          headerColorKey: groupReason,
          documentTitle: receiptView.documentTitle,
          recipientLabelLeft: receiptView.recipientLabelLeft,
          thirdSignatureLabel: receiptView.thirdSignatureLabel,
          signatureLabels: receiptView.signatureLabels,
          showFooterSignature: false,
        },
      });
    } catch (e) {
      console.error("export current pdf error:", e?.body || e);
      try {
        if (!res.headersSent) res.status(_exportErrorStatus(e)).json({ error: e?.message || "Failed to export PDF" });
      } catch {}
    }
  },
);

// Export current user's order group to Excel
// Body: { orderIds: [notionPageId, ...] }
app.post(
  "/api/orders/export/excel",
  requireAuth,
  requirePage("Current Orders"),
  async (req, res) => {
    try {
      const ExcelJS = require("exceljs");
      const { orderIds } = req.body || {};
      if (!Array.isArray(orderIds) || orderIds.length === 0) {
        return res.status(400).json({ error: "orderIds required" });
      }

      const ids = orderIds
        .map((x) => String(x || "").trim())
        .filter(Boolean)
        .map((x) => (looksLikeNotionId(x) ? toHyphenatedUUID(x) : x));
      if (!ids.length) return res.status(400).json({ error: "orderIds required" });

      if (_sbOrdersEnabled() && ids.every((id) => /^\d+$/.test(String(id)))) {
        return await _sbPipeOrderExcel(req, res, ids);
      }

      const userId = await getSessionUserNotionId(req);
      if (!userId) return res.status(404).json({ error: "User not found." });

      const sameId = (a, b) => String(a || "").replace(/-/g, "") === String(b || "").replace(/-/g, "");

      // Helpers
      const parseNumberProp = (prop) => {
        if (!prop) return null;
        try {
          if (prop.type === "number") return prop.number ?? null;
          if (prop.type === "formula") {
            if (prop.formula?.type === "number") return prop.formula.number ?? null;
            if (prop.formula?.type === "string") {
              const n = parseFloat(String(prop.formula.string || "").replace(/[^0-9.-]/g, ""));
              return Number.isFinite(n) ? n : null;
            }
          }
          if (prop.type === "rollup") {
            if (prop.rollup?.type === "number") return prop.rollup.number ?? null;
            if (prop.rollup?.type === "array") {
              const arr = prop.rollup.array || [];
              for (const x of arr) {
                if (x.type === "number" && typeof x.number === "number") return x.number;
                if (x.type === "formula" && x.formula?.type === "number") return x.formula.number;
                if (x.type === "formula" && x.formula?.type === "string") {
                  const n = parseFloat(String(x.formula.string || "").replace(/[^0-9.-]/g, ""));
                  if (Number.isFinite(n)) return n;
                }
              }
            }
          }
        } catch {}
        return null;
      };

      const getPropInsensitive = (props, name) => {
        if (!props || !name) return null;
        const target = String(name).trim().toLowerCase();
        for (const [k, v] of Object.entries(props)) {
          if (String(k).trim().toLowerCase() === target) return v;
        }
        return null;
      };

      const extractUniqueIdDetails = (prop) => {
        try {
          if (!prop) return { text: null, prefix: null, number: null };
          if (prop.type === "unique_id") {
            const u = prop.unique_id;
            if (!u || typeof u.number !== "number") return { text: null, prefix: null, number: null };
            const prefix = u.prefix ? String(u.prefix).trim() : "";
            const number = u.number;
            const text = prefix ? `${prefix}-${number}` : String(number);
            return { text, prefix: prefix || null, number };
          }
        } catch {}
        return { text: null, prefix: null, number: null };
      };

      const getOrderUniqueIdDetails = (props) => {
        // Prefer the new numeric group id column: "Order - ID" (Number)
        const orderNumProp =
          getPropInsensitive(props, "Order - ID") ||
          getPropInsensitive(props, "Order ID") ||
          getPropInsensitive(props, "Order-ID") ||
          getPropInsensitive(props, "Order Id") ||
          null;
        const orderNum = _extractPropNumber(orderNumProp);
        if (Number.isFinite(Number(orderNum))) {
          const n = Number(orderNum);
          return { text: `ORD-${n}`, prefix: "ORD", number: n };
        }

        // Fallback to old unique_id column (legacy)
        const direct = getPropInsensitive(props, "ID");
        const d = extractUniqueIdDetails(direct);
        if (d.text) return d;
        for (const v of Object.values(props || {})) {
          if (v?.type === "unique_id") {
            const x = extractUniqueIdDetails(v);
            if (x.text) return x;
          }
        }
        return { text: null, prefix: null, number: null };
      };

      const computeOrderIdRange = (uids) => {
        const nums = uids.filter((u) => typeof u.number === "number");
        if (nums.length) {
          const prefix = nums[0].prefix || "";
          const samePrefix = nums.every((x) => (x.prefix || "") === prefix);
          const min = Math.min(...nums.map((x) => x.number));
          const max = Math.max(...nums.map((x) => x.number));
          if (min === max) return prefix ? `${prefix}-${min}` : String(min);
          if (samePrefix && prefix) return `${prefix}-${min} : ${prefix}-${max}`;
        }
        const texts = uids.map((u) => u.text).filter(Boolean);
        if (!texts.length) return "Order";
        if (texts.length === 1) return texts[0];
        return `${texts[0]} : ${texts[texts.length - 1]}`;
      };

      // Received Quantity property (Number)
      const receivedProp = (await (async () => {
        const props = await getOrdersDBProps();
        if (props[REC_PROP_HARDBIND] && props[REC_PROP_HARDBIND].type === "number") return REC_PROP_HARDBIND;
        return await detectReceivedQtyPropName();
      })());

      // Load pages
      const pagesMap = await mapWithConcurrency(ids, 3, async (id) => {
        return await notion.pages.retrieve({ page_id: id });
      });
      const pages = ids.map((id) => pagesMap.get(id)).filter(Boolean);
      if (!pages.length) return res.status(404).json({ error: "Orders not found" });

      // Validate ownership
      for (const p of pages) {
        const rel = p?.properties?.["Teams Members"]?.relation || [];
        const belongs = Array.isArray(rel) && rel.some((r) => sameId(r?.id, userId));
        if (!belongs) return res.status(403).json({ error: "Not allowed" });
      }

      // Derive order header info
      const createdTimes = pages.map((p) => new Date(p.created_time));
      const createdAt = new Date(Math.min(...createdTimes.map((d) => d.getTime())));

      // Team member (from first page relation)
      let teamMember = "";
      const firstProps = pages[0].properties || {};
      const teamRel = firstProps["Teams Members"]?.relation;
      if (Array.isArray(teamRel) && teamRel.length) {
        teamMember = await getTeamMemberNameCached(teamRel[0].id);
      }

      const uids = pages.map((p) => getOrderUniqueIdDetails(p.properties || {}));
      const orderIdRange = computeOrderIdRange(uids);

      // Product cache
      const productCache = new Map();
      async function productInfo(productPageId) {
        if (!productPageId) return { name: "Unknown", idCode: null, unitPrice: null, url: null };
        if (productCache.has(productPageId)) return productCache.get(productPageId);
        const info = await getProductInfoCached(productPageId);
        const out = {
          name: info?.name || "Unknown",
          idCode: info?.idCode || null,
          unitPrice: typeof info?.unitPrice === "number" ? info.unitPrice : null,
          url: info?.url || null,
        };
        productCache.set(productPageId, out);
        return out;
      }

      // Build rows
      const rows = [];
      let grandTotal = 0;
      let grandQty = 0;

      for (const p of pages) {
        const props = p.properties || {};
        const reason = props.Reason?.title?.[0]?.plain_text || "";

        const qtyProgressProp = props["Quantity Progress"] || props["Quantity progress"];
        const qtyProgress =
          qtyProgressProp?.number ??
          qtyProgressProp?.formula?.number ??
          qtyProgressProp?.rollup?.number ??
          null;
        const qtyRequested = props["Quantity Requested"]?.number || 0;
        const baseQty = qtyProgress !== null && qtyProgress !== undefined ? qtyProgress : qtyRequested;

        const recQtyRaw = receivedProp ? parseNumberProp(props[receivedProp]) : null;
        const qty =
          recQtyRaw === null || recQtyRaw === undefined
            ? Number(baseQty) || 0
            : Number.isFinite(Number(recQtyRaw))
              ? Number(recQtyRaw)
              : Number(baseQty) || 0;

        const productRel = props.Product?.relation;
        const productPageId = Array.isArray(productRel) && productRel.length ? productRel[0].id : null;
        const prod = await productInfo(productPageId);
        const unitProp =
          _propInsensitive(props, "Unit price") ||
          _propInsensitive(props, "Unit Price") ||
          _propInsensitive(props, "Unity Price") ||
          _propInsensitive(props, "Price") ||
          null;
        const unitFromOrder = _extractPropNumber(unitProp);
        const unit = Number.isFinite(Number(unitFromOrder))
          ? Number(unitFromOrder)
          : (Number(prod.unitPrice) || 0);
        const total = (Number(qty) || 0) * unit;
        grandTotal += total;
        grandQty += Number(qty) || 0;

        rows.push({
          idCode: prod.idCode || "",
          component: prod.name,
          qty: Number(qty) || 0,
          reason,
          link: prod.url,
          unit,
          total,
        });
      }

      // Primary Reason for this order group (Current Orders are grouped by Reason)
      const reasonCounts = new Map();
      for (const r of rows) {
        const key = String(r?.reason || "").trim() || "No Reason";
        reasonCounts.set(key, (reasonCounts.get(key) || 0) + 1);
      }
      const groupReason =
        Array.from(reasonCounts.entries()).sort((a, b) => b[1] - a[1])[0]?.[0] || "No Reason";

      // Create workbook
      const wb = new ExcelJS.Workbook();
      wb.creator = "Operations Hub";
      const ws = wb.addWorksheet("Order");

      const formatDateTime = (date) => {
        try {
          const d = date instanceof Date ? date : new Date(date);
          if (Number.isNaN(d.getTime())) return String(date || "-");
          return d.toLocaleString("en-GB", {
            day: "2-digit",
            month: "short",
            year: "numeric",
            hour: "2-digit",
            minute: "2-digit",
          });
        } catch {
          return String(date || "-");
        }
      };

      // User requested: "make all boarder for tables" (strong borders)
      const borderStrong = {
        top: { style: "thin", color: { argb: "FF000000" } },
        left: { style: "thin", color: { argb: "FF000000" } },
        bottom: { style: "thin", color: { argb: "FF000000" } },
        right: { style: "thin", color: { argb: "FF000000" } },
      };

      // ---- Meta small table (top) ----
      // Requested layout for Current Orders:
      // Team member | Reason
      // Order ID     | Date
      ws.addRow(["Team member", String(teamMember || ""), "Reason", String(groupReason || "")]);
      ws.addRow(["Order ID", orderIdRange, "Date", formatDateTime(createdAt)]);

      // Keep a useful summary row (matches UI: Components + Estimated cost)
      ws.addRow(["Components", Number(rows.length) || 0, "Estimate total", Number(grandTotal) || 0]);

      // Style meta table A1:D3
      for (let r = 1; r <= 3; r++) {
        const row = ws.getRow(r);
        row.height = 20;
        for (let c = 1; c <= 4; c++) {
          const cell = row.getCell(c);
          cell.border = borderStrong;
          cell.alignment = { vertical: "middle", horizontal: "left", wrapText: true };
        }
        [1, 3].forEach((c) => {
          const cell = row.getCell(c);
          cell.font = { bold: true };
          cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFEFEFEF" } };
        });
        [2, 4].forEach((c) => {
          const cell = row.getCell(c);
          cell.font = { bold: true };
        });
      }
      ws.getRow(3).getCell(2).numFmt = "0";
      ws.getRow(3).getCell(4).numFmt = '"£"#,##0.00';

      ws.addRow([]);

      // ---- Data table ----
      const EXCEL_TAG_PALETTE = [
        { bg: "FFFDF2F8", header: "FFFCE7F3", font: "FF9D174D" },
        { bg: "FFECFDF5", header: "FFD1FAE5", font: "FF065F46" },
        { bg: "FFEFF6FF", header: "FFDBEAFE", font: "FF1E40AF" },
        { bg: "FFFEFCE8", header: "FFFEF3C7", font: "FF92400E" },
        { bg: "FFF5F3FF", header: "FFEDE9FE", font: "FF5B21B6" },
        { bg: "FFFFF7ED", header: "FFFFEDD5", font: "FF9A3412" },
        { bg: "FFF0FDFA", header: "FFCCFBF1", font: "FF115E59" },
      ];
      const hashString = (str) => {
        const s = String(str || "");
        let h = 0;
        for (let i = 0; i < s.length; i++) {
          h = (h << 5) - h + s.charCodeAt(i);
          h |= 0;
        }
        return h;
      };
      const pickExcelColors = (key) => {
        const idx = Math.abs(hashString(key)) % EXCEL_TAG_PALETTE.length;
        return EXCEL_TAG_PALETTE[idx];
      };

      const dataHeaderCols = [
        "ID Code",
        "Component",
        "Quantity",
        "Unit cost",
        "Total cost",
      ];


      // Color the table header using the primary Reason (no separate Reason bar row)
      const colors = pickExcelColors(String(groupReason || "Order"));
      const header = ws.addRow(dataHeaderCols);
      header.font = { bold: true, color: { argb: colors.font } };
      header.alignment = { vertical: "middle" };
      header.eachCell((cell) => {
        cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: colors.header } };
        cell.border = borderStrong;
      });

      const items = (rows || []).slice().sort((a, b) =>
        String(a?.component || "").localeCompare(String(b?.component || "")),
      );

      for (const row of items) {
        const r = ws.addRow([
          row.idCode || "",
          row.component,
          row.qty,
          row.unit === null || typeof row.unit === "undefined" ? "" : Number(row.unit),
          row.total === null || typeof row.total === "undefined" ? "" : Number(row.total),
        ]);

        if (row.link) {
          // Make the component name clickable
          r.getCell(2).value = { text: row.component, hyperlink: row.link };
          r.getCell(2).font = { color: { argb: "FF2563EB" }, underline: true };
        }

        r.getCell(3).numFmt = "0";
        r.getCell(4).numFmt = '"£"#,##0.00';
        r.getCell(5).numFmt = '"£"#,##0.00';

        r.eachCell((cell) => {
          cell.border = borderStrong;
          cell.alignment = { vertical: "middle", wrapText: true };
        });
      }

      ws.columns = [
        { width: 14 },
        { width: 36 },
        { width: 10 },
        { width: 12 },
        { width: 12 },
      ];
      ws.views = [{ state: "frozen", ySplit: 4 }];

      const safeName = String(orderIdRange || "order")
        .replace(/[\\/:*?"<>|]/g, "-")
        .replace(/\s+/g, "_")
        .slice(0, 60);
      const fileName = `order_${safeName}.xlsx`;

      const buf = await wb.xlsx.writeBuffer();
      res.setHeader(
        "Content-Type",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      );
      res.setHeader(
        "Content-Disposition",
        `attachment; filename="${fileName}"; filename*=UTF-8''${encodeURIComponent(fileName)}`,
      );
      res.setHeader("Cache-Control", "no-store");
      res.send(Buffer.from(buf));
    } catch (e) {
      console.error("export current excel error:", e?.body || e);
      res.status(500).json({ error: "Failed to export Excel" });
    }
  },
);

// -----------------------------------------------------------------------------
// Events Module — independent event requests and event components catalog
// -----------------------------------------------------------------------------
function _sbEventsTable() {
  return String(process.env.SUPABASE_EVENTS_TABLE || 'events').trim() || 'events';
}

function _sbEventComponentsTable() {
  return String(process.env.SUPABASE_EVENT_COMPONENTS_TABLE || 'event_components').trim() || 'event_components';
}

function _sbEventTypesTable() {
  return String(process.env.SUPABASE_EVENT_TYPES_TABLE || 'event_type_catalog').trim() || 'event_type_catalog';
}

function _sbEventComponentCategoriesTable() {
  return String(process.env.SUPABASE_EVENT_COMPONENT_CATEGORIES_TABLE || 'event_component_category_catalog').trim() || 'event_component_category_catalog';
}

function _sbEventsGovernorateRatesTable() {
  return String(process.env.SUPABASE_EVENTS_GOVERNORATE_RATES_TABLE || 'event_governorate_transport_rates').trim() || 'event_governorate_transport_rates';
}

function _sbEventsEnabled() {
  return supabaseDb.isConfigured();
}

function _eventsText(value, maxLength = 500) {
  return String(value ?? '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, maxLength);
}

function _eventsLongText(value, maxLength = 5000) {
  return String(value ?? '').replace(/\u0000/g, '').trim().slice(0, maxLength);
}

function _eventsUuid(value) {
  const id = String(value || '').trim();
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id) ? id : '';
}

function _eventsDateTime(value) {
  const raw = String(value || '').trim();
  if (!raw) return null;
  // Preserve legacy date-only records as a midnight UTC timestamp while all
  // new event requests send a full ISO timestamp from the browser.
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return `${raw}T00:00:00.000Z`;
  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
}

function _eventsNumber(value, { min = 0, max = 1000000, fallback = 0, integer = false } = {}) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  const safe = Math.max(min, Math.min(max, parsed));
  return integer ? Math.round(safe) : safe;
}

function _eventsBoolean(value) {
  return value === true || value === 1 || String(value || '').trim().toLowerCase() === 'true';
}

function _eventsArray(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }
  return [];
}

const EVENTS_STANDARD_TYPE_OPTIONS = Object.freeze([
  { code: 'tech_day', label: 'Tech Day', isCustom: false },
  { code: 'seminar', label: 'Seminar', isCustom: false },
  { code: 'steam_fair', label: 'STEAM Fair', isCustom: false },
  { code: 'competition', label: 'Competition', isCustom: false },
  { code: 'exhibition', label: 'Exhibition', isCustom: false },
]);
const EVENTS_TYPES = new Set([...EVENTS_STANDARD_TYPE_OPTIONS.map((item) => item.code), 'other']);
const EVENTS_STATUSES = new Set(['submitted', 'in_progress', 'completed', 'cancelled']);
const EVENTS_STANDARD_COMPONENT_CATEGORY_OPTIONS = Object.freeze([
  { code: 'project', label: 'Project Resource', isCustom: false },
  { code: 'marketing_material', label: 'Marketing Material', isCustom: false },
  { code: 'venue_equipment', label: 'Venue Equipment', isCustom: false },
]);
const EVENT_COMPONENT_CATEGORIES = new Set([...EVENTS_STANDARD_COMPONENT_CATEGORY_OPTIONS.map((item) => item.code), 'other']);
const EVENT_COMPONENT_OWNERSHIP_TYPES = new Set(['company_owned', 'external_rental']);

function _eventsTypeCode(value) {
  return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 72);
}

function _eventsNormalizeType(value) {
  const raw = _eventsTypeCode(value);
  if (EVENTS_TYPES.has(raw)) return raw;
  return /^custom_[a-z0-9_]{1,64}$/.test(raw) ? raw : 'other';
}

function _eventsNormalizeStatus(value) {
  const raw = String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  // The Events workflow no longer uses separate Under review or Approved states.
  // Legacy records are displayed and handled as Submitted so they remain visible.
  if (raw === 'under_review' || raw === 'approved') return 'submitted';
  return EVENTS_STATUSES.has(raw) ? raw : 'submitted';
}

function _eventsNormalizeComponentCategory(value) {
  const raw = String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  if (EVENT_COMPONENT_CATEGORIES.has(raw)) return raw;
  return /^custom_[a-z0-9_]{1,64}$/.test(raw) ? raw : 'other';
}


function _eventsNormalizeComponentOwnership(value) {
  const raw = String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  return EVENT_COMPONENT_OWNERSHIP_TYPES.has(raw) ? raw : 'company_owned';
}

function _eventsCost(value, fallback = 0) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.round(Math.max(0, Math.min(100000000, parsed)) * 100) / 100;
}

function _eventsComponentUnitCost(ownershipType, operatingCost, rentalCost) {
  const operating = _eventsCost(operatingCost, 0);
  const rental = _eventsNormalizeComponentOwnership(ownershipType) === 'external_rental'
    ? _eventsCost(rentalCost, 0)
    : 0;
  return Math.round((operating + rental) * 100) / 100;
}

function _eventsNormalizeProjects(value) {
  return _eventsArray(value)
    .slice(0, 50)
    .map((row) => ({
      title: _eventsText(row?.title || row?.name, 180),
      description: _eventsLongText(row?.description, 1500),
      quantity: _eventsNumber(row?.quantity, { min: 0, max: 100000, fallback: 1, integer: true }),
      workingCost: _eventsCost(row?.workingCost ?? row?.working_cost ?? row?.cost, 0),
      notes: _eventsLongText(row?.notes, 1500),
    }))
    .filter((row) => row.title);
}

function _eventsNormalizeComponentRows(value) {
  return _eventsArray(value)
    .slice(0, 100)
    .map((row) => {
      const quantity = _eventsNumber(row?.quantity, { min: 0, max: 100000, fallback: 1 });
      const ownershipType = _eventsNormalizeComponentOwnership(row?.ownershipType || row?.ownership_type);
      const operatingCost = _eventsCost(row?.operatingCost ?? row?.operating_cost, 0);
      const rentalCost = ownershipType === 'external_rental' ? _eventsCost(row?.rentalCost ?? row?.rental_cost, 0) : 0;
      const unitCost = _eventsComponentUnitCost(ownershipType, operatingCost, rentalCost);
      return {
        componentId: _eventsUuid(row?.componentId || row?.component_id || row?.id) || null,
        name: _eventsText(row?.name || row?.componentName || row?.component_name, 180),
        quantity,
        notes: _eventsLongText(row?.notes, 1000),
        ownershipType,
        operatingCost,
        rentalCost,
        unitCost,
        totalCost: Math.round((unitCost * quantity) * 100) / 100,
        linkUrl: _eventsHttpUrl(row?.linkUrl || row?.link_url, 1000),
        photoUrl: _eventsHttpUrl(row?.photoUrl || row?.photo_url, 2000),
      };
    })
    .filter((row) => row.name);
}

async function _eventsResolveComponentRows(value, expectedCategory = '') {
  const submittedRows = _eventsNormalizeComponentRows(value);
  if (!submittedRows.length) return [];
  const expectedCategoryCode = String(expectedCategory || '').trim() ? _eventsNormalizeComponentCategory(expectedCategory) : '';
  const catalogRows = await supabaseDb.selectAll(_sbEventComponentsTable(), { limit: 1000, order: 'name.asc' });
  const catalog = new Map((Array.isArray(catalogRows) ? catalogRows : []).map((row) => {
    const serialized = _eventsSerializeComponent(row);
    return [serialized.id, serialized];
  }));

  return submittedRows.map((submitted) => {
    const component = submitted.componentId ? catalog.get(submitted.componentId) : null;
    if (!component) return submitted;
    if (expectedCategoryCode && String(component.category || '') !== expectedCategoryCode) {
      const expectedLabels = {
        project: 'Project Resource',
        marketing_material: 'Marketing Material',
        venue_equipment: 'Venue Equipment',
      };
      const error = new Error(`Selected component "${component.name}" must be from the ${expectedLabels[expectedCategoryCode] || 'required'} category.`);
      error.status = 400;
      throw error;
    }
    const ownershipType = _eventsNormalizeComponentOwnership(component.ownershipType);
    const operatingCost = _eventsCost(component.operatingCost, 0);
    const rentalCost = ownershipType === 'external_rental' ? _eventsCost(component.rentalCost, 0) : 0;
    const unitCost = _eventsComponentUnitCost(ownershipType, operatingCost, rentalCost);
    return {
      componentId: component.id || submitted.componentId,
      name: component.name || submitted.name,
      quantity: submitted.quantity,
      notes: submitted.notes,
      ownershipType,
      operatingCost,
      rentalCost,
      unitCost,
      totalCost: Math.round((unitCost * submitted.quantity) * 100) / 100,
      linkUrl: component.linkUrl || '',
      photoUrl: component.photoUrl || '',
    };
  });
}

function _eventsHttpUrl(value, maxLength = 1000) {
  const raw = _eventsText(value, maxLength);
  if (!raw) return '';
  try {
    const url = new URL(raw);
    return /^https?:$/i.test(url.protocol) ? url.href.slice(0, maxLength) : '';
  } catch {
    return '';
  }
}

// Transport is estimated by the selected governorate/area. Each event stores a
// snapshot of the per-governorate rate used at submission time so future rate
// changes do not modify historic event budgets.
function _eventsGoogleMapsUrl(value, maxLength = 2000) {
  const raw = _eventsHttpUrl(value, maxLength);
  if (!raw) return '';
  try {
    const url = new URL(raw);
    const host = String(url.hostname || '').toLowerCase().replace(/^www\./, '');
    const path = String(url.pathname || '');
    const isGoogleDomain = /(^|\.)google\.[a-z.]+$/i.test(host);
    const isMapsShortLink = host === 'maps.app.goo.gl' || (host === 'goo.gl' && /^\/maps(?:\/|$)/i.test(path));
    const isGoogleMapsPath = isGoogleDomain && (
      host === 'maps.google.com' ||
      /^\/maps(?:\/|$)/i.test(path) ||
      /(?:^|[?&])(?:q|query|ll|destination|origin|place_id)=/i.test(url.search)
    );
    return isMapsShortLink || isGoogleMapsPath ? url.href.slice(0, maxLength) : '';
  } catch {
    return '';
  }
}

function _eventsRoundMoney(value) {
  return Math.round(Math.max(0, Number(value || 0) || 0) * 100) / 100;
}

function _eventsGovernorateKey(value) {
  return _eventsText(value, 120).toLocaleLowerCase().replace(/\s+/g, ' ').trim();
}

function _eventsSerializeGovernorateRate(row = {}) {
  return {
    id: String(row?.id || ''),
    areaName: _eventsText(row?.area_name || row?.areaName, 120),
    transportCost: _eventsCost(row?.transport_cost ?? row?.transportCost, 0),
    isActive: row?.is_active !== false,
    sortOrder: _eventsNumber(row?.sort_order ?? row?.sortOrder, { min: 0, max: 100000, fallback: 100, integer: true }),
    updatedAt: row?.updated_at || row?.updatedAt || null,
  };
}

async function _eventsListGovernorateRates({ includeInactive = false } = {}) {
  const table = _sbEventsGovernorateRatesTable();
  const params = ['select=*', 'order=sort_order.asc,area_name.asc', 'limit=1000'];
  if (!includeInactive) params.push('is_active=eq.true');
  const rows = await supabaseDb.request(`/${encodeURIComponent(table)}?${params.join('&')}`);
  return (Array.isArray(rows) ? rows : []).map(_eventsSerializeGovernorateRate)
    .filter((item) => item.areaName);
}

async function _eventsFindGovernorateRate(areaName) {
  const key = _eventsGovernorateKey(areaName);
  if (!key) return null;
  const rates = await _eventsListGovernorateRates();
  return rates.find((item) => _eventsGovernorateKey(item.areaName) === key) || null;
}

async function _eventsCalculateGovernorateTransportQuote(areaName) {
  const governorate = _eventsText(areaName, 120);
  if (!governorate) {
    const error = new Error('Governorate is required to calculate transport cost.');
    error.status = 400;
    throw error;
  }
  const rate = await _eventsFindGovernorateRate(governorate);
  if (!rate) {
    const error = new Error(`Transport cost for ${governorate} is not configured. Ask an Events Admin to add this governorate or area.`);
    error.status = 400;
    throw error;
  }
  const transportRate = _eventsCost(rate.transportCost, 0);
  return {
    governorate: rate.areaName,
    transportRate,
    transportCost: _eventsRoundMoney(transportRate * 2),
    calculation: 'governorate_x2',
  };
}

async function _eventsSaveGovernorateRates(body = {}, req) {
  const requested = _eventsArray(body?.rates).slice(0, 200);
  if (!requested.length) {
    const error = new Error('Add at least one governorate or area rate.');
    error.status = 400;
    throw error;
  }

  const cleaned = [];
  const seen = new Set();
  for (let index = 0; index < requested.length; index += 1) {
    const source = requested[index] || {};
    const id = _eventsUuid(source?.id);
    const areaName = _eventsText(source?.areaName || source?.area_name, 120);
    if (!areaName) continue;
    const key = _eventsGovernorateKey(areaName);
    if (seen.has(key)) {
      const error = new Error(`Duplicate governorate/area: ${areaName}.`);
      error.status = 400;
      throw error;
    }
    seen.add(key);
    cleaned.push({
      id,
      areaName,
      transportCost: _eventsCost(source?.transportCost ?? source?.transport_cost, 0),
      isActive: source?.isActive !== false,
      sortOrder: _eventsNumber(source?.sortOrder ?? source?.sort_order, { min: 0, max: 100000, fallback: index + 1, integer: true }),
    });
  }
  if (!cleaned.length) {
    const error = new Error('Add a valid governorate or area name.');
    error.status = 400;
    throw error;
  }

  const table = _sbEventsGovernorateRatesTable();
  const existing = await _eventsListGovernorateRates({ includeInactive: true });
  const existingById = new Map(existing.map((item) => [item.id, item]));
  const existingByKey = new Map(existing.map((item) => [_eventsGovernorateKey(item.areaName), item]));
  const saved = [];

  for (const rate of cleaned) {
    const existingRow = (rate.id && existingById.get(rate.id)) || existingByKey.get(_eventsGovernorateKey(rate.areaName)) || null;
    const payload = {
      area_name: rate.areaName,
      transport_cost: rate.transportCost,
      is_active: rate.isActive,
      sort_order: rate.sortOrder,
      updated_by_user_id: _eventsUuid(req?.session?.userSupabaseId) || null,
    };
    const row = existingRow?.id
      ? await supabaseDb.updateById(table, existingRow.id, payload)
      : await supabaseDb.insert(table, payload);
    saved.push(_eventsSerializeGovernorateRate(row || payload));
  }
  return saved;
}

function _eventsWorkingCost(projects = [], marketingMaterials = [], venueRequirements = []) {
  const projectCost = (Array.isArray(projects) ? projects : []).reduce((total, row) => total + _eventsCost(row?.workingCost ?? row?.working_cost, 0), 0);
  const componentCost = [...(Array.isArray(marketingMaterials) ? marketingMaterials : []), ...(Array.isArray(venueRequirements) ? venueRequirements : [])]
    .reduce((total, row) => total + _eventsCost(row?.totalCost ?? row?.total_cost, 0), 0);
  return _eventsRoundMoney(projectCost + componentCost);
}

function _eventsSerializeType(row = {}) {
  const code = _eventsNormalizeType(row?.code);
  const label = _eventsText(row?.label, 80);
  return {
    code: /^custom_/.test(code) ? code : '',
    label,
    isCustom: true,
    isActive: row?.is_active !== false,
    createdAt: row?.created_at || null,
  };
}

function _eventsTypeLabelKey(value) {
  return _eventsText(value, 80).toLocaleLowerCase().replace(/\s+/g, ' ').trim();
}

function _eventsCustomTypeCode(label, usedCodes = new Set()) {
  const baseSlug = _eventsTypeCode(label).replace(/^custom_/, '') || 'event_type';
  const base = `custom_${baseSlug.slice(0, 52)}`;
  let code = base;
  let index = 2;
  while (usedCodes.has(code)) {
    code = `${base.slice(0, Math.max(1, 66 - String(index).length))}_${index}`;
    index += 1;
  }
  return code;
}

async function _eventsListTypeOptions() {
  const rows = await supabaseDb.selectAll(_sbEventTypesTable(), { limit: 1000, order: 'label.asc' });
  const standard = EVENTS_STANDARD_TYPE_OPTIONS.map((item) => ({ ...item }));
  const seenCodes = new Set(standard.map((item) => item.code));
  const custom = (Array.isArray(rows) ? rows : [])
    .map(_eventsSerializeType)
    .filter((item) => item.code && item.label && item.isActive !== false && !seenCodes.has(item.code));
  return [...standard, ...custom];
}

async function _eventsCreateTypeOption(label) {
  const cleanLabel = _eventsText(label, 80);
  if (!cleanLabel) {
    const error = new Error('Event type name is required.');
    error.status = 400;
    throw error;
  }

  const existing = await _eventsListTypeOptions();
  const key = _eventsTypeLabelKey(cleanLabel);
  const same = existing.find((item) => _eventsTypeLabelKey(item.label) === key);
  if (same) return same;

  const usedCodes = new Set(existing.map((item) => item.code).filter(Boolean));
  const code = _eventsCustomTypeCode(cleanLabel, usedCodes);
  const inserted = await supabaseDb.insert(_sbEventTypesTable(), {
    code,
    label: cleanLabel,
    is_active: true,
  });
  const saved = _eventsSerializeType(inserted || {});
  if (!saved.code || !saved.label) {
    const error = new Error('Event type could not be saved.');
    error.status = 500;
    throw error;
  }
  return saved;
}

async function _eventsResolveRequestType(body = {}) {
  const requested = _eventsNormalizeType(body?.eventType || body?.event_type);
  if (EVENTS_TYPES.has(requested)) {
    const customLabel = _eventsText(body?.eventTypeCustom || body?.event_type_custom, 80);
    if (requested === 'other' && customLabel) {
      const custom = await _eventsCreateTypeOption(customLabel);
      return { code: custom.code, label: custom.label };
    }
    return { code: requested, label: null };
  }

  const options = await _eventsListTypeOptions();
  const matched = options.find((item) => item.code === requested && item.isCustom);
  if (!matched) {
    const error = new Error('The selected event type is not available. Please select an existing type or add a new one under Other.');
    error.status = 400;
    throw error;
  }
  return { code: matched.code, label: matched.label };
}


