async function _eventsRequestWriteRow(body = {}, req) {
  const startDate = _eventsDateTime(body?.eventStartDate || body?.event_start_date);
  const endDate = _eventsDateTime(body?.eventEndDate || body?.event_end_date);
  if (!startDate) {
    const error = new Error('Event start date and time are required.');
    error.status = 400;
    throw error;
  }
  if (endDate && new Date(endDate).getTime() < new Date(startDate).getTime()) {
    const error = new Error('End date and time cannot be before the start date and time.');
    error.status = 400;
    throw error;
  }

  const eventName = _eventsText(body?.eventName || body?.event_name, 240);
  if (!eventName) {
    const error = new Error('Event name is required.');
    error.status = 400;
    throw error;
  }

  const locationUrl = _eventsGoogleMapsUrl(body?.locationUrl || body?.location_url, 2000);
  if (!locationUrl) {
    const error = new Error('Google Maps / Location URL is required. Paste a Google Maps link such as https://www.google.com/maps/... or https://maps.app.goo.gl/...');
    error.status = 400;
    throw error;
  }

  const governorate = _eventsText(body?.governorate, 120);
  if (!governorate) {
    const error = new Error('Governorate is required.');
    error.status = 400;
    throw error;
  }
  const eventType = await _eventsResolveRequestType(body);
  const projects = _eventsNormalizeProjects(body?.projects);
  const marketingMaterials = await _eventsResolveComponentRows(body?.marketingMaterials || body?.marketing_materials, 'marketing_material');
  const venueRequirements = await _eventsResolveComponentRows(body?.venueRequirements || body?.venue_requirements, 'venue_equipment');
  const workingCost = _eventsWorkingCost(projects, marketingMaterials, venueRequirements);
  const transport = await _eventsCalculateGovernorateTransportQuote(governorate);
  const totalCost = _eventsRoundMoney(workingCost + transport.transportCost);
  const requesterName = _eventsText(
    req?.session?.accountCache?.name || req?.session?.username || body?.requesterName,
    160,
  );
  const currentTeamMember = await _sbFindSessionTeamMember(req).catch(() => null);
  const requesterId = _eventsUuid(
    _sbGet(currentTeamMember || {}, ['id', 'ID']) || req?.session?.userSupabaseId
  );

  return {
    event_name: eventName,
    event_type: eventType.code,
    event_type_custom: eventType.label || null,
    status: 'submitted',
    organization_name: _eventsText(body?.organizationName || body?.organization_name, 240) || null,
    contact_person: _eventsText(body?.contactPerson || body?.contact_person, 160) || null,
    contact_phone: _eventsText(body?.contactPhone || body?.contact_phone, 80) || null,
    contact_email: _eventsText(body?.contactEmail || body?.contact_email, 200) || null,
    event_start_date: startDate,
    event_end_date: endDate,
    expected_attendees: _eventsNumber(body?.expectedAttendees || body?.expected_attendees, { min: 0, max: 1000000, fallback: 0, integer: true }),
    audience: _eventsLongText(body?.audience, 1000) || null,
    projects,
    marketing_materials: marketingMaterials,
    venue_requirements: venueRequirements,
    venue_name: _eventsText(body?.venueName || body?.venue_name, 240) || null,
    venue_type: _eventsText(body?.venueType || body?.venue_type, 120) || null,
    governorate: transport.governorate || governorate,
    location_url: locationUrl,
    venue_setup_time: _eventsDateTime(body?.venueSetupTime || body?.venue_setup_time) || null,
    requires_power: _eventsBoolean(body?.requiresPower || body?.requires_power),
    requires_internet: _eventsBoolean(body?.requiresInternet || body?.requires_internet),
    requires_sound_system: _eventsBoolean(body?.requiresSoundSystem || body?.requires_sound_system),
    venue_notes: _eventsLongText(body?.venueNotes || body?.venue_notes, 3000) || null,
    transport_rate: transport.transportRate,
    transport_calculation: transport.calculation,
    working_cost: workingCost,
    transport_cost: transport.transportCost,
    total_cost: totalCost,
    requester_name: requesterName || null,
    created_by_user_id: requesterId || null,
    is_archived: false,
    archived_at: null,
  };
}

async function _eventsRequestUpdateRow(body = {}, req, existing = {}) {
  const next = await _eventsRequestWriteRow(body, req);
  // Preserve request ownership, reference code and the current workflow state.
  next.status = _eventsNormalizeStatus(existing?.status);
  next.requester_name = existing?.requester_name || next.requester_name || null;
  next.created_by_user_id = existing?.created_by_user_id || next.created_by_user_id || null;
  next.is_archived = _eventsBoolean(existing?.is_archived);
  next.archived_at = existing?.archived_at || null;
  return next;
}
// Events Admins can manage catalog records directly. Users with Edit access may
// create one component or edit one selected component after shared Admin-password authorization.
const EVENTS_COMPONENT_CREATE_UNLOCK_TTL_MS = 5 * 60 * 1000;
const EVENTS_COMPONENT_EDIT_UNLOCK_TTL_MS = 5 * 60 * 1000;
const EVENTS_GOVERNORATE_RATES_UNLOCK_TTL_MS = 5 * 60 * 1000;
// Event-request workflow actions are protected by a short, event-specific Admin verification.
const EVENTS_REQUEST_WORKFLOW_UNLOCK_TTL_MS = 5 * 60 * 1000;
// Request-level Edit and Cancel actions are also explicitly authorized by the
// shared Events Admin password, even for an Events Admin account.
const EVENTS_REQUEST_ACTION_UNLOCK_TTL_MS = 5 * 60 * 1000;

function _hasEventsComponentCreateAccess(req) {
  if (_hasEventComponentsAdminAccess(req)) return true;
  const until = Number(req?.session?.eventsComponentCreateAdminUnlockUntil || 0);
  return Number.isFinite(until) && until > Date.now();
}

function _hasEventsComponentEditAccess(req, componentId) {
  if (_hasEventComponentsAdminAccess(req)) return true;
  const expectedId = _eventsUuid(componentId);
  const grantedId = _eventsUuid(req?.session?.eventsComponentEditAdminUnlockComponentId);
  const until = Number(req?.session?.eventsComponentEditAdminUnlockUntil || 0);
  return !!expectedId && expectedId === grantedId && Number.isFinite(until) && until > Date.now();
}

function _hasEventsTransportSettingsAccess(req) {
  if (_hasEventRequestsAdminAccess(req)) return true;
  const until = Number(req?.session?.eventsTransportSettingsAdminUnlockUntil || 0);
  return Number.isFinite(until) && until > Date.now();
}

function _hasEventsGovernorateRatesAccess(req) {
  if (_hasEventRequestsAdminAccess(req)) return true;
  const until = Number(req?.session?.eventsGovernorateRatesAdminUnlockUntil || 0);
  return Number.isFinite(until) && until > Date.now();
}

/**
 * Resolve the only status transitions that can be carried out through the
 * Events request workflow buttons. The database remains normalized using
 * `completed`, while the UI calls that final state “Done”.
 */
function _eventsWorkflowTransition(targetStatus) {
  const to = _eventsNormalizeStatus(targetStatus);
  if (to === 'in_progress') return { action: 'approve', from: 'submitted', to };
  if (to === 'completed') return { action: 'deliver', from: 'in_progress', to };
  return null;
}

function _hasEventsRequestWorkflowAccess(req, eventId, targetStatus) {
  const expectedId = _eventsUuid(eventId);
  const transition = _eventsWorkflowTransition(targetStatus);
  const grantedId = _eventsUuid(req?.session?.eventsRequestWorkflowUnlockEventId);
  const grantedTarget = _eventsNormalizeStatus(req?.session?.eventsRequestWorkflowUnlockTargetStatus);
  const until = Number(req?.session?.eventsRequestWorkflowUnlockUntil || 0);

  return !!(
    expectedId
    && transition
    && expectedId === grantedId
    && transition.to === grantedTarget
    && Number.isFinite(until)
    && until > Date.now()
  );
}

function _eventsRequestAction(value) {
  const action = String(value || '').trim().toLowerCase();
  return action === 'edit' || action === 'cancel' ? action : '';
}

function _hasEventsRequestActionAccess(req, eventId, action) {
  const expectedId = _eventsUuid(eventId);
  const expectedAction = _eventsRequestAction(action);
  const grantedId = _eventsUuid(req?.session?.eventsRequestActionUnlockEventId);
  const grantedAction = _eventsRequestAction(req?.session?.eventsRequestActionUnlockAction);
  const until = Number(req?.session?.eventsRequestActionUnlockUntil || 0);
  return !!(expectedId && expectedAction && expectedId === grantedId && expectedAction === grantedAction && Number.isFinite(until) && until > Date.now());
}

async function _clearEventsRequestWorkflowUnlock(req) {
  if (!req?.session) return;
  delete req.session.eventsRequestWorkflowUnlockUntil;
  delete req.session.eventsRequestWorkflowUnlockEventId;
  delete req.session.eventsRequestWorkflowUnlockTargetStatus;
  try { await _saveSessionNow(req); } catch {}
}

async function _clearEventsRequestActionUnlock(req) {
  if (!req?.session) return;
  delete req.session.eventsRequestActionUnlockUntil;
  delete req.session.eventsRequestActionUnlockEventId;
  delete req.session.eventsRequestActionUnlockAction;
  try { await _saveSessionNow(req); } catch {}
}

async function _clearEventsComponentCreateUnlock(req) {
  if (!req?.session) return;
  delete req.session.eventsComponentCreateAdminUnlockUntil;
  try { await _saveSessionNow(req); } catch {}
}

async function _clearEventsComponentEditUnlock(req) {
  if (!req?.session) return;
  delete req.session.eventsComponentEditAdminUnlockUntil;
  delete req.session.eventsComponentEditAdminUnlockComponentId;
  try { await _saveSessionNow(req); } catch {}
}

async function _clearEventsTransportSettingsUnlock(req) {
  if (!req?.session) return;
  delete req.session.eventsTransportSettingsAdminUnlockUntil;
  try { await _saveSessionNow(req); } catch {}
}

async function _clearEventsGovernorateRatesUnlock(req) {
  if (!req?.session) return;
  delete req.session.eventsGovernorateRatesAdminUnlockUntil;
  try { await _saveSessionNow(req); } catch {}
}

function _eventsModuleMissingError(error) {
  const raw = String(error?.message || '');
  if (/SUPABASE_STORAGE_OR_BLOB_TOKEN_MISSING|SUPABASE_STORAGE_PUBLIC_URL_MISSING/i.test(raw)) {
    return 'Photo upload is not configured. Add SUPABASE_STORAGE_BUCKET in Vercel, or add BLOB_READ_WRITE_TOKEN as a fallback.';
  }
  return /event_components|event_type_catalog|event_component_category_catalog|event_governorate_transport_rates|events|relation .* does not exist|Could not find the table|PGRST205|42P01|schema cache/i.test(raw)
    ? 'Events tables are not installed. Run the latest Events component categories SQL migration in Supabase first.'
    : raw || 'Events request failed.';
}

