app.post('/api/events/admin/verify', requireAuth, requirePage(['Event Requests', 'Event Components']), async (req, res) => {
  res.set('Cache-Control', 'no-store');
  try {
    const password = String(req.body?.password || req.body?.adminPassword || '').trim();
    const requestedIntent = _eventsText(req.body?.intent, 32).toLowerCase();
    const intent = ['edit', 'governorate_rates', 'request_workflow', 'request_action'].includes(requestedIntent) ? requestedIntent : 'create';
    const componentId = _eventsUuid(req.body?.componentId || req.body?.component_id);
    const eventId = _eventsUuid(req.body?.eventId || req.body?.event_id);
    const targetStatus = _eventsNormalizeStatus(req.body?.targetStatus || req.body?.target_status);
    const requestAction = _eventsRequestAction(req.body?.action);

    // Request workflow and request actions deliberately require the shared
    // Events Admin password even when the current account is an Events Admin.
    const intentPage = (intent === 'edit' || intent === 'create') ? 'Event Components' : 'Event Requests';
    const verified = (intent === 'request_workflow' || intent === 'request_action')
      ? (!!password && password !== PAGE_ADMIN_BYPASS_TOKEN && await verifyAdminPassword(password))
      : await _verifyPageAdminPassword(req, password, intentPage);

    if (!verified) return res.status(401).json({ ok: false, error: 'Invalid Admin password.' });

    if (intent === 'request_workflow') {
      const transition = _eventsWorkflowTransition(targetStatus);
      if (!eventId || !transition) {
        return res.status(400).json({ ok: false, error: 'Choose a valid event request workflow action.' });
      }
      req.session.eventsRequestWorkflowUnlockUntil = Date.now() + EVENTS_REQUEST_WORKFLOW_UNLOCK_TTL_MS;
      req.session.eventsRequestWorkflowUnlockEventId = eventId;
      req.session.eventsRequestWorkflowUnlockTargetStatus = transition.to;
      await _saveSessionNow(req);
      return res.json({
        ok: true,
        intent,
        eventId,
        targetStatus: transition.to,
        expiresInSeconds: Math.floor(EVENTS_REQUEST_WORKFLOW_UNLOCK_TTL_MS / 1000),
      });
    }

    if (intent === 'request_action') {
      if (!eventId || !requestAction) {
        return res.status(400).json({ ok: false, error: 'Choose a valid event request action.' });
      }
      req.session.eventsRequestActionUnlockUntil = Date.now() + EVENTS_REQUEST_ACTION_UNLOCK_TTL_MS;
      req.session.eventsRequestActionUnlockEventId = eventId;
      req.session.eventsRequestActionUnlockAction = requestAction;
      await _saveSessionNow(req);
      return res.json({
        ok: true,
        intent,
        eventId,
        action: requestAction,
        expiresInSeconds: Math.floor(EVENTS_REQUEST_ACTION_UNLOCK_TTL_MS / 1000),
      });
    }

    if (intent === 'governorate_rates') {
      req.session.eventsGovernorateRatesAdminUnlockUntil = Date.now() + EVENTS_GOVERNORATE_RATES_UNLOCK_TTL_MS;
      await _saveSessionNow(req);
      return res.json({ ok: true, intent, expiresInSeconds: Math.floor(EVENTS_GOVERNORATE_RATES_UNLOCK_TTL_MS / 1000) });
    }

    if (intent === 'edit') {
      if (!componentId) return res.status(400).json({ ok: false, error: 'Select a valid event component to edit.' });
      req.session.eventsComponentEditAdminUnlockUntil = Date.now() + EVENTS_COMPONENT_EDIT_UNLOCK_TTL_MS;
      req.session.eventsComponentEditAdminUnlockComponentId = componentId;
      await _saveSessionNow(req);
      return res.json({ ok: true, intent, expiresInSeconds: Math.floor(EVENTS_COMPONENT_EDIT_UNLOCK_TTL_MS / 1000) });
    }

    req.session.eventsComponentCreateAdminUnlockUntil = Date.now() + EVENTS_COMPONENT_CREATE_UNLOCK_TTL_MS;
    await _saveSessionNow(req);
    return res.json({ ok: true, intent, expiresInSeconds: Math.floor(EVENTS_COMPONENT_CREATE_UNLOCK_TTL_MS / 1000) });
  } catch (error) {
    console.error('POST /api/events/admin/verify error:', error?.details || error);
    return res.status(500).json({ ok: false, error: 'Failed to verify Admin password.' });
  }
});

app.post('/api/events/components', requireAuth, requirePage('Event Components'), async (req, res) => {
  res.set('Cache-Control', 'no-store');
  try {
    if (!_hasEventsComponentCreateAccess(req)) return res.status(403).json({ ok: false, error: 'Admin authorization is required to add an event component.' });
    const name = _eventsText(req.body?.name, 180);
    if (!name) return res.status(400).json({ ok: false, error: 'Component name is required.' });
    const photoUrl = await _eventsComponentPhotoUrl(req.body || {});
    const linkUrl = _eventsHttpUrl(req.body?.linkUrl || req.body?.link_url, 1000);
    if (String(req.body?.linkUrl || req.body?.link_url || '').trim() && !linkUrl) {
      return res.status(400).json({ ok: false, error: 'Link must start with http:// or https://.' });
    }
    const category = await _eventsResolveComponentCategory(req.body || {});
    const inserted = await supabaseDb.insert(_sbEventComponentsTable(), {
      name,
      category: category.code,
      description: _eventsLongText(req.body?.description, 2000) || null,
      default_quantity: _eventsNumber(req.body?.defaultQuantity || req.body?.default_quantity, { min: 0, max: 100000, fallback: 1 }),
      ownership_type: _eventsNormalizeComponentOwnership(req.body?.ownershipType || req.body?.ownership_type),
      operating_cost: _eventsCost(req.body?.operatingCost ?? req.body?.operating_cost, 0),
      rental_cost: _eventsNormalizeComponentOwnership(req.body?.ownershipType || req.body?.ownership_type) === 'external_rental' ? _eventsCost(req.body?.rentalCost ?? req.body?.rental_cost, 0) : 0,
      photo_url: photoUrl,
      link_url: linkUrl || null,
      is_active: req.body?.isActive !== false,
    });
    if (!_hasEventComponentsAdminAccess(req)) await _clearEventsComponentCreateUnlock(req);
    return res.status(201).json({ ok: true, component: _eventsSerializeComponent(inserted || {}) });
  } catch (error) {
    console.error('POST /api/events/components error:', error?.details || error);
    return res.status(error?.status || 500).json({ ok: false, error: _eventsModuleMissingError(error) });
  }
});

