// Return an Operations Order to In progress — requires admin password.
// Used by the 3-dot Edit action in Operations Orders. This does not open
// the shopping cart; it only moves the order back to the Not Started bucket.
app.post(
  "/api/orders/operations/edit-to-progress",
  requireAuth,
  requirePage("Operations Orders"),
  async (req, res) => {
    try {
      const { orderIds, adminPassword } = req.body || {};
      if (!Array.isArray(orderIds) || orderIds.length === 0) {
        return res.status(400).json({ error: "orderIds required" });
      }

      const pwd = String(adminPassword || "").trim();
      if (!pwd) return res.status(400).json({ error: "adminPassword required" });

      const ok = await _verifyPageAdminPassword(req, pwd, ["Operations Orders", "Requested Orders"]);
      if (!ok) return res.status(401).json({ error: "Invalid admin password" });

      const ids = orderIds
        .map((x) => String(x || "").trim())
        .filter(Boolean)
        .map((x) => (looksLikeNotionId(x) ? toHyphenatedUUID(x) : x));

      if (!ids.length) return res.status(400).json({ error: "orderIds required" });

      if (_sbOrdersEnabled() && ids.every((id) => /^\d+$/.test(String(id)))) {
        const result = await _sbResetOperationsOrdersToProgress(ids);
        if (req.session) {
          delete req.session.editingOrder;
          delete req.session.adminCreateOrderUnlockUntil;
          await _saveSessionNow(req).catch(() => {});
        }
        return res.json(result);
      }

      if (!ordersDatabaseId) {
        return res.status(500).json({ error: "Supabase orders table is not configured." });
      }

      const statusProp = await detectStatusPropName();
      const dbProps = await getOrdersDBProps();
      const dbPropMeta = dbProps?.[statusProp] || null;
      const sample = await notion.pages.retrieve({ page_id: ids[0] });
      const statusType = dbPropMeta?.type || sample?.properties?.[statusProp]?.type || "select";
      const opts = statusType === "status" ? dbPropMeta?.status?.options : dbPropMeta?.select?.options;
      const picked = (Array.isArray(opts) ? opts : []).find((o) => norm(o?.name) === norm("In progress"))?.name || "In progress";
      const value = statusType === "status" ? { status: { name: picked } } : { select: { name: picked } };

      await Promise.all(ids.map((id) => notion.pages.update({ page_id: id, properties: { [statusProp]: value } })));
      await cacheDel("cache:api:orders:requested:v7");
      return res.json({ success: true, status: picked, statusColor: "yellow", source: "notion" });
    } catch (e) {
      console.error("operations edit-to-progress error:", e?.details || e?.body || e);
      return res.status(e?.status || 500).json({ error: e?.message || "Failed to return order to In progress" });
    }
  },
);

// Verify admin password before opening the Operations Orders edit details modal.
app.post(
  "/api/orders/operations/verify-admin",
  requireAuth,
  requirePage("Operations Orders"),
  async (req, res) => {
    try {
      const { orderIds, adminPassword } = req.body || {};
      const ids = (Array.isArray(orderIds) ? orderIds : [])
        .map((x) => String(x || "").trim())
        .filter(Boolean)
        .map((x) => (looksLikeNotionId(x) ? toHyphenatedUUID(x) : x));
      if (!ids.length) return res.status(400).json({ error: "orderIds required" });

      const pwd = String(adminPassword || "").trim();
      if (!pwd) return res.status(400).json({ error: "adminPassword required" });
      const ok = await _verifyPageAdminPassword(req, pwd, ["Operations Orders", "Requested Orders"]);
      if (!ok) return res.status(401).json({ error: "Invalid admin password" });

      if (_sbOrdersEnabled() && ids.every((id) => /^\d+$/.test(String(id)))) {
        const rows = await _sbOrderRowsByIds(ids);
        if (!rows.length) return res.status(404).json({ error: "Orders not found" });
      }

      return res.json({ success: true });
    } catch (e) {
      console.error("operations verify admin error:", e?.details || e?.body || e);
      return res.status(e?.status || 500).json({ error: e?.message || "Failed to verify admin password" });
    }
  },
);

// Edit Operations Order details without moving the order back to the beginning.
// Body: { orderIds, adminPassword, receiptNumbers, quantities: { [orderRowId]: number }, orderReceiptDataUrls, orderReceiptFilenames }
app.post(
  "/api/orders/operations/details-edit",
  requireAuth,
  requirePage("Operations Orders"),
  async (req, res) => {
    try {
      const {
        orderIds,
        adminPassword,
        receiptNumber,
        receiptNumbers,
        quantities,
        orderReceiptReplace,
        orderReceiptKeepEntries,
        orderReceiptRemovedKeys,
        orderReceiptRemovedUrls,
        orderReceiptDataUrls,
        orderReceiptFilenames,
      } = req.body || {};

      const ids = (Array.isArray(orderIds) ? orderIds : [])
        .map((x) => String(x || "").trim())
        .filter(Boolean)
        .map((x) => (looksLikeNotionId(x) ? toHyphenatedUUID(x) : x));
      if (!ids.length) return res.status(400).json({ error: "orderIds required" });

      const pwd = String(adminPassword || "").trim();
      if (!pwd) return res.status(400).json({ error: "adminPassword required" });
      const ok = await _verifyPageAdminPassword(req, pwd, ["Operations Orders", "Requested Orders"]);
      if (!ok) return res.status(401).json({ error: "Invalid admin password" });

      if (!_sbOrdersEnabled() || !ids.every((id) => /^\d+$/.test(String(id)))) {
        return res.status(400).json({ error: "Operations edit details is available for Supabase orders only." });
      }

      const rowsBeforeUpdate = await _sbOrderRowsByIds(ids);
      if (!rowsBeforeUpdate.length) return res.status(404).json({ error: "Orders not found" });

      const receiptTextProvided =
        Object.prototype.hasOwnProperty.call(req.body || {}, "receiptNumbers") ||
        Object.prototype.hasOwnProperty.call(req.body || {}, "receiptNumber");
      const receiptText = _normalizeReceiptNumbersText(
        Array.isArray(receiptNumbers) && receiptNumbers.length ? receiptNumbers : receiptNumber,
      );

      const keepReceiptEntriesProvided = Object.prototype.hasOwnProperty.call(req.body || {}, "orderReceiptKeepEntries");
      const normalizeReceiptEditPhotoKey = (entry = {}) => {
        const url = String(
          entry?.url ||
          entry?.publicUrl ||
          entry?.public_url ||
          entry?.rawUrl ||
          entry?.raw ||
          entry?.path ||
          entry?.fullPath ||
          entry?.full_path ||
          "",
        ).trim().toLowerCase();
        const name = String(entry?.name || entry?.filename || entry?.fileName || "").trim().toLowerCase();
        return `${url}::${name}`;
      };
      const removedPhotoKeys = new Set(
        (Array.isArray(orderReceiptRemovedKeys) ? orderReceiptRemovedKeys : [])
          .map((key) => String(key || "").trim().toLowerCase())
          .filter(Boolean),
      );
      const removedPhotoUrls = new Set(
        (Array.isArray(orderReceiptRemovedUrls) ? orderReceiptRemovedUrls : [])
          .map((url) => String(url || "").trim().toLowerCase())
          .filter(Boolean),
      );
      const keepReceiptEntries = (Array.isArray(orderReceiptKeepEntries) ? orderReceiptKeepEntries : [])
        .map((entry, index) => {
          const name = String(entry?.name || entry?.filename || `Receipt photo ${index + 1}`).trim() || `Receipt photo ${index + 1}`;
          const url = String(entry?.url || entry?.publicUrl || entry?.public_url || entry?.rawUrl || entry?.raw || entry?.path || entry?.fullPath || "").trim();
          if (!url) return null;
          const normalized = { name, url };
          const key = normalizeReceiptEditPhotoKey({ ...entry, ...normalized });
          const normalizedUrl = String(url || "").trim().toLowerCase();
          if (key && removedPhotoKeys.has(key)) return null;
          if (normalizedUrl && removedPhotoUrls.has(normalizedUrl)) return null;
          return normalized;
        })
        .filter(Boolean);

      const photoDataUrls = (Array.isArray(orderReceiptDataUrls) ? orderReceiptDataUrls : [])
        .map((x) => String(x || "").trim())
        .filter(Boolean);
      const photoNames = (Array.isArray(orderReceiptFilenames) ? orderReceiptFilenames : [])
        .map((x) => String(x || "").trim())
        .filter(Boolean);
      const uploadedReceiptFiles = [];
      for (let index = 0; index < photoDataUrls.length; index += 1) {
        const dataUrl = photoDataUrls[index];
        const fallbackName = `operations-receipt-${index + 1}.jpg`;
        const rawName = String(photoNames[index] || fallbackName).trim() || fallbackName;
        const cleanName = rawName.replace(/[^a-zA-Z0-9._-]+/g, "_").slice(0, 120) || fallbackName;
        const extMatch = cleanName.match(/\.([a-zA-Z0-9]+)$/);
        const safeExt = extMatch?.[1] ? extMatch[1].toLowerCase() : "jpg";
        const objectName = `delivery-receipts/${Date.now()}-${index + 1}-${Math.random().toString(36).slice(2, 10)}.${safeExt}`;
        try {
          const publicUrl = await uploadToBlobFromBase64(dataUrl, objectName);
          uploadedReceiptFiles.push({ name: cleanName, url: publicUrl });
        } catch (uploadErr) {
          const uploadMessage =
            String(uploadErr?.message || "").trim() === "SUPABASE_STORAGE_OR_BLOB_TOKEN_MISSING"
              ? "Supabase Storage upload is not configured."
              : "Failed to upload receipt photo.";
          return res.status(500).json({ error: uploadMessage });
        }
      }

      const shouldReplaceReceiptPhotos =
        !!orderReceiptReplace ||
        keepReceiptEntriesProvided ||
        uploadedReceiptFiles.length > 0 ||
        removedPhotoKeys.size > 0 ||
        removedPhotoUrls.size > 0;

      const quantityMap = quantities && typeof quantities === "object" ? quantities : {};
      const beforeById = new Map((rowsBeforeUpdate || []).filter(Boolean).map((row) => [String(row?.id ?? ""), row]));
      const updatedRows = [];

      for (const id of ids) {
        const beforeRow = beforeById.get(String(id)) || null;
        if (!beforeRow) continue;
        const patch = {};

        if (receiptTextProvided) {
          patch.receipt_number = receiptText || null;
        }
        if (shouldReplaceReceiptPhotos) {
          const combinedReceiptFiles = [...keepReceiptEntries, ...uploadedReceiptFiles];
          const receiptPhotosValue = combinedReceiptFiles.length ? JSON.stringify(combinedReceiptFiles) : null;
          // Always replace the operation receipt photos with exactly the list saved from the edit modal.
          // Clearing these alias columns prevents old imported/legacy receipt photos from reappearing in the UI.
          patch.order_receipt = receiptPhotosValue;
          patch.delivery_receipt = receiptPhotosValue;
          patch.receipt_photos = receiptPhotosValue;
          patch.maintenance_receipt = receiptPhotosValue;
        }

        if (Object.prototype.hasOwnProperty.call(quantityMap, String(id))) {
          const rawQty = Number(quantityMap[String(id)]);
          if (!Number.isFinite(rawQty)) {
            return res.status(400).json({ error: "Quantity received must be a valid number." });
          }
          const serialized = _sbSerializeOrderRow(beforeRow);
          const base = Number(serialized?.quantity) || 0;
          let nextQty = roundOrderQty(rawQty);
          if (base < 0 && nextQty > 0) nextQty = -Math.abs(nextQty);
          const clampedQty = clampOrderQtyToBase(base, nextQty);
          patch.quantity_received_by_operations = clampedQty;
          patch.quantity_remaining = roundOrderQty(base - clampedQty);
        }

        if (!Object.keys(patch).length) {
          updatedRows.push(beforeRow);
          continue;
        }
        updatedRows.push(await _sbUpdateOrderRowSafe(id, patch));
      }

      const rowsNeedingStockSync = updatedRows.filter((row) => {
        const serialized = _sbSerializeOrderRow(row || {});
        return _sbOrderFinalStatusName(serialized?.status);
      });
      const stocktakingSyncResults = [];
      const stocktakingSyncErrors = [];
      if (rowsNeedingStockSync.length) {
        await _sbDeleteStocktakingRowsForOrderRows(rowsBeforeUpdate);
        for (const row of rowsNeedingStockSync) {
          const id = String(_sbOrderGet(row, ["id", "ID"]) ?? "").trim();
          try {
            const result = await _sbSyncArrivedOrderToStocktaking(row, { wasArrivedLike: true });
            stocktakingSyncResults.push({ orderId: id, ...result });
          } catch (syncErr) {
            stocktakingSyncErrors.push({ orderId: id, message: String(syncErr?.message || "Failed to sync Stocktaking row.") });
          }
        }
      }

      await _sbInvalidateOrdersCaches(req);
      try { await cacheDel("cache:api:orders:requested:v7"); } catch {}
      try { await cacheDel("cache:api:b2b:school-stock:supabase:v1"); } catch {}

      const freshRowsAfterUpdate = await _sbOrderRowsByIds(ids).catch(() => updatedRows);
      const responseRows = Array.isArray(freshRowsAfterUpdate) && freshRowsAfterUpdate.length ? freshRowsAfterUpdate : updatedRows;

      if (stocktakingSyncErrors.length) {
        return res.status(500).json({
          success: false,
          error: "Order details updated but failed to sync some Stocktaking rows.",
          items: responseRows.map((row) => _sbSerializeOrderRow(row)),
          stocktakingSyncErrors,
          source: "supabase",
        });
      }

      return res.json({
        success: true,
        items: responseRows.map((row) => _sbSerializeOrderRow(row)),
        stocktakingSyncedCount: stocktakingSyncResults.filter((item) => item && item.skipped === false).length,
        stocktakingSkippedCount: stocktakingSyncResults.filter((item) => item && item.skipped === true).length,
        source: "supabase",
      });
    } catch (e) {
      console.error("operations details edit error:", e?.details || e?.body || e);
      return res.status(e?.status || 500).json({ error: e?.message || "Failed to update order details" });
    }
  },
);

// ===== Stocktaking data (JSON) — requires Stocktaking =====

// ===== Helpers: Stocktaking / Products "ID code" extraction (Notion) =====
function _propInsensitive(props = {}, name = "") {
  const target = String(name || "").trim().toLowerCase();
  if (!target) return null;
  for (const [k, v] of Object.entries(props || {})) {
    if (String(k || "").trim().toLowerCase() === target) return v;
  }
  return null;
}

function _extractPropText(prop) {
  try {
    if (!prop) return null;
    if (prop.type === "unique_id" && prop.unique_id && typeof prop.unique_id.number === "number") {
      const prefix = prop.unique_id.prefix ? String(prop.unique_id.prefix).trim() : "";
      const n = prop.unique_id.number;
      return prefix ? `${prefix}-${n}` : String(n);
    }
    if (prop.type === "rich_text") {
      const t = (prop.rich_text || []).map((r) => r?.plain_text || "").join("").trim();
      return t || null;
    }
    if (prop.type === "title") {
      const t = (prop.title || []).map((r) => r?.plain_text || "").join("").trim();
      return t || null;
    }
    if (prop.type === "number" && (prop.number === 0 || typeof prop.number === "number")) {
      return String(prop.number);
    }
    if (prop.type === "select") return prop.select?.name || null;
    if (prop.type === "formula") {
      if (prop.formula?.type === "string") {
        const t = String(prop.formula.string || "").trim();
        return t || null;
      }
      if (prop.formula?.type === "number" && typeof prop.formula.number === "number") {
        return String(prop.formula.number);
      }
    }
  } catch {}
  return null;
}

function _extractPropNumber(prop) {
  try {
    if (!prop) return null;

    if (prop.type === "number" && typeof prop.number === "number") return prop.number;

    if (prop.type === "formula") {
      if (prop.formula?.type === "number" && typeof prop.formula.number === "number") {
        return prop.formula.number;
      }
      if (prop.formula?.type === "string") {
        const t = String(prop.formula.string || "").trim();
        if (!t) return null;
        const n = parseFloat(t.replace(/[^0-9.-]/g, ""));
        return Number.isFinite(n) ? n : null;
      }
    }

    if (prop.type === "rollup") {
      if (prop.rollup?.type === "number" && typeof prop.rollup.number === "number") {
        return prop.rollup.number;
      }
      if (prop.rollup?.type === "array") {
        const arr = prop.rollup.array || [];
        for (const x of arr) {
          if (x?.type === "number" && typeof x.number === "number") return x.number;
          if (x?.type === "formula" && x.formula?.type === "number" && typeof x.formula.number === "number") {
            return x.formula.number;
          }
          if (x?.type === "formula" && x.formula?.type === "string") {
            const n = parseFloat(String(x.formula.string || "").replace(/[^0-9.-]/g, ""));
            if (Number.isFinite(n)) return n;
          }
          if (x?.type === "rich_text") {
            const t = (x.rich_text || []).map((r) => r?.plain_text || "").join("").trim();
            const n = parseFloat(t.replace(/[^0-9.-]/g, ""));
            if (Number.isFinite(n)) return n;
          }
        }
      }
    }

    if (prop.type === "rich_text") {
      const t = (prop.rich_text || []).map((r) => r?.plain_text || "").join("").trim();
      const n = parseFloat(t.replace(/[^0-9.-]/g, ""));
      return Number.isFinite(n) ? n : null;
    }
  } catch {}
  return null;
}

function _extractIdCodeFromProps(props = {}) {
  // Prefer explicit property names
  const candidates = [
    "ID code",
    "ID Code",
    "Id code",
    "ID",
    "Code",
    "Component Code",
    "Item Code",
    "SKU",
  ];

  for (const name of candidates) {
    const p = _propInsensitive(props, name) || props?.[name];
    const t = _extractPropText(p);
    if (t) return t;
  }

  // Fallback: first unique_id on the page
  for (const v of Object.values(props || {})) {
    if (v?.type === "unique_id") {
      const t = _extractPropText(v);
      if (t) return t;
    }
  }

  return null;
}

// ===== Helpers: map Products(Name) -> Products(ID Code) =====
// The user wants the ID Code coming specifically from the Products database column "ID Code".
// We build a cached lookup table: normalized Product Name -> ID Code.
function _normNameKey(s) {
  return String(s || "")
    .replace(/\u00A0/g, " ")
    .trim()
    .toLowerCase()
    .replace(/[–—−]/g, "-")
    .replace(/\s*-\s*/g, " - ")
    .replace(/\s+/g, " ");
}

function _extractProductNameFromProps(props = {}) {
  // In Products DB, "Name" is typically a rich_text (Aa) column (as per user's screenshot).
  // We still support other possible names as fallback.
  const candidates = ["Name", "Component", "Product", "Item", "Material"];
  for (const name of candidates) {
    const p = _propInsensitive(props, name) || props?.[name];
    const t = _extractPropText(p);
    if (t) return t;
  }
  return null;
}

const _PRODUCTS_IDCODE_CACHE_TTL_MS = 10 * 60 * 1000; // 10 minutes
let _productsNameToIdCodeCache = {
  ts: 0,
  db: null,
  map: new Map(),
};

const _PRODUCTS_PRICE_CACHE_TTL_MS = 10 * 60 * 1000; // 10 minutes
let _productsNameToUnityPriceCache = {
  ts: 0,
  db: null,
  map: new Map(),
};

async function _getProductsNameToIdCodeMap() {
  try {
    if (_sbProductsEnabled()) {
      const now = Date.now();
      const db = `supabase:${_sbProductsTable()}`;
      if (
        _productsNameToIdCodeCache.map &&
        _productsNameToIdCodeCache.map.size > 0 &&
        _productsNameToIdCodeCache.db === db &&
        now - _productsNameToIdCodeCache.ts < _PRODUCTS_IDCODE_CACHE_TTL_MS
      ) {
        return _productsNameToIdCodeCache.map;
      }
      const map = new Map();
      const list = await _sbProductsList();
      for (const product of list) {
        if (!product?.name || !product?.displayId) continue;
        const key = _normNameKey(product.name);
        if (!map.has(key) || !map.get(key)) map.set(key, String(product.displayId));
      }
      _productsNameToIdCodeCache = { ts: now, db, map };
      return map;
    }

    if (!componentsDatabaseId) return new Map();

    const now = Date.now();
    if (
      _productsNameToIdCodeCache.map &&
      _productsNameToIdCodeCache.map.size > 0 &&
      _productsNameToIdCodeCache.db === componentsDatabaseId &&
      now - _productsNameToIdCodeCache.ts < _PRODUCTS_IDCODE_CACHE_TTL_MS
    ) {
      return _productsNameToIdCodeCache.map;
    }

    const map = new Map();
    let hasMore = true;
    let startCursor = undefined;

    while (hasMore) {
      const resp = await notion.databases.query({
        database_id: componentsDatabaseId,
        start_cursor: startCursor,
        page_size: 100,
      });

      for (const page of resp.results || []) {
        const props = page.properties || {};
        const productName = _extractProductNameFromProps(props);
        if (!productName) continue;

        // Prefer the explicit Products column "ID Code" (often it is the Title property)
        const idProp =
          _propInsensitive(props, "ID Code") ||
          _propInsensitive(props, "ID code") ||
          props?.["ID Code"] ||
          props?.["ID code"];

        let idCode = _extractPropText(idProp);

        // Fallback to other variants only if "ID Code" is missing
        if (!idCode) idCode = _extractIdCodeFromProps(props);

        if (!idCode) continue;

        const key = _normNameKey(productName);
        // Keep the first non-empty
        if (!map.has(key) || !map.get(key)) map.set(key, idCode);
      }

      hasMore = resp.has_more;
      startCursor = resp.next_cursor;
    }

    _productsNameToIdCodeCache = { ts: now, db: componentsDatabaseId, map };
    return map;
  } catch (e) {
    console.error("Failed to build Products Name->ID Code map:", e.body || e);
    return new Map();
  }
}

// ===== Helpers: map Products(Name) -> Products(Unity Price) =====
// Used for Stocktaking Excel export only.
async function _getProductsNameToUnityPriceMap() {
  try {
    if (_sbProductsEnabled()) {
      const now = Date.now();
      const db = `supabase:${_sbProductsTable()}`;
      if (
        _productsNameToUnityPriceCache.map &&
        _productsNameToUnityPriceCache.map.size > 0 &&
        _productsNameToUnityPriceCache.db === db &&
        now - _productsNameToUnityPriceCache.ts < _PRODUCTS_PRICE_CACHE_TTL_MS
      ) {
        return _productsNameToUnityPriceCache.map;
      }
      const map = new Map();
      const list = await _sbProductsList();
      for (const product of list) {
        if (!product?.name) continue;
        const price = Number(product.unitPrice);
        if (!Number.isFinite(price)) continue;
        const key = _normNameKey(product.name);
        if (!map.has(key) || map.get(key) === null || typeof map.get(key) === "undefined") map.set(key, price);
      }
      _productsNameToUnityPriceCache = { ts: now, db, map };
      return map;
    }

    if (!componentsDatabaseId) return new Map();

    const now = Date.now();
    if (
      _productsNameToUnityPriceCache.map &&
      _productsNameToUnityPriceCache.map.size > 0 &&
      _productsNameToUnityPriceCache.db === componentsDatabaseId &&
      now - _productsNameToUnityPriceCache.ts < _PRODUCTS_PRICE_CACHE_TTL_MS
    ) {
      return _productsNameToUnityPriceCache.map;
    }

    const map = new Map();
    let hasMore = true;
    let startCursor = undefined;

    while (hasMore) {
      const resp = await notion.databases.query({
        database_id: componentsDatabaseId,
        start_cursor: startCursor,
        page_size: 100,
      });

      for (const page of resp.results || []) {
        const props = page.properties || {};
        const productName = _extractProductNameFromProps(props);
        if (!productName) continue;

        const priceProp =
          _propInsensitive(props, "Unity Price") ||
          _propInsensitive(props, "Unit price") ||
          _propInsensitive(props, "Unit Price") ||
          _propInsensitive(props, "Price") ||
          props?.["Unity Price"] ||
          props?.["Unit price"] ||
          props?.["Unit Price"] ||
          props?.Price;

        const unityPrice = _extractPropNumber(priceProp);
        if (unityPrice === null || typeof unityPrice === "undefined") continue;

        const key = _normNameKey(productName);
        if (!map.has(key) || map.get(key) === null || typeof map.get(key) === "undefined") {
          map.set(key, unityPrice);
        }
      }

      hasMore = resp.has_more;
      startCursor = resp.next_cursor;
    }

    _productsNameToUnityPriceCache = { ts: now, db: componentsDatabaseId, map };
    return map;
  } catch (e) {
    console.error("_getProductsNameToUnityPriceMap error:", e.body || e);
    return new Map();
  }
}


// -----------------------------------------------------------------------------
// Supabase Stocktaking adapter
// -----------------------------------------------------------------------------
function _sbStocktakingEnabled() {
  return !!(supabaseDb && supabaseDb.isConfigured && supabaseDb.isConfigured());
}

function _sbStocktakingTable() {
  const cfg = supabaseDb.getConfig ? supabaseDb.getConfig() : {};
  return (cfg.stocktakingTable || process.env.SUPABASE_STOCKTAKING_TABLE || "stocktaking").trim() || "stocktaking";
}

function _sbStocktakingNum(value) {
  if (value === null || typeof value === "undefined") return 0;
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  if (typeof value === "boolean") return value ? 1 : 0;
  const raw = String(value || "").trim();
  if (!raw || /^null$/i.test(raw)) return 0;
  const n = Number(raw.replace(/[^0-9.-]/g, ""));
  return Number.isFinite(n) ? n : 0;
}

function _sbStocktakingText(value) {
  const t = _sbString(value);
  return t && !/^null$/i.test(t) ? t : "";
}

function _stockMovementTagColor(name = "", fallback = "default") {
  const canon = _sbCanon(name);
  if (canon === "requestproducts" || canon === "requestproduct") return "green";
  if (canon === "withdrawproducts" || canon === "withdrawproduct" || canon === "withdrawalproducts" || canon === "withdrawalproduct") return "red";
  return fallback || "default";
}

function _stockMovementTagHex(name = "", fallback = "default") {
  const color = _stockMovementTagColor(name, fallback);
  switch (color) {
    case "gray": return { bg: "#F3F4F6", text: "#374151", border: "#E5E7EB" };
    case "brown": return { bg: "#EFEBE9", text: "#4E342E", border: "#D7CCC8" };
    case "orange": return { bg: "#FFF7ED", text: "#9A3412", border: "#FED7AA" };
    case "yellow": return { bg: "#FEFCE8", text: "#854D0E", border: "#FDE68A" };
    case "green": return { bg: "#ECFDF5", text: "#065F46", border: "#A7F3D0" };
    case "blue": return { bg: "#EFF6FF", text: "#1E40AF", border: "#BFDBFE" };
    case "purple": return { bg: "#F5F3FF", text: "#5B21B6", border: "#DDD6FE" };
    case "pink": return { bg: "#FDF2F8", text: "#9D174D", border: "#FBCFE8" };
    case "red": return { bg: "#FEF2F2", text: "#991B1B", border: "#FECACA" };
    default: return { bg: "#F3F4F6", text: "#111827", border: "#E5E7EB" };
  }
}

function _sbStocktakingColumnKey(label = "") {
  return String(label || "")
    .replace(/\u00A0/g, " ")
    .trim()
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/%/g, " percent ")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .replace(/_+/g, "_");
}


function _sbFindStocktakingKey(keysOrRows = [], aliases = []) {
  const keys = Array.isArray(keysOrRows)
    ? (keysOrRows.length && typeof keysOrRows[0] === "object" ? _sbAllColumnKeys(keysOrRows) : keysOrRows)
    : Object.keys(keysOrRows || {});
  return _sbFindKey(keys, aliases);
}

function _sbDetectStocktakingQuantityColumnFromKeys(keys = [], schoolName = "") {
  const keyList = Array.isArray(keys) ? keys : [];
  if (!keyList.length) return "";
  const base = _sbStocktakingColumnKey(schoolName);
  const aliases = [];
  if (schoolName) aliases.push(schoolName);
  if (base) {
    aliases.push(base, `${base}_done`, `${base}_2nd_term`);
    if (base.endsWith("_done")) aliases.push(base.replace(/_done$/, ""));
  }
  aliases.push("total_quantity", "all_schools_stock", "all_done", "all_2nd_term", "quantity", "stock");
  const direct = _sbFindKey(keyList, aliases);
  if (direct) return direct;

  if (base) {
    const fuzzy = keyList.find((key) => {
      const k = _sbStocktakingColumnKey(key);
      return k === base || k === `${base}_done` || k === `${base}_2nd_term` || (k.includes(base) && /(done|stock|quantity|2nd_term)/i.test(k));
    });
    if (fuzzy) return fuzzy;
  }
  return "";
}

async function _sbResolveOrderOwnerTeamRow(orderRow = {}) {
  const ownerId = _sbOrderOwnerId(orderRow);
  if (ownerId) {
    const byId = await _sbFindTeamMemberById(ownerId).catch(() => null);
    if (byId) return byId;
  }

  const ownerName =
    _sbOrderOwnerName(orderRow) ||
    _sbOrderText(_sbOrderGet(orderRow, ["team_member_name", "Teams Members", "teams_members", "created_by_name", "created_by", "Created By", "Supervisor", "supervisor"]));
  if (ownerName) {
    const byName = await _sbFindTeamMemberByName(ownerName).catch(() => null);
    if (byName) return byName;
  }

  return null;
}

function _sbStocktakingMissingColumnName(error) {
  const text = String(
    error?.message ||
    error?.details?.message ||
    error?.details?.details ||
    error?.hint ||
    error?.details ||
    "",
  );
  return (
    (text.match(/Could not find the ['\"]([^'\"]+)['\"] column/i) || [])[1] ||
    (text.match(/['\"]([^'\"]+)['\"] column of ['\"][^'\"]+['\"]/i) || [])[1] ||
    (text.match(/column ['\"]([^'\"]+)['\"]/i) || [])[1] ||
    ""
  );
}

async function _sbInsertStocktakingRowSafe(row = {}, requiredColumns = []) {
  let payload = _sbCleanInsertRow(row);
  const required = new Set((Array.isArray(requiredColumns) ? requiredColumns : []).filter(Boolean));
  const removed = [];

  for (let attempt = 0; attempt < 12; attempt += 1) {
    try {
      return await supabaseDb.insert(_sbStocktakingTable(), payload);
    } catch (error) {
      const missingColumn = _sbStocktakingMissingColumnName(error);
      if (!missingColumn || !Object.prototype.hasOwnProperty.call(payload, missingColumn)) throw error;
      if (required.has(missingColumn)) {
        const err = new Error(`Missing required Stocktaking column: ${missingColumn}.`);
        err.status = 400;
        err.cause = error;
        throw err;
      }
      delete payload[missingColumn];
      removed.push(missingColumn);
    }
  }

  const err = new Error(`Failed to insert Stocktaking row after removing unsupported column(s): ${removed.join(", ")}`);
  err.status = 500;
  throw err;
}

function _sbStocktakingRowsMatchOrderPayload(row = {}, payload = {}) {
  const qtyColumn = String(payload?.quantityColumn || "").trim();
  if (!qtyColumn || !Object.prototype.hasOwnProperty.call(row || {}, qtyColumn)) return false;

  const rowQty = Number(_sbStocktakingNum(row?.[qtyColumn]));
  const wantedQty = Number(payload?.quantity || 0);
  if (Math.abs(roundOrderQty(rowQty - wantedQty)) > 1e-9) return false;

  const rowProduct = _sbStocktakingText(_sbGet(row, ["product_name", "Product Name", "product", "Product", "name", "Name", "component", "Component"]));
  if (payload?.productName && rowProduct && normKey(rowProduct) !== normKey(payload.productName)) return false;

  const rowTag = _sbStocktakingText(_sbGet(row, ["tag", "Tag", "tags", "Tags", "order_type", "Order Type", "type", "Type"]));
  if (payload?.orderType && rowTag && _normKeyOrderType(rowTag) !== _normKeyOrderType(payload.orderType)) return false;

  const rowReceipt = _normalizeMultilineText(
    _sbStocktakingText(_sbGet(row, ["receipt_number", "Receipt Number", "store_receipt_number", "Store Receipt Number", "receipt", "Receipt", "order_receipt", "Order Receipt"])),
  );
  const wantedReceipt = _normalizeMultilineText(payload?.receiptText || "");
  if (rowReceipt || wantedReceipt) return rowReceipt === wantedReceipt;

  return true;
}

async function _sbBuildArrivedOrderStocktakingPayload(orderRow = {}) {
  const item = _sbSerializeOrderRow(orderRow);
  const orderType = _canonicalOrderTypeLabel(item?.orderType || "");
  const orderTypeKey = _normKeyOrderType(orderType);
  if (
    orderTypeKey !== _normKeyOrderType("Request Products") &&
    orderTypeKey !== _normKeyOrderType("Withdraw Products")
  ) {
    return null;
  }

  const ownerRow = await _sbResolveOrderOwnerTeamRow(orderRow);
  const schoolName = String(_sbString(_sbValueForLabel(ownerRow || {}, "School")) || "").trim();
  if (!schoolName) {
    throw new Error("Could not determine the requester school/stocktaking column.");
  }

  const rows = await _sbStocktakingRows();
  const keys = _sbAllColumnKeys(rows || []);
  const quantityColumn =
    _sbDetectStocktakingQuantityColumnFromKeys(keys, schoolName) ||
    _sbStocktakingColumnKey(schoolName);

  if (!quantityColumn) {
    throw new Error(`Could not determine the Stocktaking quantity column for ${schoolName}.`);
  }

  const qtyCandidates = [item.quantityReceived, item.quantityProgress, item.quantityRequested, item.quantity];
  let quantity = 0;
  for (const candidate of qtyCandidates) {
    const n = Number(candidate);
    if (Number.isFinite(n) && hasNonZeroOrderQty(n)) {
      quantity = roundOrderQty(n);
      break;
    }
  }
  if (!hasNonZeroOrderQty(quantity)) {
    throw new Error("No delivered quantity was found for Stocktaking sync.");
  }

  if (orderTypeKey === _normKeyOrderType("Withdraw Products")) {
    quantity = -Math.abs(quantity);
  } else if (orderTypeKey === _normKeyOrderType("Request Products")) {
    quantity = Math.abs(quantity);
  }

  const productName =
    String(item.productName || "").trim() ||
    _sbOrderText(_sbOrderGet(orderRow, ["product_name", "Product Name", "product", "Product"])) ||
    "Untitled Product";

  const orderReceiptEntries = _sbParseScreenshotEntries(_sbOrderGet(orderRow, ["order_receipt", "Order Receipt", "delivery_receipt", "Delivery Receipt", "receipt_photos", "Receipt Photos"]));
  const receiptText = _normalizeMultilineText(
    item.receiptNumber ||
    _sbOrderText(_sbOrderGet(orderRow, ["receipt_number", "Receipt Number", "Store Receipt Number"])) ||
    orderReceiptEntries.map((entry) => entry.name || entry.url).filter(Boolean).join("\n") ||
    "",
  );

  return {
    rows,
    keys,
    quantityColumn,
    quantity,
    orderType,
    productName,
    productUrl: item.productUrl || _sbExtractUrl(_sbOrderGet(orderRow, ["product_url", "Product URL", "url", "URL"])) || "",
    unitPrice: Number.isFinite(Number(item.unitPrice)) ? Number(item.unitPrice) : null,
    receiptText,
    orderId: String(_sbOrderGet(orderRow, ["id", "ID"]) ?? "").trim(),
    orderNumber: item.orderId || null,
    ownerName: item.createdByName || _sbOrderOwnerName(orderRow) || "",
    ownerSchool: schoolName,
  };
}

async function _sbSyncArrivedOrderToStocktaking(orderRow = {}, options = {}) {
  const payload = await _sbBuildArrivedOrderStocktakingPayload(orderRow);
  if (!payload) return { skipped: true, reason: "unsupported-order-type" };

  const keys = payload.keys || [];
  const sourceOrderColumn = _sbFindStocktakingKey(keys, ["source_order_id", "Source Order ID", "source_order", "Source Order", "order_row_id", "Order Row ID"]);
  const sourceOrderNumberColumn = _sbFindStocktakingKey(keys, ["order_id", "Order ID", "order_number", "Order Number"]);

  const existingRows = Array.isArray(payload.rows) ? payload.rows : [];
  if (sourceOrderColumn && payload.orderId) {
    const existingBySource = existingRows.find((row) => String(row?.[sourceOrderColumn] ?? "").trim() === payload.orderId);
    if (existingBySource) return { skipped: true, reason: "already-synced", existingId: existingBySource?.id || null };
  }
  if (existingRows.some((row) => _sbStocktakingRowsMatchOrderPayload(row, payload))) {
    return { skipped: true, reason: "already-synced" };
  }

  const row = {};
  const setFirstExisting = (aliases, value, fallbackKey = "") => {
    if (value === null || typeof value === "undefined") return "";
    const key = _sbFindStocktakingKey(keys, aliases) || (!keys.length ? fallbackKey : "");
    if (!key) return "";
    row[key] = value;
    return key;
  };

  const nameKey = setFirstExisting(["name", "Name", "component", "Component"], payload.productName, "name");
  const productKey = setFirstExisting(["product_name", "Product Name", "product", "Product", "products", "Products"], payload.productName, nameKey ? "" : "product_name");
  if (!nameKey && !productKey && !keys.length) row.name = payload.productName;

  setFirstExisting(["product_url", "Product URL", "url", "URL", "item_url", "Item URL"], payload.productUrl || null, "product_url");
  setFirstExisting(["unity_price", "unit_price", "Unity Price", "Unit Price", "one_piece_price"], payload.unitPrice, "unit_price");
  setFirstExisting(["tag", "Tag", "tags", "Tags", "order_type", "Order Type", "type", "Type"], payload.orderType, "tag");
  setFirstExisting(["receipt_number", "Receipt Number", "store_receipt_number", "Store Receipt Number", "receipt", "Receipt", "order_receipt", "Order Receipt"], payload.receiptText || null, "receipt_number");
  if (sourceOrderColumn) row[sourceOrderColumn] = payload.orderId;
  else if (!keys.length && payload.orderId) row.source_order_id = payload.orderId;
  if (sourceOrderNumberColumn && payload.orderNumber) row[sourceOrderNumberColumn] = payload.orderNumber;
  setFirstExisting(["team_member_name", "Team Member", "requester", "Requester", "created_by", "Created By"], payload.ownerName || null, "team_member_name");
  setFirstExisting(["school", "School", "stocktaking_column", "Stocktaking Column"], payload.ownerSchool || null, "school");
  setFirstExisting(["created_at", "Created at", "created_time", "Created time", "notion_created_time"], new Date().toISOString(), "");

  row[payload.quantityColumn] = payload.quantity;

  const created = await _sbInsertStocktakingRowSafe(row, [payload.quantityColumn]);
  return { skipped: false, createdId: created?.id || null, quantityColumn: payload.quantityColumn, quantity: payload.quantity };
}

function _sbDetectStocktakingQuantityColumn(row = {}, schoolName = "") {
  const keys = Object.keys(row || {});
  if (!keys.length) return "";
  const exact = (wanted) => keys.find((key) => _sbCanon(key) === _sbCanon(wanted));
  const base = _sbStocktakingColumnKey(schoolName);
  const candidates = [];
  if (base) candidates.push(base);
  if (base && !base.endsWith("_done")) candidates.push(`${base}_done`);
  if (base && base.endsWith("_done")) candidates.push(base.replace(/_done$/, ""));
  if (base && !base.endsWith("_2nd_term")) candidates.push(`${base}_2nd_term`);
  candidates.push(
    "total_quantity",
    "all_schools_stock",
    "all_done",
    "all_2nd_term",
    "quantity",
    "stock",
  );
  for (const c of candidates) {
    const hit = exact(c);
    if (hit) return hit;
  }
  return "";
}

async function _sbStocktakingCurrentSchoolName(req) {
  let row = null;
  if (req?.session?.userSupabaseId) row = await _sbFindTeamMemberById(req.session.userSupabaseId);
  if (!row && req?.session?.username) row = await _sbFindTeamMemberByName(req.session.username);
  const schoolName = _sbStocktakingText(_sbValueForLabel(row || {}, "School"));
  return { row, schoolName };
}

async function _sbStocktakingRows() {
  const rows = await supabaseDb.selectAll(_sbStocktakingTable(), {
    limit: 5000,
    order: "name.asc,id.asc",
  });
  return Array.isArray(rows) ? rows : [];
}

function _sbSerializeStocktakingRow(row = {}, schoolNameOrColumn = "") {
  const quantityColumn = Object.prototype.hasOwnProperty.call(row || {}, schoolNameOrColumn)
    ? schoolNameOrColumn
    : _sbDetectStocktakingQuantityColumn(row, schoolNameOrColumn);
  const name = _sbStocktakingText(_sbGet(row, ["name", "Name", "component", "Component", "product_name", "Product Name"])) || "Untitled";
  const productName = _sbStocktakingText(_sbGet(row, ["product_name", "Product Name", "product", "Product"])) || name;
  const url =
    _sbExtractUrl(_sbGet(row, ["url", "URL"])) ||
    _sbExtractUrl(_sbGet(row, ["product_url", "Product URL"])) ||
    _sbExtractUrl(_sbGet(row, ["item_url", "Item URL"])) ||
    null;
  const tagName = _sbStocktakingText(_sbGet(row, ["tag", "Tag", "tags", "Tags"])) || "Untagged";
  return {
    id: String(_sbGet(row, ["id", "ID", "notion_id", "Notion ID"]) ?? ""),
    name,
    productName,
    url,
    quantity: _sbStocktakingNum(quantityColumn ? row?.[quantityColumn] : 0),
    oneKitQuantity: _sbStocktakingNum(_sbGet(row, ["one_kit_quantity", "One Kit Quantity", "one kit quantity"])),
    idCode: _sbStocktakingText(_sbGet(row, ["id_code", "ID Code", "id code", "code", "Code"])) || null,
    receiptNumber: _normalizeMultilineText(
      _sbStocktakingText(_sbGet(row, ["receipt_number", "Receipt Number", "store_receipt_number", "Store Receipt Number", "receipt", "Receipt", "order_receipt", "Order Receipt"])) || "",
    ),
    unitPrice: _sbStocktakingNum(_sbGet(row, ["unity_price", "unit_price", "Unity Price", "Unit Price", "one_piece_price"])),
    userName: _sbStocktakingText(_sbGet(row, ["user_name", "username", "User Name", "Username", "created_by", "Created By", "requested_by", "Requested By", "owner_name", "Owner Name", "employee", "Employee"])) || "Unknown user",
    tag: { name: tagName, color: _stockMovementTagColor(tagName, "default") },
    quantityColumn: quantityColumn || null,
    source: "supabase",
  };
}

async function _sbStocktakingForRequest(req) {
  const { schoolName } = await _sbStocktakingCurrentSchoolName(req);
  if (!schoolName) {
    const err = new Error("Could not determine school name for the current user.");
    err.status = 404;
    throw err;
  }
  const rows = await _sbStocktakingRows();
  const items = rows.map((row) => _sbSerializeStocktakingRow(row, schoolName));
  // Stocktaking must show both incoming Request Products (+qty) and outgoing Withdrawal Products (-qty).
  // Keep zero-only rows hidden so the page still behaves as an active stock/movement view.
  return items.filter((item) => Number(item.quantity) !== 0);
}

// Home global analysis — all Users Center members plus their page access.
app.get(
  "/api/home/analysis-users",
  requireAuth,
  async (req, res) => {
    res.set("Cache-Control", "no-store");
    try {
      if (!_sbTeamMembersEnabled()) return res.json({ users: [], source: "unavailable" });
      const rows = await _sbSelectTeamMembersRows();
      const users = [];
      for (const row of rows || []) {
        const id = String(_sbGet(row, ["id", "ID"]) ?? "").trim();
        const name = _sbString(_sbValueForLabel(row, "Name")) || "Unnamed";
        if (!id || !name) continue;
        let allowedPages = [];
        try {
          const access = await _sbAccountPayloadWithAccess(row, name);
          allowedPages = Array.isArray(access?.accountPayload?.allowedPages)
            ? access.accountPayload.allowedPages
            : [];
        } catch (accessError) {
          console.warn("[home-analysis] failed to resolve user access:", id, accessError?.message || accessError);
        }
        users.push({
          id,
          name,
          username: _sbString(_sbValueForLabel(row, "Username")) || name,
          email: _sbString(_sbValueForLabel(row, "Email")) || "",
          employeeCode: _sbString(_sbValueForLabel(row, "Employee Code")) || "",
          allowedPages,
        });
      }
      users.sort((a, b) => String(a.name).localeCompare(String(b.name)));
      return res.json({ users, source: "supabase" });
    } catch (error) {
      console.error("GET /api/home/analysis-users error:", error?.details || error?.body || error);
      return res.status(error?.status || 500).json({ error: error?.message || "Failed to load analysis users." });
    }
  },
);

