// =============================================================================
// Department Task Management — Supabase-only workflow tickets
// =============================================================================
// Each ticket is a cross-department request. Its sections are intentionally
// stored as ordered records so the workflow UI can render an execution path
// without relying on a nested JSON column or Notion relation.
function _tmTicketsTable() {
  return String(process.env.SUPABASE_DEPARTMENT_TICKETS_TABLE || "department_tickets").trim() || "department_tickets";
}

function _tmSectionsTable() {
  return String(process.env.SUPABASE_DEPARTMENT_TICKET_SECTIONS_TABLE || "department_ticket_sections").trim() || "department_ticket_sections";
}

function _tmEdgesTable() {
  return String(process.env.SUPABASE_DEPARTMENT_TICKET_EDGES_TABLE || "department_ticket_section_edges").trim() || "department_ticket_section_edges";
}

function _tmAssignmentsTable() {
  return String(process.env.SUPABASE_DEPARTMENT_TICKET_ASSIGNMENTS_TABLE || "department_ticket_section_assignments").trim() || "department_ticket_section_assignments";
}

function _tmAssignmentEdgesTable() {
  return String(process.env.SUPABASE_DEPARTMENT_TICKET_ASSIGNMENT_EDGES_TABLE || "department_ticket_section_assignment_edges").trim() || "department_ticket_section_assignment_edges";
}

function _tmText(value, max = 0) {
  const text = String(value ?? "").replace(/\r\n/g, "\n").trim();
  return max > 0 ? text.slice(0, max) : text;
}

function _tmDate(value) {
  const text = _tmText(value, 24);
  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : null;
}

function _tmAttachment(value = {}) {
  if (!value || typeof value !== "object") return null;
  const url = _tmText(value.url || value.attachmentUrl || value.attachment_url, 4000);
  const isProtectedStorageUrl = /^\/api\/storage\/file\/[A-Za-z0-9._~-]+(?:[?&].*)?$/i.test(url);
  if (!url || (!/^https?:\/\//i.test(url) && !isProtectedStorageUrl)) return null;
  return {
    name: _tmText(value.name || value.filename || value.attachmentName || value.attachment_name, 500) || "Attachment",
    url,
    type: _tmText(value.type || value.mime || value.attachmentType || value.attachment_type, 180),
    size: Math.max(0, Math.min(100 * 1024 * 1024, Number(value.size || value.attachmentSize || value.attachment_size) || 0)),
  };
}

function _tmDecodeWorkFiles(row = {}) {
  const rawUrl = _sbGet(row, ["work_file_url", "workFileUrl"]);
  if (typeof rawUrl === "string" && rawUrl.startsWith("__TM_WORK_FILES_JSON__:")) {
    try {
      const decoded = JSON.parse(rawUrl.slice("__TM_WORK_FILES_JSON__:".length));
      return _tmAttachments(decoded);
    } catch {}
  }
  const legacy = _tmAttachment({
    name: _sbGet(row, ["work_file_name", "workFileName"]),
    url: rawUrl,
    type: _sbGet(row, ["work_file_type", "workFileType"]),
    size: _sbGet(row, ["work_file_size", "workFileSize"]),
  });
  return legacy ? [legacy] : [];
}

function _tmWorkFileColumns(value) {
  const files = _tmAttachments(value).slice(0, 20);
  const first = files[0] || null;
  return {
    work_file_name: files.length > 1 ? `${files.length} work files` : (first?.name || null),
    work_file_url: files.length > 1
      ? `__TM_WORK_FILES_JSON__:${JSON.stringify(files)}`
      : (first?.url || null),
    work_file_type: first?.type || null,
    work_file_size: first?.size || null,
  };
}

function _tmAttachments(value, legacyValue = null) {
  let source = value;
  if (typeof source === "string") {
    try { source = JSON.parse(source); } catch { source = []; }
  }
  if (source && !Array.isArray(source) && Array.isArray(source.files)) source = source.files;
  else if (source && !Array.isArray(source) && typeof source === "object" && (source.url || source.attachmentUrl || source.attachment_url)) source = [source];
  const attachments = (Array.isArray(source) ? source : [])
    .map((item) => _tmAttachment(item))
    .filter(Boolean);
  const legacy = _tmAttachment(legacyValue);
  if (legacy && !attachments.some((item) => item.url === legacy.url)) attachments.unshift(legacy);
  const seen = new Set();
  return attachments.filter((item) => {
    if (!item?.url || seen.has(item.url)) return false;
    seen.add(item.url);
    return true;
  }).slice(0, 20);
}

function _tmAttachmentColumns(attachments = []) {
  const files = _tmAttachments(attachments);
  const first = files[0] || null;
  return {
    attachments: files,
    attachment_name: first?.name || null,
    attachment_url: first?.url || null,
    attachment_type: first?.type || null,
    attachment_size: first?.size || null,
  };
}

function _tmStatus(value, fallback = "not_started") {
  const raw = _tmText(value, 40).toLowerCase().replace(/[\s-]+/g, "_");
  const aliases = {
    "notstarted": "not_started",
    "not_started": "not_started",
    "new": "not_started",
    "inprogress": "in_progress",
    "in_progress": "in_progress",
    "working": "in_progress",
    "rejected": "rejected",
    "reject": "rejected",
    "completed": "completed",
    "complete": "completed",
    "done": "completed",
    "cancelled": "cancelled",
    "canceled": "cancelled",
  };
  return aliases[raw] || fallback;
}

function _tmStatusLabel(value) {
  const status = _tmStatus(value);
  return ({
    not_started: "Not started",
    in_progress: "In progress",
    rejected: "Rejected",
    completed: "Completed",
    cancelled: "Cancelled",
  })[status] || "Not started";
}

function _tmPriority(value) {
  const raw = _tmText(value, 30).toLowerCase();
  if (["urgent", "high", "normal", "low"].includes(raw)) return raw.charAt(0).toUpperCase() + raw.slice(1);
  return "Normal";
}

function _tmId(row = {}) {
  return String(_sbGet(row, ["id", "ID"]) ?? "").trim();
}

function _tmTicketCode(row = {}) {
  const existing = _tmText(_sbGet(row, ["ticket_code", "ticketCode", "code", "Code"]), 80);
  if (existing) return existing;
  const id = _tmId(row);
  const numeric = Number(id);
  return Number.isFinite(numeric) ? `TKT-${String(Math.max(0, numeric)).padStart(5, "0")}` : (id ? `TKT-${id}` : "TKT");
}

function _tmSameText(left, right) {
  return norm(String(left || "")) === norm(String(right || ""));
}

async function _tmCurrentMember(req) {
  const row = await _sbFindSessionTeamMember(req).catch(() => null);
  const id = _tmId(row);
  return {
    id,
    name: _sbString(_sbValueForLabel(row || {}, "Name")) || _tmText(req?.session?.username || "", 180) || "User",
    department: _sbString(_sbValueForLabel(row || {}, "Department")) || "",
    position: _sbString(_sbValueForLabel(row || {}, "Position")) || "",
  };
}

async function _tmDepartmentOptions() {
  const rows = await _sbSelectTeamMembersRows();
  const values = new Map();
  for (const row of rows || []) {
    const department = _tmText(_sbValueForLabel(row, "Department"), 120);
    if (!department) continue;
    const key = norm(department);
    if (key && !values.has(key)) values.set(key, department);
  }
  return Array.from(values.values()).sort((a, b) => a.localeCompare(b));
}

function _tmSerializeSection(row = {}) {
  const status = _tmStatus(_sbGet(row, ["status", "Status"]));
  const legacyAttachment = _tmAttachment({
    name: _sbGet(row, ["attachment_name", "attachmentName"]),
    url: _sbGet(row, ["attachment_url", "attachmentUrl"]),
    type: _sbGet(row, ["attachment_type", "attachmentType"]),
    size: _sbGet(row, ["attachment_size", "attachmentSize"]),
  });
  const attachments = _tmAttachments(_sbGet(row, ["attachments", "attachment_files", "attachmentFiles"]), legacyAttachment);
  const attachment = attachments[0] || null;
  return {
    id: _tmId(row),
    ticketId: String(_sbGet(row, ["ticket_id", "ticketId"]) ?? "").trim(),
    department: _tmText(_sbGet(row, ["department", "Department"]), 120),
    request: _tmText(_sbGet(row, ["request_text", "request", "Request", "title", "Title"]), 4000),
    details: _tmText(_sbGet(row, ["details", "description", "Description"]), 8000),
    deliveryDate: _tmDate(_sbGet(row, ["delivery_date", "deliveryDate"])),
    attachments,
    attachment,
    sortOrder: Number(_sbGet(row, ["sort_order", "sortOrder"]) || 0),
    executionGroup: Math.max(1, Number(_sbGet(row, ["execution_group", "executionGroup", "stage", "stage_number"]) || _sbGet(row, ["sort_order", "sortOrder"]) || 1)),
    canvasX: Number(_sbGet(row, ["canvas_x", "canvasX", "node_x", "nodeX"]) || 0),
    canvasY: Number(_sbGet(row, ["canvas_y", "canvasY", "node_y", "nodeY"]) || 0),
    status,
    statusLabel: _tmStatusLabel(status),
    completionNote: _tmText(_sbGet(row, ["completion_note", "completionNote", "work_note", "workNote"]), 8000),
    workReport: _tmText(_sbGet(row, ["work_report", "workReport", "completion_note", "completionNote"]), 12000),
    rejectionReason: _tmText(_sbGet(row, ["rejection_reason", "rejectionReason"]), 4000),
    workLink: _tmText(_sbGet(row, ["work_link", "workLink"]), 4000),
    workFiles: _tmDecodeWorkFiles(row),
    workFile: _tmDecodeWorkFiles(row)[0] || null,
    startedAt: _sbGet(row, ["started_at", "startedAt"]) || null,
    completedAt: _sbGet(row, ["completed_at", "completedAt"]) || null,
    completedByName: _tmText(_sbGet(row, ["completed_by_name", "completedByName"]), 180),
    updatedAt: _sbGet(row, ["updated_at", "updatedAt"]) || null,
  };
}

function _tmSerializeEdge(row = {}) {
  return {
    id: _tmId(row),
    ticketId: String(_sbGet(row, ["ticket_id", "ticketId"]) ?? "").trim(),
    from: String(_sbGet(row, ["from_section_id", "fromSectionId", "from"]) ?? "").trim(),
    to: String(_sbGet(row, ["to_section_id", "toSectionId", "to"]) ?? "").trim(),
  };
}

function _tmTicketStatusFromSections(sections = []) {
  const statuses = (sections || []).map((section) => _tmStatus(section?.status)).filter(Boolean);
  if (!statuses.length) return "not_started";
  if (statuses.every((status) => status === "completed")) return "completed";
  if (statuses.some((status) => status === "rejected")) return "rejected";
  if (statuses.every((status) => status === "cancelled")) return "cancelled";
  if (statuses.some((status) => status === "in_progress" || status === "completed" || status === "cancelled")) return "in_progress";
  return "not_started";
}

function _tmSerializeTicket(row = {}, sectionRows = [], edgeRows = []) {
  const id = _tmId(row);
  const sections = (sectionRows || []).map(_tmSerializeSection).sort((a, b) => (a.executionGroup - b.executionGroup) || (a.sortOrder - b.sortOrder) || Number(a.id) - Number(b.id));
  const edges = (edgeRows || []).map(_tmSerializeEdge).filter((edge) => edge.from && edge.to);
  const calculatedStatus = _tmTicketStatusFromSections(sections);
  const completedCount = sections.filter((section) => section.status === "completed").length;
  return {
    id,
    ticketCode: _tmTicketCode(row),
    title: _tmText(_sbGet(row, ["title", "Title", "name", "Name"]), 500) || "Untitled ticket",
    description: _tmText(_sbGet(row, ["description", "details", "Description"]), 8000),
    priority: _tmPriority(_sbGet(row, ["priority", "Priority"])),
    dueDate: _tmDate(_sbGet(row, ["due_date", "dueDate", "deadline", "Deadline"])),
    status: calculatedStatus,
    statusLabel: _tmStatusLabel(calculatedStatus),
    createdAt: _sbGet(row, ["created_at", "createdAt"]) || null,
    updatedAt: _sbGet(row, ["updated_at", "updatedAt"]) || null,
    createdById: _tmText(_sbGet(row, ["created_by_id", "createdById"]), 120),
    createdByName: _tmText(_sbGet(row, ["created_by_name", "createdByName"]), 180) || "—",
    isArchived: !!_sbGet(row, ["is_archived", "isArchived"]),
    archivedAt: _sbGet(row, ["archived_at", "archivedAt"]) || null,
    archivedById: _tmText(_sbGet(row, ["archived_by_id", "archivedById"]), 120),
    archivedByName: _tmText(_sbGet(row, ["archived_by_name", "archivedByName"]), 180),
    archivedFromView: _tmText(_sbGet(row, ["archived_from_view", "archivedFromView"]), 30),
    sections,
    edges,
    sectionsCount: sections.length,
    completedCount,
    progress: sections.length ? Math.round((completedCount / sections.length) * 100) : 0,
  };
}

async function _tmLoadAllTickets() {
  if (!supabaseDb.isConfigured()) {
    const error = new Error("Supabase is not configured.");
    error.status = 503;
    throw error;
  }

  let ticketRows;
  let sectionRows;
  let edgeRows;
  try {
    [ticketRows, sectionRows, edgeRows] = await Promise.all([
      supabaseDb.selectAll(_tmTicketsTable(), { limit: 5000, order: "created_at.desc,id.desc" }),
      supabaseDb.selectAll(_tmSectionsTable(), { limit: 20000, order: "sort_order.asc,id.asc" }),
      supabaseDb.selectAll(_tmEdgesTable(), { limit: 30000, order: "id.asc" }),
    ]);
  } catch (error) {
    const detail = String(error?.message || "");
    if (/relation .* does not exist|Could not find the table|schema cache/i.test(detail)) {
      const missing = new Error("Task Management workflow tables are not installed. Run the supplied Supabase SQL migration, then refresh this page.");
      missing.status = 503;
      throw missing;
    }
    throw error;
  }

  const sectionsByTicket = new Map();
  for (const row of Array.isArray(sectionRows) ? sectionRows : []) {
    const ticketId = String(_sbGet(row, ["ticket_id", "ticketId"]) ?? "").trim();
    if (!ticketId) continue;
    if (!sectionsByTicket.has(ticketId)) sectionsByTicket.set(ticketId, []);
    sectionsByTicket.get(ticketId).push(row);
  }
  const edgesByTicket = new Map();
  for (const row of Array.isArray(edgeRows) ? edgeRows : []) {
    const ticketId = String(_sbGet(row, ["ticket_id", "ticketId"]) ?? "").trim();
    if (!ticketId) continue;
    if (!edgesByTicket.has(ticketId)) edgesByTicket.set(ticketId, []);
    edgesByTicket.get(ticketId).push(row);
  }

  return (Array.isArray(ticketRows) ? ticketRows : [])
    .map((row) => _tmSerializeTicket(row, sectionsByTicket.get(_tmId(row)) || [], edgesByTicket.get(_tmId(row)) || []));
}

async function _tmLoadTicketById(ticketId) {
  const cleanId = String(ticketId || "").trim();
  if (!cleanId) return null;
  const ticket = await supabaseDb.selectById(_tmTicketsTable(), cleanId);
  if (!ticket) return null;
  const [sections, edges] = await Promise.all([
    supabaseDb.select(_tmSectionsTable(), {
      select: "*",
      ticket_id: `eq.${_sbRestFilterValue(cleanId)}`,
      limit: 1000,
      order: "sort_order.asc,id.asc",
    }),
    supabaseDb.select(_tmEdgesTable(), {
      select: "*",
      ticket_id: `eq.${_sbRestFilterValue(cleanId)}`,
      limit: 3000,
      order: "id.asc",
    }),
  ]);
  return _tmSerializeTicket(ticket, Array.isArray(sections) ? sections : [], Array.isArray(edges) ? edges : []);
}

async function _tmSyncTicketStatus(ticketId) {
  const ticket = await _tmLoadTicketById(ticketId);
  if (!ticket) return null;
  const status = _tmTicketStatusFromSections(ticket.sections || []);
  const current = _tmStatus(ticket.status, status);
  if (status !== current) {
    await supabaseDb.updateById(_tmTicketsTable(), ticket.id, { status, updated_at: new Date().toISOString() });
    ticket.status = status;
    ticket.statusLabel = _tmStatusLabel(status);
  }
  return ticket;
}

app.post("/api/task-management/upload", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const dataUrl = String(req.body?.dataUrl || req.body?.data || "").trim();
    const filename = _tmText(req.body?.filename || req.body?.name, 500) || "attachment";
    const mimeHint = _tmText(req.body?.mime || req.body?.type, 180);
    const match = dataUrl.match(/^data:([^;,]+)?;base64,([\s\S]+)$/i);
    if (!match) return res.status(400).json({ ok: false, error: "Choose a valid attachment first." });
    const bytes = Buffer.from(match[2], "base64");
    if (!bytes.length) return res.status(400).json({ ok: false, error: "The selected attachment is empty." });
    if (bytes.length > 10 * 1024 * 1024) return res.status(413).json({ ok: false, error: "The attachment must be 10 MB or less." });
    const cleanName = filename.replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || `attachment-${Date.now()}`;
    const objectPath = `task-management/attachments/${Date.now()}-${Math.random().toString(16).slice(2)}-${cleanName}`;
    const url = await uploadToBlobFromBase64(dataUrl, objectPath);
    return res.status(201).json({
      ok: true,
      file: { name: filename, url, type: mimeHint || match[1] || "application/octet-stream", size: bytes.length },
    });
  } catch (error) {
    console.error("[task-management] attachment upload error:", error?.details || error?.message || error);
    const raw = String(error?.message || "");
    const message = raw.includes("SUPABASE_STORAGE_OR_BLOB_TOKEN_MISSING")
      ? "File storage is not configured. Add a Supabase Storage bucket or Vercel Blob token."
      : (error?.message || "Failed to upload attachment.");
    return res.status(error?.status || 500).json({ ok: false, error: message });
  }
});

app.get("/api/task-management/meta", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const [currentUser, departments] = await Promise.all([_tmCurrentMember(req), _tmDepartmentOptions()]);
    return res.json({
      ok: true,
      view: req.taskManagementView,
      currentUser,
      departments,
      accessLevel: req.opsPageAccessLevel || (_taskManagementViewIsAdmin(req, req.taskManagementView) ? PAGE_ACCESS_LEVELS.ADMIN : PAGE_ACCESS_LEVELS.VIEW),
      isPageAdmin: _taskManagementViewIsAdmin(req, req.taskManagementView),
    });
  } catch (error) {
    console.error("[task-management] meta error:", error?.details || error?.message || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to load Task Management options." });
  }
});

app.post("/api/task-management/admin/verify", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const adminPages = [_taskManagementViewAccessPage(req.taskManagementView), "Task Management"].filter(Boolean);
    const ok = await _verifyPageAdminPassword(req, req.body?.adminPassword, adminPages);
    if (!ok) return res.status(401).json({ ok: false, error: "Invalid admin password." });
    return res.json({ ok: true });
  } catch (error) {
    console.error("[task-management] admin verify error:", error?.details || error?.message || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to verify admin password." });
  }
});

function _tmSameMember(ticket = {}, currentMember = {}) {
  const currentId = _tmText(currentMember?.id || "", 120);
  const ticketCreatorId = _tmText(ticket?.createdById || "", 120);
  if (currentId && ticketCreatorId) return currentId === ticketCreatorId;
  const currentName = _tmText(currentMember?.name || "", 180);
  const ticketCreatorName = _tmText(ticket?.createdByName || "", 180);
  return !!(currentName && ticketCreatorName && _tmSameText(currentName, ticketCreatorName));
}

function _tmArchivedByMember(ticket = {}, currentMember = {}) {
  const archivedById = _tmText(ticket?.archivedById || "", 120);
  const currentId = _tmText(currentMember?.id || "", 120);
  if (archivedById && currentId) return archivedById === currentId;
  const archivedByName = _tmText(ticket?.archivedByName || "", 180);
  const currentName = _tmText(currentMember?.name || "", 180);
  return !!(archivedByName && currentName && _tmSameText(archivedByName, currentName));
}

function _tmArchiveView(ticket = {}) {
  const view = _tmText(ticket?.archivedFromView || "", 30).toLowerCase();
  if (["all", "my", "delegated"].includes(view)) return view;
  // Existing archived rows created before the per-page archive migration are
  // treated as Delegated Tasks archives, which matches the original archive
  // workflow where the project creator managed the record.
  return "delegated";
}

function _tmTicketBelongsToView(ticket = {}, currentMember = {}, view = "") {
  if (ticket?.isArchived) {
    // An archived task is globally hidden. It is returned only to the person
    // who archived it and only in the Task Management page where they did it.
    return _tmArchivedByMember(ticket, currentMember) && _tmArchiveView(ticket) === view;
  }
  if (view === "all") return true;
  if (view === "delegated") return _tmSameMember(ticket, currentMember);
  if (view === "my") {
    const department = _tmText(currentMember?.department || "", 120);
    return !!(department && (ticket.sections || []).some((section) => _tmSameText(section?.department || "", department)));
  }
  return false;
}

async function _tmAssignmentsForCurrentMember(currentMember = {}) {
  const currentId = _tmText(currentMember?.id, 120);
  if (currentId) {
    return await supabaseDb.select(_tmAssignmentsTable(), {
      select: "id,section_id,assignee_id,assignee_name,status",
      assignee_id: `eq.${_sbRestFilterValue(currentId)}`,
      limit: 5000,
      order: "id.asc",
    });
  }
  const rows = await supabaseDb.selectAll(_tmAssignmentsTable(), { limit: 20000, order: "id.asc" });
  return (rows || []).filter((row) =>
    _tmSameText(_sbGet(row, ["assignee_name", "assigneeName"]), currentMember?.name || ""));
}

function _tmTicketViewerProgress(ticket = {}, currentMember = {}, view = "", canManageDepartment = false, assignmentRows = []) {
  if (view !== "my") {
    return {
      viewerSectionsCount: Number(ticket.sectionsCount || 0),
      viewerCompletedCount: Number(ticket.completedCount || 0),
      viewerProgress: Number(ticket.progress || 0),
    };
  }

  if (canManageDepartment) {
    const department = _tmText(currentMember?.department || "", 120);
    const relevant = (ticket.sections || []).filter((section) =>
      department && _tmSameText(section?.department || "", department));
    const completed = relevant.filter((section) => _tmStatus(section?.status) === "completed").length;
    return {
      viewerSectionsCount: relevant.length,
      viewerCompletedCount: completed,
      viewerProgress: relevant.length ? Math.round((completed / relevant.length) * 100) : 0,
    };
  }

  const sectionIds = new Set((ticket.sections || []).map((section) => String(section?.id || "")).filter(Boolean));
  const seen = new Set();
  const relevant = (assignmentRows || []).filter((row) => {
    const sectionId = String(_sbGet(row, ["section_id", "sectionId"]) || "").trim();
    const id = String(_sbGet(row, ["id", "ID"]) || `${sectionId}:${_sbGet(row, ["assignee_id", "assigneeId", "assignee_name", "assigneeName"]) || ""}`).trim();
    if (!sectionIds.has(sectionId) || !id || seen.has(id)) return false;
    seen.add(id);
    return true;
  });
  const completed = relevant.filter((row) => _tmStatus(_sbGet(row, ["status", "Status"])) === "completed").length;
  return {
    viewerSectionsCount: relevant.length,
    viewerCompletedCount: completed,
    viewerProgress: relevant.length ? Math.round((completed / relevant.length) * 100) : 0,
  };
}

function _tmCanUpdateSectionInView(req, ticket = {}, section = {}, currentMember = {}, view = "") {
  if (_taskManagementViewIsAdmin(req, view)) return true;
  const isCreator = _tmSameMember(ticket, currentMember);
  const isDepartment = _tmSameText(section?.department || "", currentMember?.department || "");
  if (view === "delegated") return isCreator;
  if (view === "my") return isDepartment;
  // All Tasks is a company-wide visibility view. Edit users can update only
  // their own delegated work or work assigned to their own department.
  if (view === "all") return isCreator || isDepartment;
  return false;
}

app.get("/api/task-management", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const requestedStatus = _tmStatus(req.query?.status || "", "all");
    const query = norm(_tmText(req.query?.q || "", 200));
    const currentUser = await _tmCurrentMember(req);
    let tickets = await _tmLoadAllTickets();
    tickets = tickets.filter((ticket) =>
      _tmTicketBelongsToView(ticket, currentUser, req.taskManagementView));

    // Edit/Admin users manage every department section. View users receive only
    // projects that contain a person task assigned directly to them.
    let viewerAssignmentRows = [];
    if (req.taskManagementView === "my" && _tmTaskAccessLevel(req) === "view" && !_taskManagementViewIsAdmin(req, "my")) {
      viewerAssignmentRows = await _tmAssignmentsForCurrentMember(currentUser);
      const assignedSectionIds = new Set((viewerAssignmentRows || [])
        .map((row) => String(_sbGet(row, ["section_id", "sectionId"]) || "").trim())
        .filter(Boolean));
      tickets = tickets.filter((ticket) =>
        (ticket.sections || []).some((section) => assignedSectionIds.has(String(section.id))));
    }

    if (requestedStatus !== "all") tickets = tickets.filter((ticket) => ticket.status === requestedStatus);
    if (query) {
      tickets = tickets.filter((ticket) => {
        const haystack = [
          ticket.ticketCode, ticket.title, ticket.description, ticket.createdByName,
          ...(ticket.sections || []).flatMap((section) => [section.department, section.request, section.details, section.deliveryDate, section.attachment?.name]),
        ].map(norm).join(" ");
        return haystack.includes(query);
      });
    }
    const canManageDepartment = req.taskManagementView === "my" && _tmCanManageDepartmentWork(req);
    tickets = tickets.map((ticket) => ({
      ..._tmTicketForViewer(ticket, currentUser, req.taskManagementView, canManageDepartment),
      ..._tmTicketViewerProgress(ticket, currentUser, req.taskManagementView, canManageDepartment, viewerAssignmentRows),
    }));
    return res.json({ ok: true, tickets });
  } catch (error) {
    console.error("[task-management] list error:", error?.details || error?.message || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to load tickets." });
  }
});

app.get("/api/task-management/:id", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const ticket = await _tmLoadTicketById(req.params.id);
    if (!ticket) return res.status(404).json({ ok: false, error: "Ticket not found." });
    const currentUser = await _tmCurrentMember(req);
    if (!_tmTicketBelongsToView(ticket, currentUser, req.taskManagementView)) {
      return res.status(403).json({ ok: false, error: "This ticket is not available in the selected Task Management view." });
    }
    const canManageDepartment = req.taskManagementView === "my" && _tmCanManageDepartmentWork(req);
    const viewerAssignmentRows = req.taskManagementView === "my" && !canManageDepartment
      ? await _tmAssignmentsForCurrentMember(currentUser)
      : [];
    return res.json({
      ok: true,
      ticket: {
        ..._tmTicketForViewer(ticket, currentUser, req.taskManagementView, canManageDepartment),
        ..._tmTicketViewerProgress(ticket, currentUser, req.taskManagementView, canManageDepartment, viewerAssignmentRows),
      },
    });
  } catch (error) {
    console.error("[task-management] detail error:", error?.details || error?.message || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to load ticket." });
  }
});

function _tmCanvasNumber(value, fallback = 0) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(0, Math.min(10000, Math.round(number)));
}

function _tmBuildWorkflowPlan(rawSections = [], rawEdges) {
  const sourceSections = (Array.isArray(rawSections) ? rawSections : []).slice(0, 40);
  const hasGraphDefinition = Array.isArray(rawEdges);
  const prepared = sourceSections.map((item, index) => ({
    clientId: _tmText(item?.clientId || item?.client_id || item?.id || `section-${index + 1}`, 120) || `section-${index + 1}`,
    department: _tmText(item?.department, 120),
    request: _tmText(item?.request || item?.requestText || item?.title, 4000),
    details: _tmText(item?.details || item?.description, 8000),
    deliveryDate: _tmDate(item?.deliveryDate || item?.delivery_date),
    attachments: _tmAttachments(item?.attachments || item?.attachment_files, item?.attachment || {
      name: item?.attachmentName || item?.attachment_name,
      url: item?.attachmentUrl || item?.attachment_url,
      type: item?.attachmentType || item?.attachment_type,
      size: item?.attachmentSize || item?.attachment_size,
    }),
    sortOrder: index + 1,
    canvasX: _tmCanvasNumber(item?.canvasX ?? item?.canvas_x ?? item?.nodeX ?? item?.node_x, 0),
    canvasY: _tmCanvasNumber(item?.canvasY ?? item?.canvas_y ?? item?.nodeY ?? item?.node_y, 0),
    executionGroup: Math.max(1, Math.min(40, Number(item?.executionGroup ?? item?.execution_group ?? item?.stage ?? index + 1) || index + 1)),
  }));
  prepared.forEach((section) => { section.attachment = section.attachments[0] || null; });
  const ids = new Set();
  for (const section of prepared) {
    if (ids.has(section.clientId)) throw new Error("Workflow blocks must have unique IDs.");
    ids.add(section.clientId);
  }

  if (!hasGraphDefinition) {
    const distinctGroups = [...new Set(prepared.map((section) => section.executionGroup))].sort((a, b) => a - b);
    const groupMap = new Map(distinctGroups.map((group, index) => [group, index + 1]));
    return { sections: prepared.map((section) => ({ ...section, executionGroup: groupMap.get(section.executionGroup) || 1 })), edges: [] };
  }

  const edgeMap = new Map();
  for (const item of rawEdges.slice(0, 120)) {
    const from = _tmText(item?.from ?? item?.fromClientId ?? item?.from_section_id, 120);
    const to = _tmText(item?.to ?? item?.toClientId ?? item?.to_section_id, 120);
    if (!from || !to) throw new Error("Every workflow arrow needs a source and destination block.");
    if (!ids.has(from) || !ids.has(to)) throw new Error("A workflow arrow references an unknown block.");
    if (from === to) throw new Error("A workflow arrow cannot point to the same block.");
    edgeMap.set(`${from}::${to}`, { from, to });
  }
  const edges = [...edgeMap.values()];
  const outgoing = new Map(prepared.map((section) => [section.clientId, []]));
  const incomingCount = new Map(prepared.map((section) => [section.clientId, 0]));
  edges.forEach((edge) => {
    outgoing.get(edge.from).push(edge.to);
    incomingCount.set(edge.to, (incomingCount.get(edge.to) || 0) + 1);
  });
  const rank = new Map(prepared.map((section) => [section.clientId, 1]));
  const queue = prepared.filter((section) => incomingCount.get(section.clientId) === 0).map((section) => section.clientId);
  let processed = 0;
  while (queue.length) {
    const current = queue.shift();
    processed += 1;
    for (const next of outgoing.get(current) || []) {
      rank.set(next, Math.max(rank.get(next) || 1, (rank.get(current) || 1) + 1));
      incomingCount.set(next, (incomingCount.get(next) || 0) - 1);
      if (incomingCount.get(next) === 0) queue.push(next);
    }
  }
  if (processed !== prepared.length) throw new Error("The workflow contains a circular arrow. Remove the loop and try again.");
  return { sections: prepared.map((section) => ({ ...section, executionGroup: rank.get(section.clientId) || 1 })), edges };
}

function _tmSectionPrerequisites(ticket = {}, section = {}) {
  const sectionId = String(section?.id || "");
  const edgeRows = Array.isArray(ticket?.edges) ? ticket.edges : [];
  const predecessors = edgeRows
    .filter((edge) => String(edge?.to ?? edge?.toSectionId ?? edge?.to_section_id ?? "") === sectionId)
    .map((edge) => String(edge?.from ?? edge?.fromSectionId ?? edge?.from_section_id ?? ""))
    .filter(Boolean);
  if (predecessors.length) {
    const byId = new Map((ticket.sections || []).map((item) => [String(item.id), item]));
    return predecessors.map((id) => byId.get(id)).filter(Boolean);
  }
  const currentGroup = Math.max(1, Number(section?.executionGroup || section?.sortOrder || 1));
  return (ticket.sections || []).filter((item) => Math.max(1, Number(item?.executionGroup || item?.sortOrder || 1)) < currentGroup);
}


async function _tmMembersForDepartment(department) {
  const wanted = _tmText(department, 120);
  if (!wanted) return [];
  const rows = await _sbSelectTeamMembersRows();
  return (rows || [])
    .map((row) => ({
      id: _tmId(row),
      name: _tmText(_sbValueForLabel(row, "Name"), 180),
      department: _tmText(_sbValueForLabel(row, "Department"), 120),
      position: _tmText(_sbValueForLabel(row, "Position"), 180),
    }))
    .filter((member) => member.id && member.name && _tmSameText(member.department, wanted))
    .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: "base" }));
}

function _tmSerializeAssignment(row = {}) {
  const legacyAttachment = _tmAttachment({
    name: _sbGet(row, ["attachment_name", "attachmentName"]),
    url: _sbGet(row, ["attachment_url", "attachmentUrl"]),
    type: _sbGet(row, ["attachment_type", "attachmentType"]),
    size: _sbGet(row, ["attachment_size", "attachmentSize"]),
  });
  const attachments = _tmAttachments(_sbGet(row, ["attachments", "attachment_files", "attachmentFiles"]), legacyAttachment);
  const attachment = attachments[0] || null;
  return {
    id: _tmId(row),
    sectionId: String(_sbGet(row, ["section_id", "sectionId"]) ?? "").trim(),
    assigneeId: _tmText(_sbGet(row, ["assignee_id", "assigneeId"]), 120),
    assigneeName: _tmText(_sbGet(row, ["assignee_name", "assigneeName"]), 180),
    task: _tmText(_sbGet(row, ["task_text", "task", "request_text", "request"]), 4000),
    details: _tmText(_sbGet(row, ["details", "description"]), 8000),
    deliveryDate: _tmDate(_sbGet(row, ["delivery_date", "deliveryDate"])),
    attachments,
    attachment,
    sortOrder: Number(_sbGet(row, ["sort_order", "sortOrder"]) || 0),
    executionGroup: Math.max(1, Number(_sbGet(row, ["execution_group", "executionGroup"]) || _sbGet(row, ["sort_order", "sortOrder"]) || 1)),
    canvasX: Number(_sbGet(row, ["canvas_x", "canvasX"]) || 0),
    canvasY: Number(_sbGet(row, ["canvas_y", "canvasY"]) || 0),
    status: _tmStatus(_sbGet(row, ["status", "Status"])),
    workReport: _tmText(_sbGet(row, ["work_report", "workReport"]), 12000),
    rejectionReason: _tmText(_sbGet(row, ["rejection_reason", "rejectionReason"]), 4000),
    workLink: _tmText(_sbGet(row, ["work_link", "workLink"]), 4000),
    workFiles: _tmDecodeWorkFiles(row),
    workFile: _tmDecodeWorkFiles(row)[0] || null,
    createdAt: _sbGet(row, ["created_at", "createdAt"]) || null,
    updatedAt: _sbGet(row, ["updated_at", "updatedAt"]) || null,
  };
}

function _tmSerializeAssignmentEdge(row = {}) {
  return {
    id: _tmId(row),
    sectionId: String(_sbGet(row, ["section_id", "sectionId"]) ?? "").trim(),
    from: String(_sbGet(row, ["from_assignment_id", "fromAssignmentId", "from"]) ?? "").trim(),
    to: String(_sbGet(row, ["to_assignment_id", "toAssignmentId", "to"]) ?? "").trim(),
  };
}

async function _tmLoadPeopleWorkflow(sectionId) {
  const cleanId = String(sectionId || "").trim();
  if (!cleanId) return { assignments: [], edges: [] };
  try {
    const [assignmentRows, edgeRows] = await Promise.all([
      supabaseDb.select(_tmAssignmentsTable(), {
        select: "*",
        section_id: `eq.${_sbRestFilterValue(cleanId)}`,
        limit: 1000,
        order: "sort_order.asc,id.asc",
      }),
      supabaseDb.select(_tmAssignmentEdgesTable(), {
        select: "*",
        section_id: `eq.${_sbRestFilterValue(cleanId)}`,
        limit: 3000,
        order: "id.asc",
      }),
    ]);
    return {
      assignments: (Array.isArray(assignmentRows) ? assignmentRows : []).map(_tmSerializeAssignment),
      edges: (Array.isArray(edgeRows) ? edgeRows : []).map(_tmSerializeAssignmentEdge).filter((edge) => edge.from && edge.to),
    };
  } catch (error) {
    const detail = String(error?.message || "");
    if (/relation .* does not exist|Could not find the table|schema cache/i.test(detail)) {
      const missing = new Error("The My Tasks team-workflow tables are not installed. Run the supplied My Tasks SQL migration, then refresh this page.");
      missing.status = 503;
      throw missing;
    }
    throw error;
  }
}

function _tmBuildPeopleWorkflowPlan(rawAssignments = [], rawEdges) {
  const source = (Array.isArray(rawAssignments) ? rawAssignments : []).slice(0, 60);
  const byClientId = new Map();
  const genericSections = source.map((item, index) => {
    const clientId = _tmText(item?.clientId || item?.client_id || item?.id || `assignment-${index + 1}`, 120) || `assignment-${index + 1}`;
    byClientId.set(clientId, {
      assigneeId: _tmText(item?.assigneeId || item?.assignee_id, 120),
      assigneeName: _tmText(item?.assigneeName || item?.assignee_name, 180),
    });
    return {
      clientId,
      department: _tmText(item?.assigneeName || item?.assignee_name, 180),
      request: _tmText(item?.task || item?.taskText || item?.task_text || item?.request, 4000),
      details: _tmText(item?.details || item?.description, 8000),
      deliveryDate: _tmDate(item?.deliveryDate || item?.delivery_date),
      attachments: item?.attachments || null,
      attachment: item?.attachment || null,
      canvasX: item?.canvasX ?? item?.canvas_x,
      canvasY: item?.canvasY ?? item?.canvas_y,
      executionGroup: item?.executionGroup ?? item?.execution_group ?? index + 1,
    };
  });
  const generic = _tmBuildWorkflowPlan(genericSections, rawEdges);
  return {
    assignments: generic.sections.map((item) => {
      const owner = byClientId.get(item.clientId) || {};
      return {
        ...item,
        assigneeId: owner.assigneeId || "",
        assigneeName: owner.assigneeName || item.department || "",
        task: item.request,
      };
    }),
    edges: generic.edges,
  };
}

function _tmAssertOwnDepartmentSection(ticket, section, currentUser) {
  if (!ticket || !section) {
    const error = new Error("Workflow section not found.");
    error.status = 404;
    throw error;
  }
  if (!_tmSameText(section.department || "", currentUser?.department || "")) {
    const error = new Error("This task belongs to another department.");
    error.status = 403;
    throw error;
  }
}

function _tmTaskAccessLevel(req) {
  const raw = _tmText(req?.opsPageAccessLevel || "", 30).toLowerCase();
  if (raw === PAGE_ACCESS_LEVELS.ADMIN || raw === "admin") return "admin";
  if (raw === PAGE_ACCESS_LEVELS.EDIT || raw === "edit") return "edit";
  return "view";
}

function _tmCanManageDepartmentWork(req) {
  return _taskManagementViewIsAdmin(req, "my") || ["edit", "admin"].includes(_tmTaskAccessLevel(req));
}

function _tmSameAssignmentMember(assignment = {}, currentUser = {}) {
  const assigneeId = _tmText(assignment?.assigneeId || assignment?.assignee_id, 120);
  const currentId = _tmText(currentUser?.id, 120);
  if (assigneeId && currentId) return assigneeId === currentId;
  return !!(_tmText(assignment?.assigneeName || assignment?.assignee_name, 180) &&
    _tmSameText(assignment?.assigneeName || assignment?.assignee_name, currentUser?.name || ""));
}

function _tmCanEditAssignmentWork(req, assignment = {}, currentUser = {}) {
  if (_taskManagementViewIsAdmin(req, "my") || _tmTaskAccessLevel(req) === "admin") return true;
  return _tmTaskAccessLevel(req) === "view" && _tmSameAssignmentMember(assignment, currentUser);
}

function _tmAssignmentForViewer(assignment = {}, currentUser = {}, revealAll = false, published = false) {
  const own = _tmSameAssignmentMember(assignment, currentUser);
  if (revealAll || own || published) return { ...assignment };
  return {
    ...assignment,
    workReport: "",
    rejectionReason: "",
    workLink: "",
    workFile: null,
  };
}

function _tmWorkflowForViewer(workflow = {}, currentUser = {}, options = {}) {
  const revealAll = options === true || !!options?.revealAll;
  const published = !!options?.published;
  return {
    assignments: (workflow.assignments || []).map((assignment) => _tmAssignmentForViewer(assignment, currentUser, revealAll, published)),
    edges: Array.isArray(workflow.edges) ? workflow.edges : [],
  };
}

function _tmSectionForViewer(section = {}, currentUser = {}, view = "", canManageDepartment = false) {
  const status = _tmStatus(section?.status);
  const published = status === "completed";
  const managerPreview = view === "my" && canManageDepartment && _tmSameText(section?.department || "", currentUser?.department || "");
  if (published || managerPreview) return { ...section };
  return {
    ...section,
    completionNote: "",
    workReport: "",
    // Rejection is a task-state explanation, not private work content. Keep it
    // available in All Tasks, My Tasks, and Delegated Tasks so the Rejected
    // status chip opens the same reason from every page.
    rejectionReason: status === "rejected" ? _tmText(section?.rejectionReason || "", 4000) : "",
    workLink: "",
    workFile: null,
    completedByName: "",
  };
}

function _tmTicketForViewer(ticket = {}, currentUser = {}, view = "", canManageDepartment = false) {
  return {
    ...ticket,
    sections: (ticket.sections || []).map((section) => _tmSectionForViewer(section, currentUser, view, canManageDepartment)),
  };
}

function _tmBuildTeamDraftReport(workflow = {}, existingReport = "") {
  const startMarker = "--- Team member submissions (auto-synced) ---";
  const endMarker = "--- End team member submissions ---";
  const escapedStart = startMarker.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const escapedEnd = endMarker.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const manual = String(existingReport || "")
    .replace(new RegExp(`${escapedStart}[\\s\\S]*?${escapedEnd}`, "g"), "")
    .trim();
  const submissions = (workflow.assignments || []).filter((assignment) =>
    assignment?.workReport || assignment?.workLink || assignment?.workFile?.url || assignment?.rejectionReason);
  const generated = submissions.map((assignment) => {
    const lines = [`${assignment.assigneeName || "Team member"} — ${_tmStatusLabel(assignment.status)}`];
    if (assignment.workReport) lines.push(assignment.workReport);
    if (assignment.rejectionReason) lines.push(`Rejected reason: ${assignment.rejectionReason}`);
    if (assignment.workLink) lines.push(`Work link: ${assignment.workLink}`);
    if (assignment.workFile?.url) lines.push(`Work file: ${assignment.workFile.name || "Open work file"} — ${assignment.workFile.url}`);
    return lines.join("\n");
  }).join("\n\n");
  return [manual, generated ? `${startMarker}\n${generated}\n${endMarker}` : ""].filter(Boolean).join("\n\n");
}

function _tmLatestTeamWorkAsset(workflow = {}, field = "") {
  const sorted = (workflow.assignments || []).slice().sort((a, b) =>
    String(b?.updatedAt || b?.createdAt || "").localeCompare(String(a?.updatedAt || a?.createdAt || "")));
  return sorted.find((assignment) => field === "file" ? assignment?.workFile?.url : assignment?.workLink) || null;
}

function _tmAssignmentPrerequisites(workflow = {}, assignment = {}) {
  const assignmentId = String(assignment?.id || "");
  const predecessorIds = (workflow.edges || [])
    .filter((edge) => String(edge?.to || "") === assignmentId)
    .map((edge) => String(edge?.from || ""))
    .filter(Boolean);
  if (!predecessorIds.length) return [];
  const byId = new Map((workflow.assignments || []).map((item) => [String(item.id), item]));
  return predecessorIds.map((id) => byId.get(id)).filter(Boolean);
}

app.post("/api/task-management", requireAuth, requirePage("Delegated Tasks"), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    if (!supabaseDb.isConfigured()) return res.status(503).json({ ok: false, error: "Supabase is not configured." });

    const title = _tmText(req.body?.title, 500);
    const description = _tmText(req.body?.description, 8000);
    const rawPriority = _tmText(req.body?.priority, 30);
    const priority = _tmPriority(rawPriority);
    const dueDate = _tmDate(req.body?.dueDate);
    const plan = _tmBuildWorkflowPlan(req.body?.sections, req.body?.edges);
    const sections = plan.sections;
    const edges = plan.edges;

    if (!title) return res.status(400).json({ ok: false, error: "Project title is required." });
    if (!["urgent", "high", "normal", "low"].includes(rawPriority.toLowerCase())) return res.status(400).json({ ok: false, error: "Project priority is required." });
    if (!dueDate) return res.status(400).json({ ok: false, error: "Project target date is required." });
    if (!sections.length) return res.status(400).json({ ok: false, error: "Add at least one workflow block." });
    const invalid = sections.find((section) => !section.department || !section.request || !section.deliveryDate);
    if (invalid) return res.status(400).json({ ok: false, error: "Each workflow block requires a department, requested action, and delivery date." });
    const lateSection = sections.find((section) => section.deliveryDate > dueDate);
    if (lateSection) return res.status(400).json({ ok: false, error: "A workflow block delivery date cannot be after the project target date." });

    const currentUser = await _tmCurrentMember(req);
    const created = await supabaseDb.insert(_tmTicketsTable(), {
      title,
      description: description || null,
      priority,
      due_date: dueDate,
      status: "not_started",
      created_by_id: currentUser.id || null,
      created_by_name: currentUser.name || null,
    });
    const ticketId = _tmId(created);
    if (!ticketId) throw new Error("Project was created without an ID.");

    try {
      const createdSectionIds = new Map();
      for (const section of sections) {
        const sectionPayload = {
          ticket_id: ticketId,
          department: section.department,
          request_text: section.request,
          details: section.details || null,
          delivery_date: section.deliveryDate || null,
          sort_order: section.sortOrder,
          execution_group: section.executionGroup,
          canvas_x: section.canvasX || null,
          canvas_y: section.canvasY || null,
          status: "not_started",
        };
        Object.assign(sectionPayload, _tmAttachmentColumns(section.attachments || section.attachment));
        const createdSection = await supabaseDb.insert(_tmSectionsTable(), sectionPayload);
        const createdId = _tmId(createdSection);
        if (!createdId) throw new Error("Workflow block was created without an ID.");
        createdSectionIds.set(section.clientId, createdId);
      }
      for (const edge of edges) {
        const fromSectionId = createdSectionIds.get(edge.from);
        const toSectionId = createdSectionIds.get(edge.to);
        if (!fromSectionId || !toSectionId) throw new Error("Workflow arrow could not be linked to its blocks.");
        await supabaseDb.insert(_tmEdgesTable(), {
          ticket_id: ticketId,
          from_section_id: fromSectionId,
          to_section_id: toSectionId,
        });
      }
    } catch (sectionError) {
      // Cascading deletion keeps sections and workflow arrows from being orphaned.
      await supabaseDb.deleteById(_tmTicketsTable(), ticketId).catch(() => null);
      throw sectionError;
    }

    const ticket = await _tmLoadTicketById(ticketId);
    return res.status(201).json({ ok: true, ticket });
  } catch (error) {
    console.error("[task-management] create error:", error?.details || error?.message || error);
    const detail = String(error?.message || "");
    const message = /delivery_date.*schema cache|Could not find the .*delivery_date/i.test(detail)
      ? "The workflow block delivery-date column is not installed. Run the supplied delivery-date SQL migration, then refresh this page."
      : (/(attachments|attachment_(name|url|type|size)).*schema cache|Could not find the .*(attachments|attachment_)/i.test(detail)
        ? "Task Management multi-attachment columns are not installed. Run the supplied multi-attachments SQL migration, then refresh this page."
        : (/relation .* does not exist|Could not find the table|schema cache/i.test(detail)
          ? "Task Management workflow tables are not installed. Run the supplied Supabase SQL migration, then refresh this page."
          : (error?.message || "Failed to create project.")));
    return res.status(error?.status || 500).json({ ok: false, error: message });
  }
});



app.post("/api/task-management/:id/mark-delivered", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    if (req.taskManagementView !== "delegated") {
      return res.status(403).json({ ok: false, error: "Projects can be marked as delivered from Delegated Tasks only." });
    }
    const ticketId = String(req.params.id || "").trim();
    const ticket = await _tmLoadTicketById(ticketId);
    if (!ticket) return res.status(404).json({ ok: false, error: "Project not found." });
    const currentUser = await _tmCurrentMember(req);
    if (!_tmSameMember(ticket, currentUser) && !_taskManagementViewIsAdmin(req, "delegated")) {
      return res.status(403).json({ ok: false, error: "Only the project creator or an admin can mark it as delivered." });
    }
    if (ticket.isArchived) {
      return res.status(409).json({ ok: false, error: "Unarchive this project before marking it as delivered." });
    }

    const now = new Date().toISOString();
    const sectionIds = (ticket.sections || []).map((section) => String(section.id || "")).filter(Boolean);
    if (sectionIds.length) {
      await supabaseDb.updateByIds(_tmSectionsTable(), sectionIds, {
        status: "completed",
        completed_at: now,
        completed_by_id: currentUser.id || null,
        completed_by_name: currentUser.name || null,
        updated_at: now,
      });

      const assignmentGroups = await Promise.all(sectionIds.map((sectionId) => supabaseDb.select(_tmAssignmentsTable(), {
        select: "id,section_id,status",
        section_id: `eq.${_sbRestFilterValue(sectionId)}`,
        limit: 1000,
        order: "id.asc",
      })));
      const assignmentIds = assignmentGroups.flat()
        .map((row) => String(_sbGet(row, ["id", "ID"]) || ""))
        .filter(Boolean);
      if (assignmentIds.length) {
        await supabaseDb.updateByIds(_tmAssignmentsTable(), assignmentIds, {
          status: "completed",
          updated_at: now,
        });
      }
    }
    await supabaseDb.updateById(_tmTicketsTable(), ticketId, { status: "completed", updated_at: now });
    const updated = await _tmLoadTicketById(ticketId);
    return res.json({ ok: true, ticket: updated });
  } catch (error) {
    console.error("[task-management] mark delivered error:", error?.details || error?.message || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to mark the project as delivered." });
  }
});

app.patch("/api/task-management/:id/archive", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    const ticketId = String(req.params.id || "").trim();
    const ticket = await _tmLoadTicketById(ticketId);
    if (!ticket) return res.status(404).json({ ok: false, error: "Project not found." });
    const currentUser = await _tmCurrentMember(req);
    const isCurrentViewAdmin = _taskManagementViewIsAdmin(req, req.taskManagementView);
    const isAvailable = _tmTicketBelongsToView(ticket, currentUser, req.taskManagementView);
    if (!isAvailable) {
      return res.status(403).json({ ok: false, error: "This project is not available in the selected Task Management view." });
    }
    let authorized = isCurrentViewAdmin;
    if (!authorized) {
      const adminPages = [_taskManagementViewAccessPage(req.taskManagementView), "Task Management"].filter(Boolean);
      authorized = await _verifyPageAdminPassword(req, req.body?.adminPassword, adminPages);
    }
    if (!authorized) return res.status(401).json({ ok: false, error: "Invalid admin password." });

    const archived = req.body?.archived !== false;
    const now = new Date().toISOString();
    try {
      await supabaseDb.updateById(_tmTicketsTable(), ticketId, {
        is_archived: archived,
        archived_at: archived ? now : null,
        archived_by_id: archived ? (currentUser.id || null) : null,
        archived_by_name: archived ? (currentUser.name || null) : null,
        archived_from_view: archived ? req.taskManagementView : null,
        updated_at: now,
      });
    } catch (error) {
      const detail = String(error?.message || "");
      if (/is_archived|archived_at|archived_by_|archived_from_view/i.test(detail)) {
        const missing = new Error("The per-user project archive fields are not installed. Run the supplied Task Management personal-archive SQL migration, then refresh the page.");
        missing.status = 503;
        throw missing;
      }
      throw error;
    }
    const updated = await _tmLoadTicketById(ticketId);
    return res.json({ ok: true, ticket: updated });
  } catch (error) {
    console.error("[task-management] archive project error:", error?.details || error?.message || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to archive the project." });
  }
});

app.delete("/api/task-management/:id", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    if (!supabaseDb.isConfigured()) return res.status(503).json({ ok: false, error: "Supabase is not configured." });
    const ticketId = String(req.params.id || "").trim();
    if (!ticketId) return res.status(400).json({ ok: false, error: "Missing project ID." });
    const ticket = await _tmLoadTicketById(ticketId);
    if (!ticket) return res.status(404).json({ ok: false, error: "Project not found." });

    const currentUser = await _tmCurrentMember(req);
    const isCurrentViewAdmin = _taskManagementViewIsAdmin(req, req.taskManagementView);
    const isAvailable = ticket.isArchived
      ? ((_tmArchivedByMember(ticket, currentUser) && _tmArchiveView(ticket) === req.taskManagementView) || isCurrentViewAdmin)
      : _tmTicketBelongsToView(ticket, currentUser, req.taskManagementView);
    if (!isAvailable) {
      return res.status(403).json({ ok: false, error: "This project is not available in the selected Task Management view." });
    }

    let authorized = isCurrentViewAdmin;
    if (!authorized) {
      const adminPages = [_taskManagementViewAccessPage(req.taskManagementView), "Task Management"].filter(Boolean);
      authorized = await _verifyPageAdminPassword(req, req.body?.adminPassword, adminPages);
    }
    if (!authorized) return res.status(401).json({ ok: false, error: "Invalid admin password." });

    // The Task Management foreign keys use cascading deletion. Removing the
    // project therefore removes its department blocks, arrows, team tasks, and
    // team-task arrows in one atomic database operation.
    await supabaseDb.deleteById(_tmTicketsTable(), ticketId);
    return res.json({ ok: true, deletedId: ticketId });
  } catch (error) {
    console.error("[task-management] delete project error:", error?.details || error?.message || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to delete project." });
  }
});

app.put("/api/task-management/:id", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    if (!supabaseDb.isConfigured()) return res.status(503).json({ ok: false, error: "Supabase is not configured." });

    const ticketId = String(req.params.id || "").trim();
    if (!ticketId) return res.status(400).json({ ok: false, error: "Missing project ID." });

    const existingTicket = await _tmLoadTicketById(ticketId);
    if (!existingTicket) return res.status(404).json({ ok: false, error: "Project not found." });

    const currentUser = await _tmCurrentMember(req);
    if (!_tmTicketBelongsToView(existingTicket, currentUser, req.taskManagementView)) {
      return res.status(403).json({ ok: false, error: "This project is not available in the selected Task Management view." });
    }

    const adminPages = [_taskManagementViewAccessPage(req.taskManagementView), "Task Management"].filter(Boolean);
    const authorized = await _verifyPageAdminPassword(req, req.body?.adminPassword, adminPages);
    if (!authorized) return res.status(401).json({ ok: false, error: "Invalid admin password." });

    const title = _tmText(req.body?.title, 500);
    const description = _tmText(req.body?.description, 8000);
    const rawPriority = _tmText(req.body?.priority, 30);
    const priority = _tmPriority(rawPriority);
    const dueDate = _tmDate(req.body?.dueDate);
    const plan = _tmBuildWorkflowPlan(req.body?.sections, req.body?.edges);
    const sections = plan.sections;
    const edges = plan.edges;

    if (!title) return res.status(400).json({ ok: false, error: "Project title is required." });
    if (!["urgent", "high", "normal", "low"].includes(rawPriority.toLowerCase())) return res.status(400).json({ ok: false, error: "Project priority is required." });
    if (!dueDate) return res.status(400).json({ ok: false, error: "Project target date is required." });
    if (!sections.length) return res.status(400).json({ ok: false, error: "Add at least one workflow block." });
    const invalid = sections.find((section) => !section.department || !section.request || !section.deliveryDate);
    if (invalid) return res.status(400).json({ ok: false, error: "Each workflow block requires a department, requested action, and delivery date." });
    const lateSection = sections.find((section) => section.deliveryDate > dueDate);
    if (lateSection) return res.status(400).json({ ok: false, error: "A workflow block delivery date cannot be after the project target date." });

    const now = new Date().toISOString();
    await supabaseDb.updateById(_tmTicketsTable(), ticketId, {
      title,
      description: description || null,
      priority,
      due_date: dueDate,
      updated_at: now,
    });

    const existingSectionsById = new Map((existingTicket.sections || []).map((section) => [String(section.id), section]));
    const resolvedSectionIds = new Map();
    const retainedSectionIds = new Set();

    for (const section of sections) {
      const sectionPayload = {
        ticket_id: ticketId,
        department: section.department,
        request_text: section.request,
        details: section.details || null,
        delivery_date: section.deliveryDate,
        sort_order: section.sortOrder,
        execution_group: section.executionGroup,
        canvas_x: section.canvasX || null,
        canvas_y: section.canvasY || null,
        ..._tmAttachmentColumns(section.attachments || section.attachment),
        updated_at: now,
      };

      const existingSection = existingSectionsById.get(String(section.clientId));
      if (existingSection) {
        await supabaseDb.updateById(_tmSectionsTable(), existingSection.id, sectionPayload);
        resolvedSectionIds.set(section.clientId, String(existingSection.id));
        retainedSectionIds.add(String(existingSection.id));
      } else {
        const createdSection = await supabaseDb.insert(_tmSectionsTable(), {
          ...sectionPayload,
          status: "not_started",
          created_at: now,
        });
        const createdId = _tmId(createdSection);
        if (!createdId) throw new Error("Workflow block was created without an ID.");
        resolvedSectionIds.set(section.clientId, createdId);
        retainedSectionIds.add(createdId);
      }
    }

    const edgeIds = (existingTicket.edges || []).map((edge) => String(edge.id || "")).filter(Boolean);
    if (edgeIds.length) await supabaseDb.deleteByIds(_tmEdgesTable(), edgeIds);

    const removedSectionIds = (existingTicket.sections || [])
      .map((section) => String(section.id || ""))
      .filter((id) => id && !retainedSectionIds.has(id));
    if (removedSectionIds.length) await supabaseDb.deleteByIds(_tmSectionsTable(), removedSectionIds);

    for (const edge of edges) {
      const fromSectionId = resolvedSectionIds.get(edge.from);
      const toSectionId = resolvedSectionIds.get(edge.to);
      if (!fromSectionId || !toSectionId) throw new Error("Workflow arrow could not be linked to its blocks.");
      await supabaseDb.insert(_tmEdgesTable(), {
        ticket_id: ticketId,
        from_section_id: fromSectionId,
        to_section_id: toSectionId,
      });
    }

    const ticket = await _tmSyncTicketStatus(ticketId) || await _tmLoadTicketById(ticketId);
    return res.json({ ok: true, ticket });
  } catch (error) {
    console.error("[task-management] update project error:", error?.details || error?.message || error);
    const detail = String(error?.message || "");
    const message = /delivery_date.*schema cache|Could not find the .*delivery_date/i.test(detail)
      ? "The workflow block delivery-date column is not installed. Run the supplied delivery-date SQL migration, then refresh this page."
      : (/(attachments|attachment_(name|url|type|size)).*schema cache|Could not find the .*(attachments|attachment_)/i.test(detail)
        ? "Task Management multi-attachment columns are not installed. Run the supplied multi-attachments SQL migration, then refresh this page."
        : (error?.message || "Failed to update project."));
    return res.status(error?.status || 500).json({ ok: false, error: message });
  }
});


app.get("/api/task-management/sections/:id/people-workflow", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    if (req.taskManagementView !== "my") return res.status(403).json({ ok: false, error: "Team assignment workflows are available from My Tasks only." });
    const sectionId = String(req.params.id || "").trim();
    const sectionRow = await supabaseDb.selectById(_tmSectionsTable(), sectionId);
    if (!sectionRow) return res.status(404).json({ ok: false, error: "Workflow section not found." });
    const ticket = await _tmLoadTicketById(_sbGet(sectionRow, ["ticket_id", "ticketId"]));
    const currentUser = await _tmCurrentMember(req);
    const section = (ticket?.sections || []).find((item) => String(item.id) === sectionId);
    if (!_tmTicketBelongsToView(ticket, currentUser, "my")) return res.status(403).json({ ok: false, error: "This project is not assigned to your department." });
    _tmAssertOwnDepartmentSection(ticket, section, currentUser);
    const [members, workflow] = await Promise.all([
      _tmMembersForDepartment(section.department),
      _tmLoadPeopleWorkflow(sectionId),
    ]);
    const visibleWorkflow = _tmWorkflowForViewer(workflow, currentUser, { revealAll: _tmCanManageDepartmentWork(req), published: _tmStatus(section?.status) === "completed" });
    return res.json({
      ok: true,
      section,
      members,
      assignments: visibleWorkflow.assignments,
      edges: visibleWorkflow.edges,
      accessLevel: req.opsPageAccessLevel || PAGE_ACCESS_LEVELS.VIEW,
    });
  } catch (error) {
    console.error("[task-management] people workflow load error:", error?.details || error?.message || error);
    return res.status(error?.status || 500).json({ ok: false, error: error?.message || "Failed to load the team workflow." });
  }
});

app.put("/api/task-management/sections/:id/people-workflow", requireAuth, requireTaskManagementView(), async (req, res) => {
  res.set("Cache-Control", "no-store");
  try {
    if (req.taskManagementView !== "my") return res.status(403).json({ ok: false, error: "Team assignment workflows are available from My Tasks only." });
    const sectionId = String(req.params.id || "").trim();
    const sectionRow = await supabaseDb.selectById(_tmSectionsTable(), sectionId);
    if (!sectionRow) return res.status(404).json({ ok: false, error: "Workflow section not found." });
    const ticket = await _tmLoadTicketById(_sbGet(sectionRow, ["ticket_id", "ticketId"]));
    const currentUser = await _tmCurrentMember(req);
    const section = (ticket?.sections || []).find((item) => String(item.id) === sectionId);
    if (!_tmTicketBelongsToView(ticket, currentUser, "my")) return res.status(403).json({ ok: false, error: "This project is not assigned to your department." });
    _tmAssertOwnDepartmentSection(ticket, section, currentUser);
    if (!_tmCanManageDepartmentWork(req)) {
      return res.status(403).json({ ok: false, error: "Edit or Admin access is required to assign tasks to team members." });
    }

    const members = await _tmMembersForDepartment(section.department);
    const membersById = new Map(members.map((member) => [String(member.id), member]));
    const plan = _tmBuildPeopleWorkflowPlan(req.body?.assignments, req.body?.edges);
    if (!plan.assignments.length) return res.status(400).json({ ok: false, error: "Add at least one person task." });
    const invalid = plan.assignments.find((assignment) => !assignment.assigneeId || !assignment.task || !assignment.deliveryDate);
    if (invalid) return res.status(400).json({ ok: false, error: "Every person task requires a team member, assigned task, and delivery date." });
    const outsideDepartment = plan.assignments.find((assignment) => !membersById.has(String(assignment.assigneeId)));
    if (outsideDepartment) return res.status(400).json({ ok: false, error: "Every selected person must belong to your department." });
    const departmentDeliveryDate = String(section?.deliveryDate || "").trim();
    const latePersonTask = departmentDeliveryDate
      ? plan.assignments.find((assignment) => String(assignment.deliveryDate || "").trim() > departmentDeliveryDate)
      : null;
    if (latePersonTask) {
      return res.status(400).json({ ok: false, error: "A personal task delivery date cannot be after its department task delivery date." });
    }

    const existing = await _tmLoadPeopleWorkflow(sectionId);
    const existingById = new Map((existing.assignments || []).map((assignment) => [String(assignment.id), assignment]));
    const retainedIds = new Set();
    const resolvedIds = new Map();
    const now = new Date().toISOString();

    for (const assignment of plan.assignments) {
      const member = membersById.get(String(assignment.assigneeId));
      const payload = {
        section_id: sectionId,
        assignee_id: String(member.id),
        assignee_name: member.name,
        task_text: assignment.task,
        details: assignment.details || null,
        delivery_date: assignment.deliveryDate,
        sort_order: assignment.sortOrder,
        execution_group: assignment.executionGroup,
        canvas_x: assignment.canvasX || null,
        canvas_y: assignment.canvasY || null,
        ..._tmAttachmentColumns(assignment.attachments || assignment.attachment),
        updated_at: now,
      };
      const previous = existingById.get(String(assignment.clientId));
      if (previous) {
        await supabaseDb.updateById(_tmAssignmentsTable(), previous.id, payload);
        retainedIds.add(String(previous.id));
        resolvedIds.set(String(assignment.clientId), String(previous.id));
      } else {
        const created = await supabaseDb.insert(_tmAssignmentsTable(), {
          ...payload,
          status: "not_started",
          created_at: now,
        });
        const createdId = _tmId(created);
        if (!createdId) throw new Error("Person task was created without an ID.");
        retainedIds.add(createdId);
        resolvedIds.set(String(assignment.clientId), createdId);
      }
    }

    const oldEdgeIds = (existing.edges || []).map((edge) => String(edge.id || "")).filter(Boolean);
    if (oldEdgeIds.length) await supabaseDb.deleteByIds(_tmAssignmentEdgesTable(), oldEdgeIds);
    const removedIds = (existing.assignments || []).map((assignment) => String(assignment.id || "")).filter((id) => id && !retainedIds.has(id));
    if (removedIds.length) await supabaseDb.deleteByIds(_tmAssignmentsTable(), removedIds);

    for (const edge of plan.edges) {
      const fromId = resolvedIds.get(String(edge.from));
      const toId = resolvedIds.get(String(edge.to));
      if (!fromId || !toId) throw new Error("A team workflow arrow could not be linked to its person tasks.");
      await supabaseDb.insert(_tmAssignmentEdgesTable(), {
        section_id: sectionId,
        from_assignment_id: fromId,
        to_assignment_id: toId,
        created_at: now,
      });
    }

    // Creating or saving at least one team-member subtask means the department
    // has started working on this section. Move the parent section to In progress
    // automatically, while preserving terminal/review statuses.
    let sectionStatus = _tmStatus(section?.status);
    if (plan.assignments.length && sectionStatus === "not_started") {
      sectionStatus = "in_progress";
      await supabaseDb.updateById(_tmSectionsTable(), sectionId, {
        status: sectionStatus,
        updated_at: now,
      });
      await _tmSyncTicketStatus(ticket.id);
    }

    const saved = await _tmLoadPeopleWorkflow(sectionId);
    const visibleWorkflow = _tmWorkflowForViewer(saved, currentUser, { revealAll: _tmCanManageDepartmentWork(req), published: sectionStatus === "completed" });
    return res.json({ ok: true, members, sectionStatus, assignments: visibleWorkflow.assignments, edges: visibleWorkflow.edges });
  } catch (error) {
    console.error("[task-management] people workflow save error:", error?.details || error?.message || error);
    const detail = String(error?.message || "");
    const message = /(attachments).*schema cache|Could not find the .*attachments/i.test(detail)
      ? "The team-task multi-attachment column is not installed. Run the supplied multi-attachments SQL migration, then refresh this page."
      : (/relation .* does not exist|Could not find the table|schema cache/i.test(detail)
        ? "The My Tasks team-workflow tables are not installed. Run the supplied My Tasks SQL migration, then refresh this page."
        : (error?.message || "Failed to save the team workflow."));
    return res.status(error?.status || 500).json({ ok: false, error: message });
  }
});


